@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap");
@import "./burjeel-mobile.css";

* {
  box-sizing: border-box;
  /* Elimina el highlight azul al tocar en mobile */
  -webkit-tap-highlight-color: transparent;
  /* Elimina el delay de 300ms en todos los elementos */
  touch-action: manipulation;
}

/* Portal de overlays: siempre fijo en el viewport, inmune al scroll lock del body */
#overlay-root {
  position: fixed;
  top: 0;
  left: 0;
  width: 0;
  height: 0;
  z-index: 99999;
  pointer-events: none;
}

#overlay-root > * {
  pointer-events: auto;
}

html {
  /* Scroll suave nativo */
  scroll-behavior: smooth;
  /* Evita el bounce del scroll en iOS a nivel raíz */
  overscroll-behavior: none;
  height: 100%;
}

body {
  /* Evita el scroll bouncing en iOS */
  overscroll-behavior: none;
  height: 100%;
  /* Optimiza el rendering para animaciones */
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeSpeed;
}

/* Sin selección de texto en elementos de navegación */
.sidebar,
.sidebar-link,
.sidebar-nav,
.topbar,
.appt-tabs-bar,
.appt-tab-btn,
.mobile-hero-topbar,
.mobile-action-bar,
.mobile-action-btn {
  -webkit-user-select: none;
  user-select: none;
}

/* Scroll nativo con inercia en iOS */
.main-content,
.modal-card-body,
.detail-modal-content,
.floating-form-card,
.notifications-dropdown,
.sidebar-more-menu {
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

/* Botones e inputs sin delay */
button,
a,
input,
select,
textarea,
[role="button"] {
  touch-action: manipulation;
}

:root {
  --blue: #2563eb;
  --sky: #38bdf8;
  --brand-primary: #2563eb;
  --brand-secondary: #1d4ed8;
  --brand-accent: #38bdf8;
  --brand-soft: #eff6ff;
  --brand-soft-strong: #dbeafe;
  --brand-border: #93c5fd;
  --brand-shadow: rgba(37, 99, 235, 0.24);
  --navy: #0f172a;
  --slate: #1e293b;
  --muted: #6b7280;
  --bg: #ffffff;
  --card: #ffffff;
  --shadow: 0 20px 40px rgba(15, 23, 42, 0.08);
  --radius-lg: 18px;
  --radius-full: 999px;

  /* ── Elevation / Shadow System ── */
  --shadow-xs: 0 1px 2px rgba(15, 23, 42, 0.05);
  --shadow-sm: 0 2px 6px rgba(15, 23, 42, 0.06), 0 1px 2px rgba(15, 23, 42, 0.04);
  --shadow-md: 0 4px 14px rgba(15, 23, 42, 0.08), 0 2px 6px rgba(15, 23, 42, 0.05);
  --shadow-lg: 0 8px 28px rgba(15, 23, 42, 0.10), 0 4px 10px rgba(15, 23, 42, 0.06);
  --shadow-xl: 0 16px 44px rgba(15, 23, 42, 0.12), 0 6px 16px rgba(15, 23, 42, 0.07);
  --shadow-2xl: 0 24px 60px rgba(15, 23, 42, 0.16), 0 8px 20px rgba(15, 23, 42, 0.08);
  --shadow-brand: 0 8px 24px rgba(37, 99, 235, 0.28), 0 2px 6px rgba(37, 99, 235, 0.12);
  --shadow-brand-lg: 0 14px 36px rgba(37, 99, 235, 0.32), 0 4px 10px rgba(37, 99, 235, 0.14);
  --shadow-inset: inset 0 2px 4px rgba(15, 23, 42, 0.06);

  /* ── Transition presets ── */
  --ease-out-soft: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --transition-fast: 0.15s var(--ease-out-soft);
  --transition-base: 0.25s var(--ease-out-soft);
  --transition-slow: 0.35s var(--ease-out-soft);
}

body {
  margin: 0;
  font-family: "Poppins", "Inter", system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--slate);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body.theme-dark {
  --bg: #0b1120;
  --card: #0f172a;
  --slate: #e2e8f0;
  --muted: #94a3b8;
  --navy: #e2e8f0;

  /* Dark mode shadow/elevation system */
  --shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.2);
  --shadow-sm: 0 2px 6px rgba(0, 0, 0, 0.25), 0 1px 2px rgba(0, 0, 0, 0.15);
  --shadow-md: 0 4px 14px rgba(0, 0, 0, 0.3), 0 2px 6px rgba(0, 0, 0, 0.2);
  --shadow-lg: 0 8px 28px rgba(0, 0, 0, 0.35), 0 4px 10px rgba(0, 0, 0, 0.2);
  --shadow-xl: 0 16px 44px rgba(0, 0, 0, 0.4), 0 6px 16px rgba(0, 0, 0, 0.25);
  --shadow-2xl: 0 24px 60px rgba(0, 0, 0, 0.5), 0 8px 20px rgba(0, 0, 0, 0.3);
  --shadow-brand: 0 8px 24px rgba(37, 99, 235, 0.35), 0 2px 6px rgba(37, 99, 235, 0.15);
  --shadow-brand-lg: 0 14px 36px rgba(37, 99, 235, 0.4), 0 4px 10px rgba(37, 99, 235, 0.18);
  --shadow-inset: inset 0 2px 4px rgba(0, 0, 0, 0.15);

  background: var(--bg);
  color: var(--slate);
}

body.theme-dark .sidebar {
  background: linear-gradient(180deg, #0f172a 0%, #0b1224 100%);
  border-right: 1px solid rgba(30, 41, 59, 0.6);
  box-shadow: 4px 0 24px rgba(0, 0, 0, 0.3), 1px 0 4px rgba(0, 0, 0, 0.15);
}

body.theme-dark .sidebar-brand {
  border-bottom-color: #1e293b;
}

body.theme-dark .sidebar-footer {
  border-top-color: #1e293b;
}

.theme-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.65rem 0.75rem;
  border-radius: 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  color: #0f172a;
  cursor: pointer;
  font-weight: 600;
  font-size: 0.85rem;
}

.theme-toggle:hover {
  border-color: #cbd5e1;
  background: #f1f5f9;
}

.theme-toggle-label {
  line-height: 1;
}

.theme-switch {
  width: 46px;
  height: 26px;
  border-radius: 999px;
  background: linear-gradient(135deg, #cbd5f5, #bae6fd);
  position: relative;
  transition: all 0.25s ease;
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.12);
  flex-shrink: 0;
}

.theme-switch-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #fff;
  position: absolute;
  top: 2px;
  left: 2px;
  transition: transform 0.25s ease, background 0.25s ease;
  box-shadow: 0 6px 15px rgba(15, 23, 42, 0.2);
}

.theme-switch.is-dark {
  background: linear-gradient(135deg, #1f7aff, #22d3ee);
}

.theme-switch.is-dark .theme-switch-thumb {
  transform: translateX(20px);
  background: #0f172a;
  box-shadow: 0 6px 15px rgba(2, 6, 23, 0.35);
}

.sidebar:not(.expanded) .theme-toggle {
  justify-content: center;
}

.sidebar:not(.expanded) .theme-toggle-label {
  display: none;
}

body.theme-dark .theme-toggle {
  background: #0b1224;
  border-color: #1e293b;
  color: #e2e8f0;
}

body.theme-dark .theme-toggle:hover {
  background: #0f172a;
  border-color: #334155;
}

body.theme-dark .theme-switch {
  background: linear-gradient(135deg, #334155, #0f172a);
}

body.theme-dark .sidebar-link {
  color: #e2e8f0;
}

body.theme-dark .brand-wordmark-sidebar {
  color: #e2e8f0;
}

body.theme-dark .sidebar-icon {
  color: #e2e8f0;
}

body.theme-dark .sidebar-link:hover {
  background: rgba(91, 33, 182, 0.18);
}

body.theme-dark .sidebar-link.active {
  color: #ffffff;
}

body.theme-dark .sidebar-more-menu {
  background: linear-gradient(180deg, #0f172a 0%, #0b1224 100%);
  border-color: rgba(30, 41, 59, 0.5);
  box-shadow: var(--shadow-xl);
}

body.theme-dark .sidebar-menu-link {
  background: #0b1224;
  border-color: #1e293b;
  color: #e2e8f0;
}

body.theme-dark .sidebar-menu-link.active {
  color: #0b1120;
}

/* Landing v2 */
.lp-page {
  background: #fafaf8;
  color: #1c1c1e;
}

.lp-navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(250, 250, 248, 0.92);
  backdrop-filter: blur(20px);
  border-bottom: 1px solid #e8e6df;
}

.lp-navbar-inner,
.lp-section-inner,
.lp-hero-inner,
.lp-ai-inner,
.lp-footer-inner {
  width: min(1200px, calc(100% - 3rem));
  margin: 0 auto;
}

.lp-navbar-inner {
  min-height: 64px;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.lp-nav-logo,
.lp-footer-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.7rem;
  text-decoration: none;
}

.brand-wordmark {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  font-family: "Poppins", "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: inherit;
}

.brand-wordmark-full,
.brand-wordmark-compact {
  display: inline-block;
  line-height: 1;
}

.brand-wordmark-compact {
  display: none;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.lp-nav-logo-name {
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #1c1c1e;
}

.lp-nav-links {
  display: flex;
  align-items: center;
  gap: 1.75rem;
  margin: 0 auto;
}

.lp-nav-link {
  appearance: none;
  background: transparent;
  border: 0;
  padding: 0;
  font-size: 0.88rem;
  font-weight: 500;
  color: #4a4a52;
  text-decoration: none;
  cursor: pointer;
  transition: color 0.2s ease, transform 0.2s ease;
}

.lp-nav-link:hover {
  color: #2563eb;
}

.lp-nav-link.active {
  color: #2563eb;
  font-weight: 700;
}

.lp-nav-link.active::after {
  content: "";
  display: block;
  width: 100%;
  height: 2px;
  margin-top: 0.28rem;
  border-radius: 999px;
  background: linear-gradient(90deg, #30d7ff 0%, #1f7aff 100%);
}

.lp-nav-right,
.lp-hero-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.lp-theme-toggle {
  width: auto;
  min-width: 134px;
  padding: 0.58rem 0.78rem;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.72);
  border-color: #d8dee8;
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.06);
}

.lp-theme-toggle:hover {
  background: #ffffff;
  border-color: #c9d3e4;
}

.lp-btn-ghost,
.lp-btn-primary,
.lp-btn-secondary,
.lp-btn-hero,
.lp-price-btn-primary,
.lp-price-btn-ghost,
.lp-cta-btn {
  text-decoration: none;
  font-family: inherit;
  transition: all 0.18s ease;
}

.lp-btn-ghost,
.lp-btn-secondary,
.lp-price-btn-ghost {
  font-size: 0.88rem;
  font-weight: 600;
  padding: 0.68rem 1.12rem;
  border-radius: 12px;
  border: 1px solid #e8e6df;
  background: transparent;
  color: #1c1c1e;
}

.lp-btn-ghost:hover,
.lp-btn-secondary:hover,
.lp-price-btn-ghost:hover {
  background: #ffffff;
  border-color: #cfcac0;
}

.lp-btn-primary,
.lp-price-btn-primary {
  font-size: 0.88rem;
  font-weight: 700;
  padding: 0.72rem 1.2rem;
  border-radius: 12px;
  background: #2563eb;
  color: #fff;
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.25);
}

.lp-btn-primary:hover,
.lp-price-btn-primary:hover {
  background: #1d4ed8;
}

.lp-hero {
  min-height: calc(100vh - 64px);
  display: flex;
  align-items: center;
  padding: 5rem 0;
  position: relative;
  overflow: hidden;
  background: linear-gradient(160deg, #fafaf8 40%, #eef3fd 100%);
}

.lp-hero::before,
.lp-hero::after {
  content: "";
  position: absolute;
  border-radius: 999px;
  pointer-events: none;
}

.lp-hero::before {
  top: -120px;
  right: -120px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.1) 0%, transparent 65%);
}

.lp-hero::after {
  bottom: -80px;
  left: 20%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(37, 99, 235, 0.07) 0%, transparent 65%);
}

.lp-hero-inner,
.lp-ai-inner {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4rem;
  align-items: center;
  position: relative;
  z-index: 1;
}

.lp-hero-pill,
.lp-section-eyebrow,
.lp-ai-eyebrow,
.lp-cta-eyebrow {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.lp-hero-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.36rem 0.9rem 0.36rem 0.5rem;
  border-radius: 999px;
  background: #eef3fd;
  border: 1px solid #c3d4fa;
  color: #2563eb;
  margin-bottom: 1.5rem;
}

.lp-hero-pill-dot {
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: #2563eb;
  display: grid;
  place-items: center;
}

.lp-hero-pill-dot svg,
.lp-btn-hero svg,
.lp-price-check svg,
.lp-cta-btn svg {
  width: 10px;
  height: 10px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.lp-hero-pill-dot svg {
  color: #fff;
}

.lp-hero-title,
.lp-section-title,
.lp-ai-title,
.lp-cta-inner h2 {
  font-family: "Poppins", sans-serif;
  letter-spacing: -0.03em;
}

.lp-hero-title {
  display: grid;
  gap: 0.25rem;
  margin: 0 0 1.25rem;
  font-size: clamp(2.9rem, 5vw, 4.4rem);
  line-height: 0.98;
  color: #1c1c1e;
}

.lp-hero-title span {
  color: #2563eb;
}

.lp-hero-desc,
.lp-section-sub,
.lp-ai-desc,
.lp-cta-inner p {
  font-size: 1rem;
  line-height: 1.7;
  color: #4a4a52;
  font-weight: 300;
}

.lp-hero-desc {
  max-width: 32rem;
  margin-bottom: 2rem;
}

.lp-hero-desc strong {
  color: #1c1c1e;
  font-weight: 700;
}

.lp-btn-hero,
.lp-cta-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  background: #2563eb;
  color: #fff;
  padding: 0.9rem 1.6rem;
  border-radius: 14px;
  font-size: 0.95rem;
  font-weight: 700;
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.3);
}

.lp-btn-hero:hover,
.lp-cta-btn:hover {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.lp-hero-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.lp-hero-stat {
  padding: 0 1.4rem;
  border-right: 1px solid #e8e6df;
}

.lp-hero-stat:first-child {
  padding-left: 0;
}

.lp-hero-stat:last-child {
  border-right: 0;
}

.lp-hero-stat strong {
  display: block;
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #2563eb;
}

.lp-hero-stat span {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.76rem;
  color: #8a8a8e;
}

.lp-hero-mockup {
  background: #fff;
  border: 1px solid #e8e6df;
  border-radius: 22px;
  overflow: hidden;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.1), 0 0 0 1px rgba(0, 0, 0, 0.04);
  animation: lpFloat 6s ease-in-out infinite;
}

@keyframes lpFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}

.lp-mockup-bar,
.lp-ai-chat-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.85rem 1rem;
}

.lp-mockup-bar {
  background: #f5f4f0;
  border-bottom: 1px solid #e8e6df;
}

.lp-mockup-dots,
.lp-ai-chat-dots {
  display: inline-flex;
  gap: 0.32rem;
}

.lp-mockup-dots span,
.lp-ai-chat-dots span {
  width: 10px;
  height: 10px;
  border-radius: 999px;
}

.is-red { background: #ff5f57; }
.is-yellow { background: #febc2e; }
.is-green { background: #28c840; }

.lp-mockup-title,
.lp-ai-chat-title {
  font-size: 0.78rem;
  font-weight: 600;
}

.lp-mockup-title {
  color: #4a4a52;
}

.lp-mockup-tag,
.lp-ai-chat-tag {
  margin-left: auto;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 700;
}

.lp-mockup-tag {
  padding: 0.18rem 0.6rem;
  background: #eef3fd;
  color: #2563eb;
  border: 1px solid #c3d4fa;
}

.lp-mockup-body {
  padding: 1rem;
}

.lp-mockup-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.82rem 0.9rem;
  border-radius: 14px;
  border: 1px solid #e8e6df;
  background: #fafaf8;
  margin-bottom: 0.55rem;
}

.lp-mockup-row strong,
.lp-feature-card h3,
.lp-more-card h3,
.lp-price-plan,
.lp-price-features li,
.lp-ai-feature strong {
  color: #1c1c1e;
}

.lp-mockup-row strong {
  display: block;
  font-size: 0.84rem;
}

.lp-mockup-row small {
  display: block;
  margin-top: 0.14rem;
  font-size: 0.72rem;
  color: #8a8a8e;
}

.lp-tag {
  flex-shrink: 0;
  padding: 0.22rem 0.58rem;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 700;
}

.lp-tag.is-blue { background: #eef3fd; color: #2563eb; border: 1px solid #c3d4fa; }
.lp-tag.is-red { background: #fef0f0; color: #dc2626; border: 1px solid #fbc8c8; }
.lp-tag.is-gray { background: #f5f4f0; color: #6b6b72; border: 1px solid #e8e6df; }
.lp-tag.is-green { background: #edfaf2; color: #16a34a; border: 1px solid #bbf0d2; }

.lp-section,
.lp-pricing-section,
.lp-ai-section {
  padding: 6rem 0;
}

#features.lp-section,
#ia.lp-ai-section,
#planes.lp-pricing-section {
  scroll-margin-top: 88px;
}

.lp-section-surface {
  background: #fff;
}

.lp-section-eyebrow,
.lp-section-title,
.lp-section-sub {
  text-align: center;
}

.lp-section-eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  color: #2563eb;
  margin-bottom: 0.75rem;
}

.lp-section-eyebrow span,
.lp-ai-eyebrow span {
  width: 20px;
  height: 1px;
  background: currentColor;
}

.lp-section-title {
  font-size: clamp(2.1rem, 4vw, 3rem);
  line-height: 1.18;
  margin: 0 0 0.7rem;
}

.lp-section-title em,
.lp-ai-title em,
.lp-cta-inner h2 em {
  color: #2563eb;
  font-style: normal;
}

.lp-section-sub {
  max-width: 34rem;
  margin: 0 auto 3.5rem;
  color: #8a8a8e;
}

.lp-feature-grid,
.lp-more-grid {
  display: grid;
  gap: 1rem;
}

.lp-feature-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.lp-feature-card,
.lp-more-card,
.lp-price-card,
.lp-ai-chat {
  position: relative;
  overflow: hidden;
}

.lp-feature-card,
.lp-more-card,
.lp-price-card {
  background: #fff;
  border: 1px solid #e8e6df;
}

.lp-feature-card {
  border-radius: 18px;
  padding: 1.5rem;
}

.lp-feature-card:hover,
.lp-more-card:hover,
.lp-price-card:hover {
  border-color: #c3d4fa;
  box-shadow: 0 8px 28px rgba(37, 99, 235, 0.08);
  transform: translateY(-3px);
}

.lp-feature-line {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
}

.lp-feature-line.tone-blue { background: linear-gradient(90deg, #2563eb, #6366f1); }
.lp-feature-line.tone-teal { background: linear-gradient(90deg, #0d9488, #16a34a); }
.lp-feature-line.tone-amber { background: linear-gradient(90deg, #d97706, #dc2626); }
.lp-feature-line.tone-violet { background: linear-gradient(90deg, #7c3aed, #a78bfa); }

.lp-feature-icon {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  margin-bottom: 1rem;
}

.lp-feature-icon svg {
  width: 18px;
  height: 18px;
}

.lp-feature-icon.tone-blue { background: #eef3fd; color: #2563eb; }
.lp-feature-icon.tone-teal { background: #edfafa; color: #0d9488; }
.lp-feature-icon.tone-amber { background: #fef7ec; color: #d97706; }
.lp-feature-icon.tone-violet { background: #f4f0fd; color: #7c3aed; }

.lp-feature-card h3,
.lp-more-card h3 {
  font-size: 0.95rem;
  margin: 0 0 0.38rem;
}

.lp-feature-card p,
.lp-more-card p,
.lp-price-subtitle,
.lp-footer-copy,
.lp-footer-brand span {
  font-size: 0.82rem;
  color: #8a8a8e;
  line-height: 1.6;
}

.lp-more-block {
  margin-top: 3rem;
}

.lp-more-kicker {
  margin: 0 0 1rem;
  text-align: center;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #8a8a8e;
}

.lp-more-grid {
  grid-template-columns: repeat(6, minmax(0, 1fr));
}

.lp-more-card {
  border-radius: 14px;
  padding: 1.1rem 1rem;
}

.lp-ai-section {
  background: linear-gradient(160deg, #0d0f14 0%, #13161d 60%, #1a1340 100%);
}

.lp-ai-eyebrow {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: #818cf8;
  margin-bottom: 0.85rem;
}

.lp-ai-title {
  font-size: clamp(2.2rem, 4vw, 3.2rem);
  line-height: 1.1;
  color: #f0eee8;
  margin: 0 0 1rem;
}

.lp-ai-desc {
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 2rem;
}

.lp-ai-feature-list {
  display: grid;
  gap: 1rem;
}

.lp-ai-feature {
  display: flex;
  align-items: flex-start;
  gap: 0.8rem;
}

.lp-ai-feature-icon {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  background: rgba(99, 102, 241, 0.15);
  border: 1px solid rgba(99, 102, 241, 0.25);
  color: #818cf8;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.lp-ai-feature-icon svg {
  width: 14px;
  height: 14px;
}

.lp-ai-feature strong {
  display: block;
  margin-bottom: 0.18rem;
  color: #f0eee8;
  font-size: 0.9rem;
}

.lp-ai-feature p {
  margin: 0;
  color: rgba(255, 255, 255, 0.45);
  font-size: 0.78rem;
  line-height: 1.6;
}

.lp-ai-chat {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 22px;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.4);
}

.lp-ai-chat-bar {
  background: rgba(255, 255, 255, 0.05);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.lp-ai-chat-title {
  color: rgba(255, 255, 255, 0.6);
}

.lp-ai-chat-tag {
  padding: 0.18rem 0.52rem;
  background: rgba(99, 102, 241, 0.2);
  color: #818cf8;
  border: 1px solid rgba(99, 102, 241, 0.3);
}

.lp-ai-messages {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  padding: 1.1rem;
}

.lp-ai-msg {
  max-width: 85%;
  padding: 0.72rem 0.9rem;
  border-radius: 14px;
  font-size: 0.82rem;
  line-height: 1.6;
}

.lp-ai-msg.is-ai {
  align-self: flex-start;
  background: rgba(255, 255, 255, 0.07);
  color: rgba(255, 255, 255, 0.8);
  border-radius: 4px 14px 14px 14px;
}

.lp-ai-msg.is-user {
  align-self: flex-end;
  background: rgba(99, 102, 241, 0.25);
  border: 1px solid rgba(99, 102, 241, 0.3);
  color: rgba(255, 255, 255, 0.9);
  border-radius: 14px 4px 14px 14px;
}

.lp-ai-chip-row {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  padding: 0 1.1rem 1.1rem;
}

.lp-ai-chip {
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.6);
  padding: 0.34rem 0.75rem;
  font-size: 0.72rem;
  font-weight: 600;
}

.lp-ai-chip:hover {
  background: rgba(99, 102, 241, 0.2);
  border-color: rgba(99, 102, 241, 0.3);
  color: #818cf8;
}

.lp-billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 3rem;
}

.lp-billing-toggle > span {
  font-size: 0.88rem;
  color: #8a8a8e;
}

.lp-billing-toggle > span.is-active {
  color: #1c1c1e;
  font-weight: 600;
}

.lp-billing-switch {
  position: relative;
  width: 44px;
  height: 24px;
  border-radius: 999px;
  background: #c3d4fa;
  padding: 3px;
}

.lp-billing-switch.is-yearly {
  background: #2563eb;
}

.lp-billing-thumb {
  display: block;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
  transition: transform 0.18s ease;
}

.lp-billing-switch.is-yearly .lp-billing-thumb {
  transform: translateX(20px);
}

.lp-billing-badge {
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  background: #edfaf2;
  border: 1px solid #bbf0d2;
  color: #16a34a;
  font-size: 0.72rem;
  font-weight: 700;
}

.lp-pricing-grid {
  max-width: 960px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1.08fr 1fr;
  gap: 1.25rem;
  align-items: start;
}

.lp-price-card {
  border-radius: 22px;
  padding: 1.9rem;
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.lp-price-card.is-featured {
  border-color: #2563eb;
  box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.08), 0 16px 48px rgba(37, 99, 235, 0.15);
}

.lp-price-rec {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  padding: 0.25rem 0.95rem;
  border-radius: 0 0 10px 10px;
  background: #16a34a;
  color: #fff;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.lp-price-plan {
  margin-bottom: 0.5rem;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #8a8a8e;
}

.lp-price-amount {
  font-family: "Poppins", sans-serif;
  font-size: 2.1rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #2563eb;
  line-height: 1.05;
}

.lp-price-amount.is-free {
  color: #16a34a;
}

.lp-price-period {
  margin-top: 0.35rem;
  font-size: 0.82rem;
  color: #8a8a8e;
}

.lp-price-subtitle {
  margin: 0.4rem 0 1.3rem;
}

.lp-price-divider {
  height: 1px;
  background: #e8e6df;
  margin-bottom: 1.2rem;
}

.lp-price-features {
  list-style: none;
  display: grid;
  gap: 0.68rem;
  margin: 0 0 1.6rem;
}

.lp-price-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  font-size: 0.84rem;
  line-height: 1.45;
  color: #4a4a52;
}

.lp-price-check {
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: #edfaf2;
  display: grid;
  place-items: center;
  color: #16a34a;
  flex-shrink: 0;
  margin-top: 0.08rem;
}

.lp-price-btn-primary,
.lp-price-btn-ghost {
  display: block;
  width: 100%;
  text-align: center;
}

.lp-price-btn-primary {
  margin-bottom: 0.7rem;
}

.lp-cta-section {
  padding: 3rem 0 6rem;
}

.lp-cta-inner {
  width: min(1200px, calc(100% - 3rem));
  margin: 0 auto;
  padding: 5rem 4rem;
  border-radius: 28px;
  text-align: center;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #1e3a5f 0%, #1e2454 50%, #2d1e54 100%);
}

.lp-cta-inner::before,
.lp-cta-inner::after {
  content: "";
  position: absolute;
  border-radius: 999px;
}

.lp-cta-inner::before {
  top: -60px;
  right: -60px;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.2) 0%, transparent 70%);
}

.lp-cta-inner::after {
  bottom: -80px;
  left: -40px;
  width: 250px;
  height: 250px;
  background: radial-gradient(circle, rgba(37, 99, 235, 0.15) 0%, transparent 70%);
}

.lp-cta-eyebrow {
  color: rgba(255, 255, 255, 0.45);
  margin-bottom: 0.8rem;
  position: relative;
  z-index: 1;
}

.lp-cta-inner h2 {
  position: relative;
  z-index: 1;
  font-size: clamp(2.2rem, 4vw, 3.4rem);
  line-height: 1.08;
  color: #fff;
  margin: 0 0 0.9rem;
}

.lp-cta-inner h2 em {
  color: #93c5fd;
}

.lp-cta-inner p {
  position: relative;
  z-index: 1;
  max-width: 32rem;
  margin: 0 auto 2rem;
  color: rgba(255, 255, 255, 0.55);
}

.lp-cta-btn {
  position: relative;
  z-index: 1;
  background: #fff;
  color: #2563eb;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
}

.lp-cta-btn svg {
  color: #2563eb;
  width: 14px;
  height: 14px;
}

.lp-footer {
  background: #fff;
  border-top: 1px solid #e8e6df;
  padding: 2rem 0;
}

.lp-footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.lp-footer-brand strong {
  display: block;
  font-size: 0.9rem;
}

.lp-footer-brand span {
  display: block;
  margin-top: 0.15rem;
}

.lp-anim {
  opacity: 0;
  animation: lpFadeUp 0.6s ease forwards;
}

.lp-anim-d1 { animation-delay: 0.05s; }
.lp-anim-d2 { animation-delay: 0.12s; }
.lp-anim-d3 { animation-delay: 0.18s; }
.lp-anim-d4 { animation-delay: 0.24s; }
.lp-anim-d5 { animation-delay: 0.3s; }

@keyframes lpFadeUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

body.theme-dark .lp-page,
body.theme-dark .lp-pricing-section {
  background: #0b1120;
}

body.theme-dark .lp-navbar,
body.theme-dark .lp-footer,
body.theme-dark .lp-section-surface,
body.theme-dark .lp-price-card,
body.theme-dark .lp-feature-card,
body.theme-dark .lp-more-card,
body.theme-dark .lp-hero-mockup {
  background: #0f172a;
  border-color: #223046;
}

body.theme-dark .lp-navbar {
  background: rgba(11, 17, 32, 0.88);
}

body.theme-dark .lp-theme-toggle {
  background: rgba(15, 23, 42, 0.84);
  border-color: #334155;
  box-shadow: 0 10px 24px rgba(2, 6, 23, 0.34);
}

body.theme-dark .lp-theme-toggle:hover {
