}

body.theme-dark .lp-feature-icon.tone-blue { background: rgba(37, 99, 235, 0.14); color: #60a5fa; }
body.theme-dark .lp-feature-icon.tone-teal { background: rgba(13, 148, 136, 0.14); color: #2dd4bf; }
body.theme-dark .lp-feature-icon.tone-amber { background: rgba(217, 119, 6, 0.14); color: #fbbf24; }
