  border-color: rgba(34, 197, 94, 0.28);
}

body.theme-dark .lp-footer {
  border-color: #223046;
}

@media (max-width: 1100px) {
  .lp-feature-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .lp-more-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .lp-pricing-grid {
    grid-template-columns: 1fr;
    max-width: 620px;
  }
}

@media (max-width: 920px) {
  .lp-navbar-inner,
  .lp-section-inner,
  .lp-hero-inner,
  .lp-ai-inner,
  .lp-footer-inner,
  .lp-cta-inner {
    width: min(100% - 1.6rem, 1200px);
  }

  .lp-hero-inner,
  .lp-ai-inner {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .lp-navbar-inner {
    flex-wrap: wrap;
    row-gap: 0.65rem;
  }

  .lp-nav-links {
    display: flex;
    order: 3;
    width: 100%;
    margin: 0;
    gap: 0.55rem;
    overflow-x: auto;
    padding: 0.15rem 0 0.1rem;
    scrollbar-width: none;
  }

  .lp-nav-links::-webkit-scrollbar {
    display: none;
  }

  .lp-nav-link {
    flex: 0 0 auto;
    min-height: 34px;
    padding: 0.45rem 0.8rem;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.7);
    border: 1px solid rgba(148, 163, 184, 0.22);
  }

  .lp-nav-link.active {
    background: rgba(37, 99, 235, 0.1);
    border-color: rgba(37, 99, 235, 0.24);
  }

  .lp-nav-link.active::after {
    display: none;
  }

  body.theme-dark .lp-nav-link {
    background: rgba(15, 23, 42, 0.84);
    border-color: #334155;
  }

  body.theme-dark .lp-nav-link.active {
    background: rgba(59, 130, 246, 0.16);
    border-color: rgba(96, 165, 250, 0.28);
  }

  .lp-hero {
    min-height: auto;
    padding: 3.6rem 0;
  }
}

@media (max-width: 640px) {
  .lp-navbar-inner {
    min-height: 60px;
    gap: 0.75rem;
    row-gap: 0.55rem;
    flex-wrap: wrap;
  }

  .lp-nav-right {
    gap: 0.45rem;
  }

  .lp-theme-toggle {
    min-width: 0;
    padding: 0.55rem 0.62rem;
  }

  .lp-theme-toggle .theme-toggle-label {
    display: none;
  }

  .lp-btn-ghost,
  .lp-btn-primary {
    padding: 0.62rem 0.82rem;
    font-size: 0.8rem;
  }

  .lp-hero-title,
  .lp-section-title,
  .lp-ai-title,
  .lp-cta-inner h2 {
    font-size: 2.2rem;
  }

  .lp-hero-desc,
  .lp-section-sub,
  .lp-ai-desc,
  .lp-cta-inner p {
    font-size: 0.92rem;
  }

  .lp-hero-actions,
  .lp-footer-inner {
    flex-direction: column;
    align-items: stretch;
  }

  .lp-btn-hero,
  .lp-btn-secondary,
  .lp-cta-btn {
    justify-content: center;
    width: 100%;
  }

  .lp-hero-stats,
  .lp-feature-grid,
  .lp-more-grid {
    grid-template-columns: 1fr;
  }

  .lp-hero-stat {
    border-right: 0;
    border-bottom: 1px solid #e8e6df;
    padding: 0.9rem 0;
  }

  .lp-hero-stat:last-child {
    border-bottom: 0;
  }

  .lp-section,
  .lp-pricing-section,
  .lp-ai-section {
    padding: 4.4rem 0;
  }

  .lp-feature-card,
  .lp-more-card,
  .lp-price-card {
    padding: 1.2rem;
  }

  .lp-billing-toggle {
    flex-wrap: wrap;
    gap: 0.55rem;
    margin-bottom: 2rem;
  }

  .lp-ai-messages,
  .lp-ai-chip-row {
    padding-left: 0.85rem;
    padding-right: 0.85rem;
  }

  .lp-ai-msg {
    max-width: 100%;
    font-size: 0.78rem;
  }

  .lp-cta-inner {
    padding: 3.4rem 1.25rem;
  }

  body.theme-dark .lp-hero-stat {
    border-color: #223046;
  }
}

/* Plans detail v2 */
