  border-bottom: 1px solid #e8e6df;
}

.pp-navbar-inner,
.pp-content,
.pp-footer-inner {
  width: min(1160px, calc(100% - 3rem));
  margin: 0 auto;
}

.pp-navbar-inner {
  min-height: 64px;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.pp-nav-logo,
.pp-footer-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  text-decoration: none;
}

.pp-nav-logo-name {
  font-size: 1.04rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #1c1c1e;
}

.pp-nav-links {
  display: flex;
  align-items: center;
  gap: 1.75rem;
  margin: 0 auto;
}

.pp-nav-link {
  font-size: 0.88rem;
  font-weight: 500;
  color: #4a4a52;
}

.pp-nav-link.is-active {
  color: #2563eb;
  font-weight: 600;
}

.pp-nav-right {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.pp-btn-ghost,
.pp-btn-primary-nav,
.pp-btn-main,
.pp-btn-secondary,
.pp-cta-main,
.pp-cta-ghost {
  font-family: inherit;
  text-decoration: none;
  transition: all 0.18s ease;
}

.pp-btn-ghost,
.pp-btn-secondary {
  border: 1px solid #e8e6df;
  border-radius: 12px;
  background: transparent;
  color: #1c1c1e;
  font-size: 0.88rem;
  font-weight: 600;
  padding: 0.65rem 1.1rem;
}

.pp-btn-ghost:hover,
.pp-btn-secondary:hover {
  background: #fff;
  border-color: #d0cec5;
