  border-bottom: 1px solid #e8e6df;
  overflow-x: auto;
}

.pp-plan-tab {
  border: 1px solid transparent;
  background: transparent;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.68rem 1rem;
  border-bottom: 2px solid transparent;
  border-radius: 10px 10px 0 0;
  color: #8a8a8e;
  font-size: 0.84rem;
  font-weight: 600;
