  gap: 0.65rem;
}

.pp-btn-main {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  padding: 0.95rem 1.4rem;
  border-radius: 14px;
}

.pp-btn-main.is-green {
  background: #16a34a;
  box-shadow: 0 6px 20px rgba(22, 163, 74, 0.25);
}

.pp-btn-main.is-green:hover {
