}

.pp-detail-note {
  text-align: center;
  font-size: 0.76rem;
  line-height: 1.5;
}

.pp-feature-section,
.pp-comparison-section,
.pp-faq-section {
  margin-bottom: 3.25rem;
}

.pp-feature-section h3,
.pp-comparison-section h3,
.pp-faq-section h3 {
  margin: 0 0 1.5rem;
  font-size: 1.7rem;
}

.pp-feature-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.9rem;
}

.pp-feature-card {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  padding: 1.35rem;
  background: #fff;
  border: 1px solid #e8e6df;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}

.pp-feature-card:hover {
  border-color: #c3d4fa;
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.07);
  transform: translateY(-2px);
}

.pp-feature-line {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
}

.pp-feature-line.tone-green { background: linear-gradient(90deg, #16a34a, #34d399); }
.pp-feature-line.tone-blue { background: linear-gradient(90deg, #2563eb, #6366f1); }
.pp-feature-line.tone-amber { background: linear-gradient(90deg, #d97706, #f59e0b); }
.pp-feature-line.tone-red { background: linear-gradient(90deg, #dc2626, #f87171); }
.pp-feature-line.tone-violet { background: linear-gradient(90deg, #7c3aed, #a78bfa); }
.pp-feature-line.tone-teal { background: linear-gradient(90deg, #0d9488, #34d399); }
.pp-feature-line.tone-indigo { background: linear-gradient(90deg, #6366f1, #818cf8); }

.pp-feature-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  margin-bottom: 0.8rem;
}

.pp-feature-icon svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.pp-feature-icon.tone-green { background: #edfaf2; color: #16a34a; }
.pp-feature-icon.tone-blue { background: #eef3fd; color: #2563eb; }
.pp-feature-icon.tone-amber { background: #fef7ec; color: #d97706; }
.pp-feature-icon.tone-red { background: #fef0f0; color: #dc2626; }
.pp-feature-icon.tone-violet { background: #f4f0fd; color: #7c3aed; }
.pp-feature-icon.tone-teal { background: #edfafa; color: #0d9488; }
.pp-feature-icon.tone-indigo { background: #f0f1fe; color: #6366f1; }

.pp-feature-card h4 {
  margin: 0 0 0.35rem;
  font-size: 0.9rem;
}

.pp-feature-card p {
