  color: #8a8a8e;
  font-size: 0.8rem;
  line-height: 1.6;
}

.pp-table-wrap {
  overflow-x: auto;
  border-radius: 16px;
}

.pp-table {
  width: 100%;
  min-width: 720px;
  border-collapse: separate;
  border-spacing: 0;
  background: #fff;
  border: 1px solid #e8e6df;
  border-radius: 16px;
  overflow: hidden;
}

.pp-table th,
.pp-table td {
  padding: 0.92rem 1rem;
  border-bottom: 1px solid #e8e6df;
  text-align: center;
}

.pp-table th:first-child,
.pp-table td:first-child {
