  place-items: center;
}

.pp-check.yes {
  background: #edfaf2;
  color: #16a34a;
}

.pp-check.no {
  background: #f5f4f0;
  color: #8a8a8e;
}

.pp-cell-text {
  font-size: 0.82rem;
}

.pp-faq-list {
  display: grid;
}

.pp-faq-item {
  border-bottom: 1px solid #e8e6df;
}

.pp-faq-item:first-child {
  border-top: 1px solid #e8e6df;
}

.pp-faq-q {
  border: 0;
  background: transparent;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 0.25rem;
  color: #1c1c1e;
  font-size: 0.92rem;
