.pp-cta-bottom::before,
.pp-cta-bottom::after {
  content: "";
  position: absolute;
  border-radius: 999px;
}

.pp-cta-bottom::before {
  top: -60px;
  right: -60px;
  width: 280px;
  height: 280px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.2) 0%, transparent 70%);
}

.pp-cta-bottom::after {
