  background: radial-gradient(circle, rgba(37, 99, 235, 0.15) 0%, transparent 70%);
}

.pp-cta-eyebrow {
  color: rgba(255, 255, 255, 0.42);
  margin-bottom: 0.75rem;
  position: relative;
  z-index: 1;
}

.pp-cta-bottom h3 {
  position: relative;
  z-index: 1;
  margin: 0 0 0.75rem;
  font-size: clamp(2rem, 4vw, 3rem);
  color: #fff;
  line-height: 1.1;
}

.pp-cta-bottom p {
  position: relative;
  z-index: 1;
  max-width: 34rem;
  margin: 0 auto 1.8rem;
  color: rgba(255, 255, 255, 0.55);
