  border-top: 1px solid #e8e6df;
  padding: 2rem 0;
}

.pp-footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.pp-footer-name {
  font-size: 0.9rem;
  font-weight: 700;
}

.pp-footer-tag,
.pp-footer-copy {
  color: #8a8a8e;
  font-size: 0.76rem;
}

