@media (max-width: 980px) {
  .pp-feature-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pp-detail-header {
    grid-template-columns: 1fr;
  }

  .pp-detail-right {
    max-width: 320px;
  }
}

@media (max-width: 768px), (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
  .pp-navbar-inner,
  .pp-content,
  .pp-footer-inner {
    width: min(100% - 1.3rem, 1160px);
  }

  .pp-nav-links {
    display: none;
  }

  .pp-plan-tabs {
    justify-content: flex-start;
    padding-left: 0.7rem;
    padding-right: 0.7rem;
