.app-shell {
  min-height: 100vh;
  background: #ffffff;
}

.layout {
  display: flex;
  min-height: 100vh;
  background: #ffffff;
}

.sidebar {
  width: 126px;
  min-height: 100vh;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border-right: 1px solid rgba(226, 232, 240, 0.6);
  box-shadow: 4px 0 20px rgba(15, 23, 42, 0.04), 1px 0 4px rgba(15, 23, 42, 0.02);
  padding: 1rem 0.75rem;
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  z-index: 20;
}

.sidebar-brand {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.25rem 0 0.9rem;
  border-bottom: none;
}

.brand-wordmark-sidebar {
  justify-content: center;
  max-width: 100%;
  font-size: 1rem;
  color: #0f172a;
}

.brand-wordmark-sidebar .brand-wordmark-full {
  display: inline-block;
}

.brand-wordmark-sidebar .brand-wordmark-compact {
  display: none;
}

.sidebar-nav {
  margin-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.sidebar-link {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 0.68rem;
  text-decoration: none;
  color: #334155;
  border-radius: 14px;
  background: transparent;
  border: none;
  cursor: pointer;
  font: inherit;
  position: relative;
  transition: background var(--transition-fast), color var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast);
}

/* Centrar iconos cuando la sidebar no está expandida */
.sidebar-icon {
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  color: #334155;
}

.sidebar-icon svg {
  width: 16px;
  height: 16px;
}

.sidebar-icon .icon-k {
  font-size: 0.9rem;
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0;
}

.sidebar-label {
  white-space: nowrap;
  width: 0;
  opacity: 0;
  overflow: hidden;
  font-size: 0.9rem;
  transition: opacity 0.2s ease;
}

.sidebar-tooltip {
  position: absolute;
  left: calc(100% + 10px);
  top: 50%;
  transform: translateY(-50%) translateX(-6px);
  padding: 0.45rem 0.68rem;
  border-radius: 10px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid rgba(219, 231, 243, 0.7);
  box-shadow: var(--shadow-lg);
  color: #0f172a;
  font-size: 0.76rem;
  font-weight: 600;
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  z-index: 40;
  transition: opacity 0.18s ease, transform 0.18s ease, visibility 0.18s ease;
}

.sidebar-link:hover .sidebar-tooltip,
.sidebar-link:focus-visible .sidebar-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateY(-50%) translateX(0);
}

.sidebar-link:hover {
  background: var(--brand-soft);
  transform: translateX(2px);
  box-shadow: var(--shadow-xs);
}

.sidebar-link:hover .sidebar-icon {
  color: var(--brand-primary);
}

.sidebar-link:active {
  transform: scale(0.96);
  transition-duration: 0.08s;
}

.sidebar-link.active {
  background: linear-gradient(135deg, #44c4ff 0%, #2563eb 58%, #1d4ed8 100%);
  color: #ffffff;
  box-shadow: 0 8px 20px var(--brand-shadow), inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.sidebar-link.active .sidebar-icon {
  color: #ffffff;
}

.sidebar-badge {
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: linear-gradient(135deg, #f87171, #ef4444);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  top: 6px;
  right: 6px;
  box-shadow: 0 4px 10px rgba(239, 68, 68, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  animation: badge-pulse 2s ease-in-out infinite;
}

.sidebar-footer {
  margin-top: 1.2rem;
  border-top: 1px solid #e5e7eb;
  padding-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

/* Ocultar texto del footer cuando no está expandida */
.sidebar:not(.expanded) .sidebar-user {
  display: none;
}

.sidebar:not(.expanded) .nav-button.ghost .sidebar-label {
  display: none;
}

.sidebar-user {
  font-weight: 700;
}

.nav-button {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  color: var(--brand-primary);
  border: none;
  padding: 0.4rem 0.9rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: 600;
  box-shadow: var(--shadow-brand);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.nav-button:active {
  transform: scale(0.96);
  transition-duration: 0.08s;
}

.nav-button.ghost {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  color: #334155;
  border: 1px solid rgba(226, 232, 240, 0.8);
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  box-shadow: var(--shadow-xs);
  border-radius: 12px;
