/* Responsive: mobile app look - Bottom navigation bar */
@media (max-width: 768px), (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
  .layout {
    flex-direction: column;
  }

  /* Ocultar sidebar lateral completamente en móvil */
  .sidebar {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    top: auto;
    width: 100%;
    height: auto;
    min-height: auto;
    flex-direction: row;
    align-items: center;
    justify-content: space-around;
    padding: 0.5rem 1rem;
    padding-bottom: calc(0.5rem + env(safe-area-inset-bottom));
    box-shadow: 0 -4px 24px rgba(37, 99, 235, 0.18);
    border-right: none;
    border-top: none;
    border-radius: 24px 24px 0 0;
    background: #2563eb;
    z-index: 1000;
    transition: none;
  }

  .sidebar.expanded {
    width: 100%;
  }

  /* Ocultar brand y footer en móvil */
