/* Auth Pages - Modern Design */
.auth-container {
  min-height: 100dvh;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow-y: auto;
  overflow-x: clip;
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 50%, #e0f2fe 100%);
  padding: clamp(1rem, 3vw, 2rem);
  isolation: isolate;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.auth-container::-webkit-scrollbar {
  display: none; /* Chrome, Safari y Opera */
}

.auth-decoration {
  position: absolute;
  inset: 0;
  overflow: clip;
  pointer-events: none;
  opacity: 0.5;
}

.auth-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
  animation: blob-float 20s infinite ease-in-out;
}

.blob-1 {
  width: 700px;
  height: 700px;
  background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);
  top: -15%;
  left: -15%;
  animation-delay: 0s;
}

.blob-2 {
  width: 600px;
  height: 600px;
  background: linear-gradient(135deg, #22c55e 0%, #16a34a 100%);
  bottom: -20%;
  right: -15%;
  animation-delay: 7s;
}

.blob-3 {
  width: 500px;
  height: 500px;
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%);
  top: 30%;
  right: -10%;
  animation-delay: 14s;
}

@keyframes blob-float {
  0%,
  100% {
    transform: translate(0, 0) scale(1) rotate(0deg);
  }
  33% {
    transform: translate(40px, -60px) scale(1.1) rotate(120deg);
  }
  66% {
    transform: translate(-30px, 30px) scale(0.9) rotate(240deg);
  }
}

.auth-content {
  position: relative;
  z-index: 10;
  width: min(100%, 520px);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  margin: auto;
  flex-shrink: 1;
}

.auth-card {
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(25px);
  border-radius: 24px;
  padding: 2.5rem;
  box-shadow: 0 30px 70px rgba(37, 99, 235, 0.15),
    0 10px 30px rgba(0, 0, 0, 0.05), 0 0 0 1px rgba(255, 255, 255, 1);
  border: 1px solid rgba(255, 255, 255, 1);
  animation: card-appear 0.6s ease-out;
  width: 100%;
  overflow: hidden;
}

@keyframes card-appear {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes menu-pop-in {
  from {
    opacity: 0;
    transform: scale(0.95) translateY(-4px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes badge-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}

@keyframes subtle-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

.auth-header {
  text-align: center;
  margin-bottom: 2rem;
}

.auth-back-link {
  position: fixed;
  top: clamp(0.9rem, 2.5vw, 1.35rem);
  left: clamp(0.9rem, 2.5vw, 1.35rem);
  z-index: 40;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: #1d4ed8;
  text-decoration: none;
  font-weight: 700;
  font-size: 0.9rem;
  padding: 0.55rem 0.9rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #dbeafe;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.08);
  pointer-events: auto;
}

.auth-back-link svg {
  width: 16px;
  height: 16px;
}

.auth-back-link:hover {
  color: #0ea5e9;
}

