.timeline.vertical {
  position: relative;
  padding-left: 2rem;
}

/* ══════════════════════════════════════════════
   HISTORIA — Timeline vertical con dot+ícono
   ══════════════════════════════════════════════ */

.timeline.vertical {
  position: relative;
  padding-left: 0;
  gap: 0;
}

/* Línea delgada oscura centrada en los dots */
.timeline.vertical::before {
  content: "";
  position: absolute;
  top: 20px;
  bottom: 20px;
  left: 19px;          /* centro del dot de 38px */
  width: 1.5px;
  background: #1e3a8a;
  z-index: 0;
}

/* Eliminar el pseudo-dot de CSS — ahora el dot es un elemento real */
.timeline.vertical .timeline-item::before {
  display: none;
}

/* Cada ítem: fila flex dot + card */
.timeline.vertical .timeline-item {
  display: flex;
  align-items: flex-start;
  gap: 0.9rem;
  padding-left: 0;
  padding-bottom: 1rem;
}

/* ── Dot: círculo con ícono ── */
.timeline-node {
  width: 38px;
  height: 38px;
  min-width: 38px;
  border-radius: 50%;
  background: #eff6ff;
  border: 1.5px solid #93c5fd;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  z-index: 2;
  box-shadow: 0 0 0 3px rgba(219, 234, 254, 0.55);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  flex-shrink: 0;
}

.timeline.vertical .timeline-item:hover .timeline-node {
  transform: scale(1.1);
  box-shadow: 0 0 0 5px rgba(37, 99, 235, 0.12), 0 2px 10px rgba(37, 99, 235, 0.18);
}

/* Dot coloreado por tipo */
.timeline.vertical .timeline-item.type-appointment .timeline-node {
  background: #f0f9ff;
  border-color: #7dd3fc;
  box-shadow: 0 0 0 3px rgba(125, 211, 252, 0.3);
}
.timeline.vertical .timeline-item.type-document .timeline-node,
.timeline.vertical .timeline-item.type-diagnostic_result .timeline-node {
  background: #fffbeb;
  border-color: #fcd34d;
  box-shadow: 0 0 0 3px rgba(252, 211, 77, 0.3);
}
.timeline.vertical .timeline-item.type-medication .timeline-node,
.timeline.vertical .timeline-item.type-treatment .timeline-node {
  background: #f0fdf4;
  border-color: #86efac;
  box-shadow: 0 0 0 3px rgba(134, 239, 172, 0.3);
}
.timeline.vertical .timeline-item.type-health_alert .timeline-node {
  background: #fff1f2;
  border-color: #fca5a5;
  box-shadow: 0 0 0 3px rgba(252, 165, 165, 0.3);
}
.timeline.vertical .timeline-item.type-external_record .timeline-node {
  background: #faf5ff;
  border-color: #d8b4fe;
  box-shadow: 0 0 0 3px rgba(216, 180, 254, 0.3);
}

/* ── Card contenido ── */
.timeline-card {
  flex: 1;
  min-width: 0;
  padding-top: 0.35rem;
}

.timeline-item {
  background: linear-gradient(135deg, #ffffff 0%, #fafbff 100%);
  border-radius: 18px;
  padding: 1.25rem;
  border: 1.5px solid rgba(226, 232, 240, 0.7);
  box-shadow: var(--shadow-md);
  transition: transform var(--transition-base), border-color var(--transition-fast), box-shadow var(--transition-base);
}

.timeline-item:hover {
  border-color: rgba(37, 99, 235, 0.25);
  box-shadow: var(--shadow-brand);
  transform: translateX(4px) translateY(-1px);
}

.timeline-main {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
}

.timeline-title {
  margin: 0.35rem 0;
  font-weight: 700;
}

.timeline-meta {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.timeline-notes {
  margin: 0.25rem 0 0;
  color: var(--slate);
  font-size: 0.9rem;
}

.timeline-stats {
  margin-top: 1rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 0.75rem;
}

.timeline-overview-card,
.timeline-filters-card {
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
