    border-radius: 12px;
    z-index: 1200;
  }

  .topbar-label {
    display: none;
  }

  .topbar-row {
    flex-wrap: nowrap;
    gap: 0.42rem;
  }

  .topbar-title {
    font-size: 0.98rem;
    line-height: 1.2;
    margin: 0;
  }

  .topbar-chip {
    display: none;
  }

  .topbar-actions {
    width: auto;
    justify-content: flex-end;
    gap: 0.35rem;
  }

  .topbar-quick {
    padding: 0.34rem 0.52rem;
  }

  .topbar-user {
    padding: 0.28rem 0.46rem 0.28rem 0.28rem;
    border-radius: 10px;
  }

  .topbar-avatar {
    width: 28px;
    height: 28px;
    border-radius: 7px;
  }

  .topbar-name {
    font-size: 0.82rem;
    font-weight: 600;
  }

  .topbar-user-menu {
    min-width: min(320px, calc(100vw - 1.2rem));
    max-width: calc(100vw - 1.2rem);
    right: 0;
    z-index: 2300;
  }

  .notifications-dropdown {
    width: min(320px, 90vw);
    z-index: 2300;
  }
}

@media (max-width: 640px) {
  .topbar {
    padding: 0.42rem 0.54rem;
    margin-bottom: 0.42rem;
  }

  .topbar-title {
    font-size: 0.92rem;
  }

  .topbar-name {
    font-size: 0.78rem;
  }

  .topbar-quick {
    padding: 0.28rem 0.46rem;
  }

  .topbar-quick svg {
    width: 15px;
    height: 15px;
  }

  .topbar-user {
    padding: 0.22rem 0.38rem 0.22rem 0.22rem;
  }

  .topbar-avatar {
    width: 24px;
    height: 24px;
  }

  .notifications-dropdown,
  .topbar-user-menu {
    position: fixed;
    top: calc(env(safe-area-inset-top) + 4.05rem);
    left: 0.55rem;
    right: 0.55rem;
    width: auto;
    min-width: 0;
    max-width: none;
    z-index: 5600;
  }

  .notifications-dropdown {
    padding: 0.7rem;
    max-height: min(60dvh, 420px);
  }

  .notifications-header {
    flex-wrap: wrap;
    gap: 0.55rem;
    align-items: flex-start;
  }

  .notifications-heading {
    flex: 1 1 auto;
  }

  .notifications-clear-btn {
    flex: 0 0 auto;
    width: auto;
    max-width: 100%;
    min-width: 0;
    margin-left: auto;
    white-space: nowrap;
    padding: 0.42rem 0.78rem;
  }

  .notifications-list {
    max-height: calc(min(60dvh, 420px) - 4rem);
  }

  .topbar-user-menu {
    max-height: min(72dvh, 560px);
    overflow-y: auto;
  }

  .sidebar {
    padding: 0.34rem 0.3rem;
    padding-bottom: calc(0.34rem + env(safe-area-inset-bottom));
  }

  .sidebar-link {
    padding: 0.36rem 0.24rem;
