}

.landing-section-alt {
  background: linear-gradient(135deg, #f8fafc, #eff6ff);
}

.landing-section-header {
  text-align: center;
  margin-bottom: 1rem;
}

.landing-section-header h2 {
  margin: 0;
  font-size: 1.5rem;
}

.landing-section-header p {
  margin: 0.35rem 0 0;
  color: #475569;
}

.landing-cards {
  display: grid;
