}

.landing-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 1rem;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.05);
}

.landing-card-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
