  color: #1d4ed8;
  margin-bottom: 0.5rem;
}

.landing-card-icon svg {
  width: 22px;
  height: 22px;
}

.landing-card h3 {
  margin: 0 0 0.3rem;
  color: #0f172a;
}

.landing-card p {
  margin: 0;
  color: #475569;
}

.landing-modules {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1rem;
}

.landing-module-card {
  padding: 1rem 1.1rem;
  border-radius: 14px;
  background: #fff;
  border: 1px solid #e2e8f0;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.05);
}

.landing-module-card h3 {
  margin: 0 0 0.4rem;
  color: #0f172a;
}

.landing-module-card p {
  margin: 0;
  color: #475569;
}

.landing-plans {
  background: linear-gradient(135deg, #eff6ff, #eef2ff);
}

.landing-plan-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1rem;
}

.landing-plan-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  margin-bottom: 1.2rem;
  font-weight: 600;
  color: #1e293b;
}

.toggle-switch {
  width: 56px;
  height: 28px;
  border-radius: 999px;
  background: #e2e8f0;
  border: none;
  cursor: pointer;
  padding: 3px;
  display: flex;
  align-items: center;
  transition: background 0.2s ease;
}

.toggle-switch.is-yearly {
  background: linear-gradient(135deg, #2563eb, #22c55e);
}

.toggle-knob {
  width: 22px;
  height: 22px;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.15);
  transform: translateX(0);
  transition: transform 0.2s ease;
