.toggle-active {
  color: #2563eb;
}

.toggle-badge {
  background: rgba(37, 99, 235, 0.1);
  border: 1px solid rgba(37, 99, 235, 0.2);
  color: #2563eb;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  font-size: 0.75rem;
