.home-ops-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.home-ops-feed,
.home-ops-recent,
.home-ops-notes-list {
  display: grid;
  gap: 0.6rem;
}

.home-ops-feed-item,
.home-ops-recent-item,
.home-ops-note-item {
  display: grid;
  gap: 0.18rem;
  padding: 0.78rem 0.82rem;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  background: #ffffff;
}

.home-ops-feed-item {
  grid-template-columns: 88px minmax(0, 1fr);
  align-items: start;
}

.home-ops-feed-item.tone-violet {
  border-left: 3px solid #7c3aed;
}

.home-ops-feed-item.tone-green {
  border-left: 3px solid #16a34a;
}

.home-ops-feed-date {
  font-size: 0.82rem;
  font-weight: 700;
  color: #475569;
}

.home-ops-feed-title,
.home-ops-note-item p,
.home-ops-recent-title {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 600;
  color: #0f172a;
}

.home-ops-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
}

.home-ops-action {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.82rem 0.9rem;
  border-radius: 14px;
  border: 1px solid #e2e8f0;
  background: #ffffff;
  text-align: left;
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.home-ops-action:hover {
  transform: translateY(-1px);
  border-color: #cbdcf5;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.07);
}

.home-ops-action-icon {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: #eff6ff;
  color: #2563eb;
  font-size: 0.8rem;
  font-weight: 700;
  flex-shrink: 0;
}

.home-ops-action.tone-green .home-ops-action-icon {
  background: #ecfdf3;
  color: #16a34a;
}

.home-ops-action.tone-violet .home-ops-action-icon {
  background: #f5f3ff;
  color: #7c3aed;
}

.home-ops-action.tone-amber .home-ops-action-icon {
  background: #fff7ed;
  color: #c47d12;
}

.home-ops-action.tone-cyan .home-ops-action-icon {
  background: #ecfeff;
  color: #0891b2;
}

.home-ops-action strong {
  display: block;
  color: #0f172a;
  font-size: 0.88rem;
}

.home-ops-action small {
  display: block;
  margin-top: 0.12rem;
  font-size: 0.76rem;
}

.home-ops-notes {
  display: grid;
  gap: 0.75rem;
}

.home-ops-note-input {
  min-height: 104px;
}

.home-ops-note-btn {
  width: fit-content;
}

.home-ops-recent-kind {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #94a3b8;
}

.home-ops-recent-item.tone-blue {
  border-left: 3px solid #2563eb;
}

.home-ops-recent-item.tone-green {
  border-left: 3px solid #16a34a;
}

.home-ops-recent-item.tone-violet {
  border-left: 3px solid #7c3aed;
}

body.theme-dark .home-ops-title,
body.theme-dark .home-ops-section-title,
body.theme-dark .home-ops-radar-value,
body.theme-dark .home-ops-feed-title,
body.theme-dark .home-ops-note-item p,
body.theme-dark .home-ops-recent-title,
body.theme-dark .home-ops-action strong {
  color: #e2e8f0;
}

body.theme-dark .home-ops-subtitle,
body.theme-dark .home-ops-context,
body.theme-dark .home-ops-section-text,
body.theme-dark .home-ops-feed-meta,
body.theme-dark .home-ops-note-item small,
body.theme-dark .home-ops-recent-meta,
body.theme-dark .home-ops-empty,
body.theme-dark .home-ops-action small,
body.theme-dark .home-ops-radar-helper,
body.theme-dark .home-ops-kicker,
body.theme-dark .home-ops-radar-label,
body.theme-dark .home-ops-recent-kind {
  color: #94a3b8;
}

body.theme-dark .home-ops-card,
body.theme-dark .home-ops-radar-item,
body.theme-dark .home-ops-feed-item,
body.theme-dark .home-ops-recent-item,
body.theme-dark .home-ops-note-item,
body.theme-dark .home-ops-action {
  background: #0f172a;
  border-color: #1e293b;
  box-shadow: 0 12px 28px rgba(2, 6, 23, 0.2);
}

body.theme-dark .home-ops-action:hover {
  border-color: #334155;
}

body.theme-dark .home-ops-action-icon {
  background: #111827;
  border: 1px solid #243244;
}

@media (max-width: 1023px) {
  .home-ops-radar-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .home-ops {
    gap: 0.8rem;
  }

  .home-ops-title {
    font-size: 1.45rem;
  }

  .home-ops-subtitle,
  .home-ops-context,
  .home-ops-section-text {
    font-size: 0.82rem;
  }

  .home-ops-card {
    padding: 0.78rem 0.8rem;
    border-radius: 14px;
  }

  .home-ops-radar-grid,
  .home-ops-grid,
  .home-ops-actions {
    grid-template-columns: 1fr;
  }

  .home-ops-feed-item {
    grid-template-columns: 72px minmax(0, 1fr);
  }

  .home-ops-feed-item,
  .home-ops-recent-item,
  .home-ops-note-item,
  .home-ops-action,
  .home-ops-radar-item {
    padding: 0.68rem 0.72rem;
    border-radius: 12px;
  }

  .home-ops-note-input {
    min-height: 88px;
  }

  .home-ops-note-btn {
    width: 100%;
  }
}

.ai-cta-row {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  flex-wrap: wrap;
  margin: 0.35rem 0 1.25rem;
  padding: 1.1rem 1.25rem;
  border-radius: 18px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.08);
}

.home-editorial {
  position: relative;
  width: 100%;
  margin-left: 0;
  margin-right: 0;
}

.home-editorial-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.42fr) 360px;
  column-gap: 1.3rem;
  row-gap: 1.3rem;
  align-items: start;
}

.home-editorial-top,
.home-editorial-voice,
.home-editorial-left,
.home-editorial-right {
  display: flex;
  flex-direction: column;
  gap: 1.3rem;
  min-width: 0;
}

.home-editorial-top {
  grid-column: 1;
  grid-row: 1;
}

.home-editorial-voice {
  grid-column: 2;
  grid-row: 1;
}

.home-editorial-left {
  grid-column: 1;
  grid-row: 2;
}

.home-editorial-right {
  grid-column: 2;
  grid-row: 2;
}

.home-panel-card {
  position: relative;
  border-radius: 24px;
  border: 1px solid #dce4f1;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96) 0%, #ffffff 100%);
  box-shadow: 0 22px 44px rgba(15, 23, 42, 0.05);
  padding: 1.4rem;
}

.home-panel-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.18), rgba(14, 165, 233, 0.06), rgba(124, 58, 237, 0.12));
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

.home-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
}

.home-panel-title {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #0f172a;
}

.home-panel-subtitle {
  margin: 0.25rem 0 0;
  font-size: 0.82rem;
  line-height: 1.55;
  color: #64748b;
}

.home-panel-link {
  border: 1px solid #cdd9ee;
  background: rgba(255, 255, 255, 0.92);
  color: #2563eb;
  border-radius: 999px;
  min-height: 34px;
  padding: 0.45rem 0.9rem;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.home-panel-link:hover {
  border-color: #93c5fd;
  background: #eff6ff;
  transform: translateY(-1px);
}

.home-greeting-card {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  border-radius: 28px;
  padding: 1.7rem 1.8rem;
  background:
    radial-gradient(circle at 82% 22%, rgba(125, 211, 252, 0.22), transparent 28%),
    radial-gradient(circle at 14% 88%, rgba(96, 165, 250, 0.18), transparent 26%),
    linear-gradient(135deg, #38bdf8 0%, #2563eb 56%, #1d4ed8 100%);
  box-shadow: 0 24px 40px rgba(37, 99, 235, 0.24);
}

.home-greeting-copy,
.home-greeting-side {
  position: relative;
  z-index: 1;
}

.home-greeting-eyebrow {
  margin: 0 0 0.35rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.56);
}

.home-greeting-title {
  margin: 0;
  font-family: "Poppins", "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: clamp(1.95rem, 3.3vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #ffffff;
  line-height: 1.05;
}

.home-greeting-title em {
  font-style: normal;
  color: #bfdbfe;
}

.greeting-cursor {
  display: inline-block;
