  cursor: not-allowed;
}

.voice-indicacion-text {
  margin: 0;
  font-size: 0.84rem;
  line-height: 1.45;
  color: #334155;
}

.voice-actions-footer {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.75rem;
  padding-top: 0.75rem;
  border-top: 1px solid #e2e8f0;
}

.voice-actions-footer .home-note-secondary,
.voice-actions-footer .home-note-primary {
  flex: 1;
  font-size: 0.78rem;
}

.voice-share-options {
  margin-top: 0.5rem;
  padding: 0.75rem;
  border-radius: 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.voice-share-title {
  margin: 0;
  font-size: 0.78rem;
  font-weight: 700;
  color: #64748b;
}

.voice-share-option {
  padding: 0.4rem 0.75rem;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #ffffff;
  font-size: 0.82rem;
  font-weight: 600;
  color: #334155;
  cursor: pointer;
  text-align: left;
}

.voice-share-option:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.voice-share-note {
  margin: 0;
  font-size: 0.72rem;
  color: #94a3b8;
  font-style: italic;
}

/* ── Voice Page (vp-*) ────────────────────────────────────────────────────── */

.vp-page {
  max-width: 680px;
  margin: 0 auto;
  padding: 1.5rem 1rem;
}

.vp-loading {
  text-align: center;
  padding: 3rem 1rem;
  color: #64748b;
  font-size: 0.88rem;
}

/* Header */
.vp-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.vp-title {
  font-size: 1.35rem;
  font-weight: 700;
  margin: 0;
  color: #0f172a;
}

.vp-subtitle {
  font-size: 0.84rem;
  color: #64748b;
  margin: 0.2rem 0 0;
}

.vp-new-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 10px;
  background: #6C47FF;
  color: #fff;
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s;
}

.vp-new-btn:hover { background: #5a38e0; }
.vp-new-btn:disabled { opacity: 0.5; cursor: not-allowed; }

.vp-new-btn-icon {
  width: 16px;
  height: 16px;
}

/* Hero card */
.vp-hero {
  background: #6C47FF;
  border-radius: 14px;
  padding: 2rem 1.5rem;
  margin-bottom: 1.5rem;
}

.vp-hero-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.75rem;
}

.vp-hero-icon {
  width: 48px;
  height: 48px;
  stroke: rgba(255, 255, 255, 0.85);
}

.vp-hero-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: #fff;
  margin: 0;
}

.vp-hero-desc {
  font-size: 0.86rem;
  color: rgba(255, 255, 255, 0.82);
  margin: 0;
  max-width: 420px;
  line-height: 1.55;
}

.vp-hero-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.62rem;
  min-height: 56px;
  padding: 0.72rem 1.6rem;
  border: none;
  border-radius: 999px;
  background: linear-gradient(90deg, #47b5f5 0%, #4f7de8 42%, #4e18f0 100%);
  color: #ffffff;
  font-size: 0.92rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  cursor: pointer;
  margin-top: 0.25rem;
  box-shadow: 0 16px 32px rgba(79, 125, 232, 0.28);
  transition: background 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

.vp-hero-btn:hover {
  background: linear-gradient(90deg, #57bef8 0%, #5a87ee 42%, #5b27f3 100%);
  transform: translateY(-1px);
  box-shadow: 0 20px 36px rgba(79, 125, 232, 0.32);
}
.vp-hero-btn:disabled { opacity: 0.5; cursor: not-allowed; }

.vp-hero-btn-icon {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  flex-shrink: 0;
}

.vp-hero-btn-mic {
  width: 16px;
  height: 16px;
  stroke: currentColor;
}

.vp-hero-btn-label {
  line-height: 1;
}

/* Session list */
.vp-sessions {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.vp-session-card {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  cursor: pointer;
  text-align: left;
  width: 100%;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.vp-session-card:hover {
  border-color: #6C47FF;
  box-shadow: 0 0 0 1px #6C47FF22;
}

.vp-session-icon-wrap {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: #ede9fe;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.vp-session-icon {
  width: 20px;
  height: 20px;
  stroke: #6C47FF;
}

.vp-session-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.vp-session-title {
  font-size: 0.88rem;
  font-weight: 600;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.vp-session-meta {
  font-size: 0.78rem;
  color: #94a3b8;
}

.vp-session-badge {
  font-size: 0.72rem;
  font-weight: 600;
  padding: 0.2rem 0.55rem;
  border-radius: 6px;
  white-space: nowrap;
  flex-shrink: 0;
}

.vp-badge-green {
  background: #dcfce7;
  color: #166534;
}

.vp-badge-purple {
  background: #ede9fe;
  color: #5b21b6;
}

.vp-badge-orange {
  background: #ffedd5;
  color: #9a3412;
}

/* Session detail */
.vp-detail {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.vp-detail-back {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  background: none;
  border: none;
  color: #6C47FF;
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  padding: 0;
  margin-bottom: 0.25rem;
}

.vp-detail-back:hover { text-decoration: underline; }

.vp-detail-back-icon {
  width: 18px;
  height: 18px;
}

.vp-detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.vp-detail-title {
  font-size: 1.15rem;
  font-weight: 700;
  margin: 0;
  color: #0f172a;
}

.vp-detail-meta {
  font-size: 0.82rem;
  color: #64748b;
  margin: 0.3rem 0 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.vp-detail-trace {
  font-size: 0.8rem;
  color: #64748b;
  padding: 0.6rem 0.8rem;
  background: #f8fafc;
  border-radius: 8px;
  border: 1px solid #e2e8f0;
}

/* Recorder wrapper */
.vp-recorder-wrapper {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* ── Voice Page dark theme ─────────────────────────────────────────────────── */

body.theme-dark .vp-title { color: #f1f5f9; }
body.theme-dark .vp-subtitle { color: #94a3b8; }

body.theme-dark .vp-session-card {
  background: #1e293b;
  border-color: #334155;
}
body.theme-dark .vp-session-card:hover {
  border-color: #7c5cff;
  box-shadow: 0 0 0 1px rgba(124, 92, 255, 0.15);
}
body.theme-dark .vp-session-icon-wrap {
  background: rgba(108, 71, 255, 0.18);
}
body.theme-dark .vp-session-title { color: #f1f5f9; }
body.theme-dark .vp-session-meta { color: #64748b; }

body.theme-dark .vp-badge-green { background: rgba(22, 101, 52, 0.2); color: #86efac; }
body.theme-dark .vp-badge-purple { background: rgba(91, 33, 182, 0.2); color: #c4b5fd; }
body.theme-dark .vp-badge-orange { background: rgba(154, 52, 18, 0.2); color: #fdba74; }

body.theme-dark .vp-detail-title { color: #f1f5f9; }
body.theme-dark .vp-detail-meta { color: #94a3b8; }
body.theme-dark .vp-detail-trace {
  background: #1e293b;
  border-color: #334155;
  color: #94a3b8;
}

body.theme-dark .vp-detail-back { color: #818cf8; }
body.theme-dark .vp-hero-btn { color: #ffffff; }

/* ── Mobile adjustments ────────────────────────────────────────────────────── */

@media (max-width: 640px) {
  .vp-header { flex-direction: column; gap: 0.75rem; }
  .vp-new-btn { width: 100%; justify-content: center; }
  .vp-hero { padding: 1.5rem 1rem; }
  .vp-hero-btn {
    width: 100%;
    min-height: 52px;
    padding: 0.68rem 1.1rem;
    font-size: 0.84rem;
    gap: 0.56rem;
  }
  .vp-hero-btn-icon {
    width: 26px;
    height: 26px;
  }
  .vp-hero-btn-mic {
    width: 15px;
    height: 15px;
  }
  .vp-detail-meta { flex-direction: column; align-items: flex-start; gap: 0.3rem; }
}

/* ══════════════════════════════════════════════════════════════════════════════
   Voice Page v2 (vp2-*)
   ══════════════════════════════════════════════════════════════════════════════ */

@keyframes vp2-blink {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.3; }
}

.vp2-page {
  max-width: 960px;
  margin: 0 auto;
  padding: 1rem 1rem 1.5rem;
}

.vp2-loading {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--muted);
  font-size: 0.86rem;
}

/* ── Header ────────────────────────────────────────────────────────────────── */

.vp2-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.8rem;
}

.vp2-actions-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 0.8rem;
}

.vp2-header-copy {
  display: grid;
  gap: 0.18rem;
  min-width: 0;
}

.vp2-section-intro {
  display: grid;
  gap: 0.12rem;
  margin-bottom: 0.75rem;
}

.vp2-section-sub {
  font-size: 0.84rem;
  color: var(--text-secondary, #64748b);
  margin: 0;
}

body.theme-dark .vp2-section-sub {
  color: #94a3b8;
}

.vp2-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-family: "JetBrains Mono", "Fira Code", monospace;
  color: #00B377;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.vp2-eyebrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #00B377;
  animation: vp2-blink 2s ease-in-out infinite;
}

.vp2-title {
  font-size: 1.35rem;
  font-weight: 700;
  margin: 0;
  color: var(--navy);
}

.vp2-subtitle {
  font-size: 0.84rem;
  color: var(--muted);
  margin: 0.15rem 0 0;
}

.vp2-new-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 10px;
  background: var(--brand-primary);
  color: #fff;
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s;
  flex-shrink: 0;
}

.vp2-new-btn:hover { background: var(--brand-secondary); }
.vp2-new-btn:disabled { opacity: 0.5; cursor: not-allowed; }

.vp2-new-btn-icon { width: 16px; height: 16px; }

/* ── Grid ──────────────────────────────────────────────────────────────────── */

.vp2-grid {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 1.5rem;
  align-items: start;
}

/* ── Left: Hero card ───────────────────────────────────────────────────────── */

.vp2-hero {
  display: none;
}

.vp2-hero-circle {
  position: absolute;
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: rgba(255,255,255,0.05);
  pointer-events: none;
}

.vp2-hero-circle-tr { top: -30px; right: -30px; }
.vp2-hero-circle-bl { bottom: -40px; left: -30px; width: 140px; height: 140px; }

.vp2-hero-inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.65rem;
}

.vp2-hero-orb {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
}

.vp2-hero-orb-icon { width: 24px; height: 24px; stroke: #fff; }

.vp2-hero-title {
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  margin: 0;
}

.vp2-hero-desc {
  font-size: 0.8rem;
  color: rgba(255,255,255,0.78);
  margin: 0;
  line-height: 1.5;
}

.vp2-hero-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1.2rem;
  border: none;
  border-radius: 10px;
  background: #fff;
  color: var(--brand-primary);
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s;
}

.vp2-hero-btn:hover { background: #eff6ff; }
.vp2-hero-btn:disabled { opacity: 0.5; cursor: not-allowed; }
.vp2-hero-btn-mic { width: 16px; height: 16px; stroke: var(--brand-primary); }

.vp2-hero-tags {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 5px;
  margin-top: 0.35rem;
}

.vp2-hero-tag {
  font-size: 0.68rem;
  padding: 3px 8px;
  border-radius: 6px;
  background: rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.7);
  border: 1px solid rgba(255,255,255,0.15);
  white-space: nowrap;
}

/* ── Left: How it works ────────────────────────────────────────────────────── */

.vp2-how {
  background: var(--card);
  border: 1px solid var(--brand-soft-strong);
  border-radius: 14px;
  padding: 1.1rem;
  margin-top: 0;
}

.vp2-how-label {
  display: block;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.75rem;
}

.vp2-how-steps {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.vp2-how-step {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  padding: 0.55rem 0;
  border-bottom: 1px solid var(--brand-soft);
}

.vp2-how-step:last-child { border-bottom: none; }

.vp2-how-num {
  font-family: "JetBrains Mono", "Fira Code", monospace;
  font-size: 0.72rem;
  font-weight: 700;
  color: #fff;
  background: var(--brand-primary);
  width: 26px;
  height: 26px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.vp2-how-text {
  font-size: 0.8rem;
  color: var(--slate);
  line-height: 1.45;
  padding-top: 3px;
}

/* ── Right: History header + filters ───────────────────────────────────────── */

.vp2-hist-header {
  margin-bottom: 0.75rem;
}

.vp2-hist-title {
  font-size: 0.82rem;
  font-weight: 700;
  margin: 0 0 0.6rem;
  color: var(--navy);
}

.vp2-filters {
  display: flex;
  gap: 0.35rem;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-bottom: 0.1rem;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.vp2-filters::-webkit-scrollbar { display: none; }

.vp2-filter {
  font-size: 0.74rem;
  font-weight: 600;
  padding: 0.3rem 0.7rem;
  border-radius: 8px;
  border: 1px solid var(--brand-soft-strong);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  transition: all 0.15s;
  flex: 0 0 auto;
  white-space: nowrap;
}

.vp2-filter:hover {
  background: var(--brand-soft);
  color: var(--brand-primary);
  border-color: var(--brand-border);
}

.vp2-filter-active {
  background: var(--brand-soft);
  color: var(--brand-primary);
  border-color: var(--brand-border);
}

/* ── Right: Session cards ──────────────────────────────────────────────────── */

.vp2-sessions {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.vp2-card {
  position: relative;
  padding: 0;
  background: var(--card);
  border: 1px solid rgba(37,99,235,0.1);
  border-radius: 14px;
  text-align: left;
  width: 100%;
  transition: border-color 0.15s, transform 0.15s, box-shadow 0.15s;
}

.vp2-card-open {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 1rem 1rem 0.75rem;
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.vp2-card.is-manageable .vp2-card-open {
  padding-right: 3.5rem;
}

.vp2-card-delete {
  position: absolute;
  top: 0.7rem;
  right: 0.7rem;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(239, 68, 68, 0.18);
  border-radius: 10px;
  background: rgba(254, 242, 242, 0.9);
  color: #dc2626;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.15s;
}

.vp2-card-delete:hover {
  background: rgba(254, 226, 226, 1);
  border-color: rgba(239, 68, 68, 0.28);
  transform: translateY(-1px);
}

.vp2-card-delete:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

.vp2-card:hover {
  border-color: var(--brand-border);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(37,99,235,0.08);
}

.vp2-card-left-bar {
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: transparent;
  transition: background 0.15s;
}

.vp2-card:hover .vp2-card-left-bar {
  background: var(--brand-primary);
}

.vp2-card-icon-wrap {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--brand-soft);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.vp2-card-icon { width: 20px; height: 20px; stroke: var(--brand-primary); }

.vp2-card-body { flex: 1; min-width: 0; }

.vp2-card-name {
  display: block;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--navy);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.vp2-card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.15rem;
}

.vp2-card-date {
  font-family: "JetBrains Mono", "Fira Code", monospace;
  font-size: 0.72rem;
  color: var(--muted);
}

.vp2-card-chips {
  display: flex;
  gap: 4px;
  margin-top: 0.35rem;
  flex-wrap: wrap;
}

.vp2-card-chip {
  font-size: 0.66rem;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 5px;
  white-space: nowrap;
}

.vp2-card-chip-more {
  background: rgba(107,114,128,0.08);
  color: #6b7280;
}

/* Badge + hover actions */
.vp2-card-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.4rem;
  flex-shrink: 0;
  padding-right: 0.15rem;
}

.vp2-card-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 6px;
  white-space: nowrap;
}

.vp2-badge-green {
  background: rgba(0,179,119,0.1);
  color: #00B377;
  border: 1px solid rgba(0,179,119,0.2);
}

.vp2-badge-blue {
  background: var(--brand-soft);
  color: var(--brand-primary);
  border: 1px solid var(--brand-border);
}

.vp2-badge-amber {
  background: rgba(245,158,11,0.1);
  color: #b45309;
  border: 1px solid rgba(245,158,11,0.2);
}

.vp2-card-actions {
  display: flex;
  gap: 0.5rem;
  opacity: 0;
  transition: opacity 0.15s;
}

.vp2-card:hover .vp2-card-actions { opacity: 1; }

.vp2-card-action {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--brand-primary);
  white-space: nowrap;
}

.vp2-card-menu-trigger {
  position: absolute;
  top: 0.72rem;
  right: 0.72rem;
  z-index: 3;
  width: 32px;
  height: 32px;
  border: 1px solid var(--brand-soft-strong);
  border-radius: 10px;
  background: rgba(255,255,255,0.92);
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, color 0.15s, transform 0.15s;
}

.vp2-card-menu-trigger:hover,
.vp2-card-menu-trigger[aria-expanded="true"] {
  border-color: var(--brand-border);
  background: #ffffff;
  color: var(--brand-primary);
  transform: translateY(-1px);
}

.vp2-card-menu {
  position: absolute;
  top: calc(0.72rem + 36px);
  right: 0.72rem;
  z-index: 4;
  min-width: 168px;
  padding: 0.35rem;
  border-radius: 14px;
  border: 1px solid var(--brand-soft-strong);
  background: rgba(255,255,255,0.98);
  box-shadow: 0 18px 38px rgba(15,23,42,0.14);
  backdrop-filter: blur(14px);
}

.vp2-card-menu-item {
  width: 100%;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.62rem 0.72rem;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--navy);
  font-size: 0.76rem;
  font-weight: 700;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}

.vp2-card-menu-item:hover {
  background: rgba(37,99,235,0.08);
  color: var(--brand-primary);
}

.vp2-card-menu-item.is-danger {
  color: #dc2626;
}

.vp2-card-menu-item.is-danger:hover {
  background: rgba(239,68,68,0.08);
  color: #b91c1c;
}

.vp2-card-menu-item:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* ── Empty state ───────────────────────────────────────────────────────────── */

.vp2-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 2.5rem 1.5rem;
  border: 1px dashed rgba(37,99,235,0.2);
  border-radius: 16px;
}

.vp2-empty-orb {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--brand-soft);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.75rem;
}

.vp2-empty-icon { width: 24px; height: 24px; stroke: var(--brand-primary); }

.vp2-empty-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--navy);
  margin: 0 0 0.3rem;
}

.vp2-empty-desc {
  font-size: 0.82rem;
  color: var(--muted);
  margin: 0 0 1rem;
  max-width: 280px;
  line-height: 1.5;
