.vp2-empty-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1.2rem;
  border: none;
  border-radius: 10px;
  background: var(--brand-primary);
  color: #fff;
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}

.vp2-empty-btn:hover { background: var(--brand-secondary); }
.vp2-empty-btn:disabled { opacity: 0.5; cursor: not-allowed; }

