    font-size: 0.9rem;
  }

  .vp2-panel-toggle {
    min-height: 40px;
    padding: 0.3rem 0.7rem;
  }

  .vp2-how {
    padding: 0.85rem 0.8rem;
  }

  .vp2-how-step {
    align-items: center;
  }

  .vp2-card-icon-wrap {
    width: 36px;
    height: 36px;
  }

  .vp2-card-icon {
    width: 18px;
    height: 18px;
  }

  .vp2-card-right {
    gap: 0.28rem;
  }

  .vp2-card-badge {
    font-size: 0.66rem;
    padding: 0.22rem 0.45rem;
  }

  .vp2-card-menu-trigger {
    top: 0.56rem;
    right: 0.56rem;
    width: 29px;
    height: 29px;
  }

  .vp2-card-menu {
    top: calc(0.56rem + 33px);
    right: 0.56rem;
    min-width: 150px;
    padding: 0.3rem;
  }

  .vp2-card-menu-item {
    padding: 0.58rem 0.65rem;
    font-size: 0.74rem;
  }

  .vp2-empty {
    padding: 2rem 1rem;
  }
}


/* ══════════════════════════════════════════════════════════════════════════════
   Immersive Voice (iv-*)
   ══════════════════════════════════════════════════════════════════════════════ */

/* ── Animations ────────────────────────────────────────────────────────────── */

@keyframes iv-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes iv-fade-out {
  from { opacity: 1; }
  to   { opacity: 0; }
}

@keyframes iv-ringpulse {
  0%, 100% { transform: scale(1);    opacity: 0.3; }
  50%      { transform: scale(1.04); opacity: 0.7; }
}

@keyframes iv-orbpulse {
  0%, 100% { box-shadow: 0 0 0 0px currentColor; }
  50%      { box-shadow: 0 0 0 16px currentColor; }
}

@keyframes iv-wave {
  0%, 100% { transform: scaleY(1); }
  50%      { transform: scaleY(1.6); }
}

@keyframes iv-spin {
  to { transform: rotate(360deg); }
}

/* ── Overlay ───────────────────────────────────────────────────────────────── */

.iv-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  min-height: 100dvh;
  height: 100dvh;
  background: #0D0B14;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  overscroll-behavior: none;
}

.iv-overlay-done {
  align-items: stretch;
  justify-content: flex-start;
}

html.voice-immersive-active,
body.voice-immersive-active {
  background: #0D0B14 !important;
  overscroll-behavior: none !important;
}

body.voice-immersive-active .app-shell,
body.voice-immersive-active .layout,
body.voice-immersive-active .main-area,
body.voice-immersive-active .main-content,
body.voice-immersive-active .route-scene {
  background: #0D0B14 !important;
}

body.voice-immersive-active .sidebar,
body.voice-immersive-active .topbar {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

body.voice-immersive-active .main-area {
  margin-bottom: 0 !important;
}

.iv-overlay.iv-fade-in {
  animation: iv-fade-in 0.3s ease forwards;
}

.iv-overlay.iv-fade-out {
  animation: iv-fade-out 0.3s ease forwards;
  pointer-events: none;
}

/* Close button */
.iv-close {
  position: absolute;
  top: 1.25rem;
  right: 1.25rem;
  z-index: 4;
  width: 40px;
  height: 40px;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.5);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: background 0.15s, color 0.15s;
}

.iv-close:hover {
  background: rgba(255, 255, 255, 0.14);
  color: rgba(255, 255, 255, 0.8);
}

.iv-close svg {
  width: 20px;
  height: 20px;
}

/* ── Content container ─────────────────────────────────────────────────────── */

.iv-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  padding: 2rem;
  max-width: 400px;
  width: 100%;
}

/* ── Orb ───────────────────────────────────────────────────────────────────── */

.iv-orb {
  width: 128px;
  height: 128px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  transition: background 0.4s, border-color 0.4s;
}

.iv-orb-mic {
  width: 36px;
  height: 36px;
  stroke: #fff;
  position: relative;
  z-index: 2;
}

/* Amber orb — consent */
.iv-orb-amber {
  background: rgba(255, 180, 50, 0.15);
  border: 2px solid rgba(255, 180, 50, 0.5);
}

.iv-orb-amber .iv-orb-mic {
  stroke: rgba(255, 200, 80, 0.9);
}

/* Purple orb — recording */
.iv-orb-purple {
  background: #6C47FF;
  border: 2px solid transparent;
  color: rgba(108, 71, 255, 0.25);
  animation: iv-orbpulse 1.5s ease-in-out infinite;
}

/* Green orb — processing */
.iv-orb-green {
  background: rgba(26, 158, 110, 0.2);
  border: 2px solid rgba(26, 158, 110, 0.4);
}

/* Red orb — error */
.iv-orb-red {
  background: rgba(220, 50, 50, 0.15);
  border: 2px solid rgba(220, 50, 50, 0.5);
}

.iv-orb-red .iv-orb-mic {
  stroke: rgba(252, 165, 165, 0.9);
}

/* ── Rings (consent state) ─────────────────────────────────────────────────── */

.iv-ring {
  position: absolute;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 180, 50, 0.25);
  animation: iv-ringpulse 2s ease-in-out infinite;
  pointer-events: none;
}

.iv-ring-1 {
  width: 160px;
  height: 160px;
  animation-delay: 0s;
}

.iv-ring-2 {
  width: 192px;
  height: 192px;
  animation-delay: 0.4s;
}

.iv-ring-3 {
  width: 224px;
  height: 224px;
  animation-delay: 0.8s;
}

/* ── Spinner inside green orb ──────────────────────────────────────────────── */

.iv-orb-spinner {
  width: 36px;
  height: 36px;
  border: 3px solid rgba(255, 255, 255, 0.15);
  border-top-color: rgba(26, 158, 110, 0.9);
  border-radius: 50%;
  animation: iv-spin 0.8s linear infinite;
  position: relative;
  z-index: 2;
}

/* ── Audio waves ───────────────────────────────────────────────────────────── */

.iv-waves {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  height: 42px;
  min-height: 42px;
}

.iv-wave-bar {
  width: 3px;
  min-height: 10px;
  border-radius: 2px;
  background: rgba(108, 71, 255, 0.6);
  transition: height 0.12s ease, background 0.12s ease;
}

.iv-waves.is-recording .iv-wave-bar {
  background: linear-gradient(180deg, rgba(167, 139, 250, 0.95) 0%, rgba(108, 71, 255, 0.82) 100%);
}

.iv-stage-meta {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
  justify-content: center;
}

.iv-stage-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 30px;
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.iv-stage-pill.is-idle {
  background: rgba(245, 158, 11, 0.16);
  border-color: rgba(251, 191, 36, 0.2);
  color: #fde68a;
}

.iv-stage-pill.is-recording {
  background: rgba(108, 71, 255, 0.18);
  border-color: rgba(167, 139, 250, 0.26);
  color: #ddd6fe;
}

.iv-stage-pill.is-processing {
  background: rgba(16, 185, 129, 0.16);
  border-color: rgba(52, 211, 153, 0.2);
  color: #a7f3d0;
}

.iv-stage-pill.is-ready {
  background: rgba(34, 197, 94, 0.16);
  border-color: rgba(74, 222, 128, 0.2);
  color: #bbf7d0;
}

.iv-stage-pill.is-error {
  background: rgba(239, 68, 68, 0.16);
  border-color: rgba(248, 113, 113, 0.22);
  color: #fecaca;
}

.iv-stage-live {
  font-size: 0.76rem;
  color: rgba(255, 255, 255, 0.62);
}

.iv-wake-lock-note {
  margin: -0.45rem 0 0;
  text-align: center;
  font-size: 0.74rem;
  line-height: 1.4;
  color: rgba(255, 255, 255, 0.68);
  max-width: 320px;
}

.iv-wake-lock-note.is-active {
  color: #6ee7b7;
}

.iv-wake-lock-note.is-unsupported,
.iv-wake-lock-note.is-error,
.iv-wake-lock-note.is-released {
  color: #fbbf24;
}

.iv-security-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  width: 100%;
  max-width: 420px;
}

.iv-security-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 30px;
  padding: 0.28rem 0.72rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.84);
  font-size: 0.74rem;
  font-weight: 600;
}

.iv-security-chip svg {
  width: 14px;
  height: 14px;
  color: #6ee7b7;
}

/* ── Timer ──────────────────────────────────────────────────────────────────── */

.iv-timer {
  font-size: 28px;
  font-weight: 300;
  color: #fff;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}

/* ── Text ──────────────────────────────────────────────────────────────────── */

.iv-text {
  text-align: center;
  max-width: 320px;
}

.iv-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: #fff;
  margin: 0 0 0.35rem;
}

.iv-done-title {
  margin-top: 0.72rem;
}

.iv-subtitle {
  font-size: 0.86rem;
  color: rgba(255, 255, 255, 0.55);
  margin: 0;
  line-height: 1.5;
}

/* ── Step dots ─────────────────────────────────────────────────────────────── */

.iv-dots {
  display: flex;
  gap: 8px;
  align-items: center;
}

.iv-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.15);
  transition: background 0.3s;
}

.iv-dot-filled {
  background: #6C47FF;
}

.iv-dot-active {
  background: rgba(255, 255, 255, 0.7);
}

/* ── Buttons ───────────────────────────────────────────────────────────────── */

.iv-actions {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 0.5rem;
}

.iv-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 1.5rem;
  border: none;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.iv-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

.iv-btn:active { transform: scale(0.97); }

.iv-btn-primary {
  background: #6C47FF;
  color: #fff;
}

.iv-btn-primary:hover {
  background: #5a38e0;
}

.iv-btn-arrow {
  width: 16px;
  height: 16px;
}

.iv-role-card,
.iv-context-card {
  width: 100%;
  max-width: 360px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  padding: 0.9rem;
}

.iv-role-label,
.iv-context-label {
  display: block;
  margin-bottom: 0.6rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: rgba(167, 139, 250, 0.9);
}

.iv-role-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem;
}

.iv-role-option {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.22rem;
  padding: 0.72rem 0.78rem;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(255, 255, 255, 0.03);
  color: #fff;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.iv-role-option:hover {
  border-color: rgba(167, 139, 250, 0.45);
  background: rgba(108, 71, 255, 0.14);
  transform: translateY(-1px);
}

.iv-role-option.is-active {
  border-color: rgba(108, 71, 255, 0.8);
  background: rgba(108, 71, 255, 0.2);
  box-shadow: inset 0 0 0 1px rgba(196, 181, 253, 0.22);
}

.iv-role-option-title,
.iv-context-text {
  font-size: 0.83rem;
  font-weight: 600;
  line-height: 1.35;
  color: rgba(255, 255, 255, 0.92);
  margin: 0;
}

.iv-role-option-helper,
.iv-context-helper,
.iv-role-disclaimer {
  font-size: 0.72rem;
  line-height: 1.45;
  color: rgba(255, 255, 255, 0.62);
  margin: 0;
}

.iv-role-disclaimer {
  margin-top: 0.7rem;
}

/* Session controls — stop */
.iv-session-controls {
  display: flex;
  align-items: center;
  gap: 1.25rem;
}

.iv-ctrl {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.iv-ctrl:active { transform: scale(0.93); }

.iv-ctrl-stop {
  background: rgba(239, 68, 68, 0.15);
}

.iv-ctrl-stop:hover {
  background: rgba(239, 68, 68, 0.25);
}

.iv-ctrl-square {
  width: 18px;
  height: 18px;
  border-radius: 3px;
  background: #ef4444;
}

/* ── Done state: slideup animation ─────────────────────────────────────────── */

@keyframes iv-slideup {
  from { transform: translateY(100%); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

@keyframes iv-check-draw {
  from { stroke-dashoffset: 24; }
  to   { stroke-dashoffset: 0; }
}

/* ── Done state: layout ────────────────────────────────────────────────────── */

.iv-done-top {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 3rem;
  padding-bottom: 1.5rem;
  text-align: center;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}

.iv-orb-green-solid {
  background: rgba(26, 158, 110, 0.2);
  border: 2px solid rgba(26, 158, 110, 0.5);
}

.iv-orb-check {
  width: 36px;
  height: 36px;
  position: relative;
  z-index: 2;
  stroke-dasharray: 24;
  stroke-dashoffset: 0;
  animation: iv-check-draw 0.5s ease 0.3s both;
}

/* ── Bottom sheet ──────────────────────────────────────────────────────────── */

.iv-sheet {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 2;
  height: 420px;
  max-height: 65vh;
  background: #1A1730;
  border-radius: 24px 24px 0 0;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  padding-top: 10px;
  animation: iv-slideup 0.35s cubic-bezier(.34, 1.56, .64, 1) forwards;
  overflow: hidden;
}

.iv-sheet-handle {
  width: 36px;
  height: 4px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.25);
  margin: 0 auto 0;
  flex-shrink: 0;
  padding: 0;
  /* Larger touch target via the pseudo-element trick */
  position: relative;
  cursor: grab;
  touch-action: none;
}

.iv-sheet-handle::before {
  content: '';
  position: absolute;
  top: -10px;
  bottom: -10px;
  left: -40px;
  right: -40px;
}

/* ── Sheet tabs ────────────────────────────────────────────────────────────── */

.iv-sheet-tabs {
  display: flex;
  gap: 4px;
  padding: 0 1rem;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 10px;
  margin: 0 1rem 0.75rem;
  flex-shrink: 0;
}

.iv-sheet-tab {
  flex: 1;
  padding: 0.5rem 0;
  border: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.4);
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: 8px;
  transition: background 0.15s, color 0.15s;
}

.iv-sheet-tab:hover {
  color: rgba(255, 255, 255, 0.6);
}

.iv-sheet-tab-active {
  background: #6C47FF;
  color: #fff;
}

/* ── Sheet body ────────────────────────────────────────────────────────────── */

.iv-sheet-body {
  flex: 1;
  overflow-y: auto;
  padding: 0 1rem;
  -webkit-overflow-scrolling: touch;
}

.iv-tab-content {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Sheet footer ──────────────────────────────────────────────────────────── */

.iv-sheet-footer {
  padding: 0.75rem 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.iv-btn-full {
  width: 100%;
  justify-content: center;
}

.iv-btn-ghost {
  background: transparent;
  color: rgba(255, 255, 255, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.iv-btn-ghost:hover {
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.7);
}

/* ── Tab: Para ti ──────────────────────────────────────────────────────────── */

.iv-summary-card {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 12px;
  padding: 0.85rem;
}

.iv-summary-label {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: rgba(108, 71, 255, 0.7);
  margin-bottom: 0.4rem;
  display: block;
}

.iv-summary-text {
  font-size: 0.84rem;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.55;
  margin: 0;
}

.iv-indicaciones-list {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.iv-indicacion-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.65rem 0.75rem;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 10px;
}

.iv-indicacion-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.iv-indicacion-body {
  flex: 1;
  min-width: 0;
}

.iv-indicacion-text {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.75);
  margin: 0;
  line-height: 1.4;
}

.iv-indicacion-badge {
  font-size: 0.7rem;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
}

.iv-indicacion-action {
  font-size: 0.72rem;
  font-weight: 600;
  color: rgba(108, 71, 255, 0.7);
  background: none;
  border: none;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
  padding: 0;
}

.iv-indicacion-action:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ── Tab: Técnica ──────────────────────────────────────────────────────────── */

.iv-tecnica-box {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  padding: 0.85rem;
  max-height: 220px;
  overflow-y: auto;
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.7);
  line-height: 1.6;
  white-space: pre-wrap;
}

.iv-tech-sections {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.iv-tech-card {
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.04);
  padding: 0.8rem 0.85rem;
}

.iv-tech-card.tone-patient {
  border-color: rgba(96, 165, 250, 0.24);
  background: rgba(37, 99, 235, 0.08);
}

.iv-tech-card.tone-professional {
  border-color: rgba(52, 211, 153, 0.22);
  background: rgba(13, 148, 136, 0.08);
}

.iv-tech-card.tone-observed {
  border-color: rgba(251, 191, 36, 0.22);
  background: rgba(217, 119, 6, 0.08);
}

.iv-tech-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.65rem;
  margin-bottom: 0.5rem;
}

.iv-tech-card-title {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 700;
  line-height: 1.35;
  color: rgba(255, 255, 255, 0.94);
}

.iv-tech-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.24rem 0.5rem;
  border-radius: 999px;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  white-space: nowrap;
  flex-shrink: 0;
}

.iv-tech-badge.tone-patient {
  background: rgba(147, 197, 253, 0.18);
  color: #bfdbfe;
}

.iv-tech-badge.tone-professional {
  background: rgba(110, 231, 183, 0.18);
  color: #a7f3d0;
}

