/* ── Immersive mobile ──────────────────────────────────────────────────────── */

@media (max-width: 640px) {
  .iv-overlay {
    align-items: flex-start;
    justify-content: flex-start;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
  }

  .iv-overlay-done {
    align-items: center;
    overflow: hidden;
  }

  body.voice-immersive-active .sidebar {
    transform: translateY(calc(100% + env(safe-area-inset-bottom))) !important;
  }

  .iv-content {
    min-height: 100dvh;
    justify-content: flex-start;
    gap: 1rem;
    padding: calc(env(safe-area-inset-top, 0px) + 0.8rem) 0.95rem calc(env(safe-area-inset-bottom, 0px) + 1rem);
  }
  .iv-orb { width: 88px; height: 88px; }
  .iv-orb-mic { width: 28px; height: 28px; }
  .iv-ring-1 { width: 112px; height: 112px; }
  .iv-ring-2 { width: 136px; height: 136px; }
  .iv-ring-3 { width: 160px; height: 160px; }
  .iv-timer { font-size: 24px; }
  .iv-title { font-size: 1.05rem; }
  .iv-subtitle {
    font-size: 0.82rem;
    line-height: 1.42;
  }
  .iv-stage-meta {
    gap: 0.45rem;
  }
  .iv-stage-pill,
  .iv-security-chip {
    font-size: 0.7rem;
  }
  .iv-wake-lock-note {
    margin-top: -0.3rem;
    font-size: 0.7rem;
    max-width: 300px;
  }
  .iv-security-row {
    gap: 0.4rem;
  }
  .iv-role-card,
  .iv-context-card {
    padding: 0.8rem;
    max-width: min(100%, 360px);
  }
  .iv-role-grid {
    gap: 0.45rem;
  }
  .iv-role-option {
    padding: 0.62rem 0.65rem;
  }
  .iv-role-option-title,
  .iv-context-text {
    font-size: 0.78rem;
  }
  .iv-role-option-helper,
  .iv-context-helper,
  .iv-role-disclaimer {
    font-size: 0.69rem;
    line-height: 1.38;
  }
  .iv-actions {
    width: 100%;
    margin-top: 0.15rem;
  }
  .iv-btn,
  .iv-btn-full {
    width: min(100%, 360px);
    justify-content: center;
  }
  .iv-sheet {
    height: auto;
    max-height: 72vh;
  }
  .iv-close {
    top: calc(env(safe-area-inset-top, 0px) + 0.8rem);
    right: 1rem;
  }
  .iv-done-top {
    width: min(100%, 360px);
    margin: 0 auto;
    align-items: center;
    padding-top: calc(env(safe-area-inset-top, 0px) + 0.75rem);
    padding-bottom: 0.3rem;
    padding-left: 1rem;
    padding-right: 1rem;
    text-align: center;
  }
  .iv-done-top .iv-orb-green-solid {
    position: relative;
    z-index: 0;
    margin-bottom: 0.15rem;
  }
  .iv-done-title { margin-top: 0.52rem; }
  .iv-audio-player {
    max-width: 100%;
    margin-left: auto;
    margin-right: auto;
  }
  .iv-consent-audio {
    max-width: 100%;
  }
  .iv-consent-audio-label {
    font-size: 0.66rem;
  }
  .iv-family-share-head,
  .iv-family-current-item {
    flex-direction: column;
    align-items: stretch;
  }
  .iv-family-target {
    padding: 0.65rem 0.7rem;
  }
}

/* ── Immersive desktop / notebook ─────────────────────────────────────────── */

@media (min-width: 768px) {
  /* Convert overlay to centered card layout */
  .iv-overlay {
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(13, 11, 20, 0.85);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
  }

  /* Done state: side-by-side layout */
  .iv-overlay > .iv-done-top,
  .iv-overlay > .iv-sheet {
    position: static;
  }

  .iv-overlay-done {
    flex-direction: row;
    align-items: stretch;
    justify-content: center;
    gap: 0;
    padding: 2rem;
  }

  /* Left panel: orb + status */
  .iv-done-top {
    flex: 0 0 320px;
    padding: 2.5rem 2rem;
    justify-content: center;
    background: #0D0B14;
    border-radius: 20px 0 0 20px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-right: none;
  }

  /* Right panel: sheet becomes a card panel */
  .iv-sheet {
    position: static;
    height: auto;
    max-height: 70vh;
    min-height: 400px;
    width: 480px;
    max-width: 480px;
    border-radius: 0 20px 20px 0;
    animation: none;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-left: 1px solid rgba(255, 255, 255, 0.06);
  }

  .iv-sheet-handle {
    display: none;
  }

  .iv-sheet-tabs {
    margin: 1rem 1.25rem 0.75rem;
    padding: 0.15rem 0.25rem;
  }

  .iv-sheet-tab {
    font-size: 0.85rem;
    padding: 0.55rem 0.5rem;
  }

  .iv-sheet-body {
    padding: 0 1.25rem;
  }

  .iv-sheet-footer {
    padding: 1rem 1.25rem;
  }

  .iv-sheet-footer .iv-btn-full {
    max-width: 320px;
    margin: 0 auto;
  }

  /* Larger orb on desktop */
  .iv-done-top .iv-orb {
    width: 110px;
    height: 110px;
  }

  .iv-title {
    font-size: 1.15rem;
  }

  .iv-subtitle {
    font-size: 0.9rem;
  }

  /* Wider tech box */
  .iv-tecnica-box {
    max-height: 300px;
    font-size: 0.85rem;
  }

  /* Share cards in row on wide screens */
  .iv-share-cards {
    gap: 0.6rem;
  }

  .iv-summary-text {
    font-size: 0.88rem;
  }

  /* Audio player sizing */
  .iv-audio-player {
    max-width: 260px;
  }

  /* Recording states: centered card */
  .iv-content {
    max-width: 480px;
    padding: 2.5rem 2rem;
    background: rgba(26, 23, 48, 0.6);
    border-radius: 20px;
    border: 1px solid rgba(255, 255, 255, 0.08);
  }
}

/* Extra wide: more breathing room */
@media (min-width: 1024px) {
  .iv-done-top {
    flex: 0 0 380px;
    padding: 3rem 2.5rem;
  }

  .iv-sheet {
    width: 520px;
    max-width: 520px;
  }
}

/* ══════════════════════════════════════════════════════════════════════════════
   Shared Voice Page — Public view for professionals
   ══════════════════════════════════════════════════════════════════════════════ */

.sv-page {
  min-height: 100vh;
  background: var(--bg, #f8fafc);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 1rem 3rem;
}

/* Header */
.sv-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: 780px;
  padding: 1.25rem 0;
  margin-bottom: 0.5rem;
}
.sv-header-left {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.sv-logo-icon { width: 36px; height: 36px; }
.sv-header-brand {
  display: block;
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--text, #0f172a);
  line-height: 1.2;
}
.sv-header-sub {
  display: block;
  font-size: 0.78rem;
  color: var(--muted, #64748b);
}
.sv-header-badge {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.72rem;
  color: #16a34a;
  background: rgba(22, 163, 74, 0.08);
  border: 1px solid rgba(22, 163, 74, 0.15);
  border-radius: 20px;
  padding: 0.3rem 0.75rem;
  font-weight: 500;
}

/* Loading & Error */
.sv-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  margin-top: 20vh;
  color: var(--muted, #64748b);
}
.sv-spinner {
  width: 32px;
  height: 32px;
  border: 3px solid rgba(37, 99, 235, 0.15);
  border-top-color: #2563eb;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.sv-error-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  margin-top: 16vh;
  text-align: center;
  max-width: 400px;
}
.sv-error-card h2 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text, #0f172a);
}
.sv-error-card p {
  font-size: 0.88rem;
  color: var(--muted, #64748b);
  line-height: 1.5;
}

/* Main card */
.sv-card {
  width: 100%;
  max-width: 780px;
  background: var(--card, #fff);
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 16px;
  overflow: hidden;
