.sv-meta {
  padding: 1.5rem 2rem;
  border-bottom: 1px solid var(--border, #e2e8f0);
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
.sv-meta-row {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
}
.sv-meta-label {
  font-size: 0.78rem;
  color: var(--muted, #64748b);
  min-width: 160px;
  flex-shrink: 0;
  font-weight: 500;
}
.sv-meta-value {
  font-size: 0.88rem;
  color: var(--text, #0f172a);
