}

.sv-tech-sections {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.sv-tech-card {
  padding: 0.95rem 1rem;
  border-radius: 14px;
  border: 1px solid var(--border, #e2e8f0);
  background: #ffffff;
}

.sv-tech-card.tone-patient {
  border-color: rgba(37, 99, 235, 0.16);
  background: rgba(219, 234, 254, 0.42);
}

.sv-tech-card.tone-professional {
  border-color: rgba(13, 148, 136, 0.18);
  background: rgba(204, 251, 241, 0.44);
}

.sv-tech-card.tone-observed {
  border-color: rgba(217, 119, 6, 0.18);
  background: rgba(254, 243, 199, 0.48);
}

.sv-tech-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.8rem;
  margin-bottom: 0.5rem;
}

.sv-tech-card-title {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 700;
  line-height: 1.4;
  color: var(--text, #0f172a);
}

.sv-tech-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.22rem 0.55rem;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.sv-tech-badge.tone-patient {
  background: #dbeafe;
  color: #1d4ed8;
}

.sv-tech-badge.tone-professional {
  background: #ccfbf1;
  color: #0f766e;
}

.sv-tech-badge.tone-observed {
  background: #fef3c7;
  color: #b45309;
}

.sv-tech-badge.tone-neutral {
  background: #e2e8f0;
  color: #475569;
}

.sv-tech-card-body {
  display: flex;
  flex-direction: column;
  gap: 0.36rem;
}

.sv-tech-line {
  margin: 0;
  font-size: 0.88rem;
  line-height: 1.6;
  color: var(--text, #0f172a);
}

/* Indications */
.sv-indications {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
.sv-indication {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.75rem 1rem;
  border-radius: 10px;
  border: 1px solid;
}
.sv-indication-type {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.sv-indication-text {
  font-size: 0.88rem;
  color: var(--text, #0f172a);
  line-height: 1.45;
}
.sv-indication-detail {
  font-size: 0.76rem;
  color: var(--muted, #64748b);
  font-style: italic;
}

/* Footer */
.sv-footer {
  width: 100%;
  max-width: 780px;
  text-align: center;
  padding: 1.5rem 0;
  color: var(--muted, #94a3b8);
  font-size: 0.78rem;
}
.sv-footer-disclaimer {
  margin-top: 0.5rem;
  font-size: 0.72rem;
  max-width: 540px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.5;
}
.sv-footer-expires {
  margin-top: 0.5rem;
  font-size: 0.72rem;
  color: #ca8a04;
  font-weight: 500;
}

/* Shared Voice — mobile */
@media (max-width: 640px) {
  .sv-header { flex-direction: column; align-items: flex-start; gap: 0.5rem; }
  .sv-meta { padding: 1rem 1.25rem; }
  .sv-meta-row { flex-direction: column; gap: 0.15rem; }
  .sv-meta-label { min-width: 0; }
  .sv-section { padding: 1rem 1.25rem; }
  .sv-tech-context { padding: 0.8rem 0.85rem; margin-bottom: 0.75rem; }
  .sv-tech-card { padding: 0.8rem 0.85rem; }
  .sv-tech-card-head { flex-direction: column; gap: 0.45rem; }
  .sv-tech-line { font-size: 0.84rem; line-height: 1.55; }
}

