/* ── 3-dot note menu ─────────────────────────────────────────────── */
.home-note-menu-wrap {
  position: relative;
  flex-shrink: 0;
}

.home-note-menu-trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: #64748b;
  font-size: 1.2rem;
  cursor: pointer;
  line-height: 1;
  padding: 0;
}

.home-note-menu-trigger:hover {
  background: rgba(0,0,0,0.07);
  color: #1e293b;
}

.home-note-menu-popup {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 200;
  min-width: 160px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.12);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.home-note-menu-item {
  display: block;
  width: 100%;
  padding: 0.6rem 1rem;
  text-align: left;
  background: transparent;
  border: none;
  font: inherit;
  font-size: 0.82rem;
  color: #334155;
  cursor: pointer;
}

