.ai-analysis-btn {
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.2rem;
  padding: 1rem 1.35rem 1rem 4.2rem;
  border-radius: 18px;
  border: 1px solid #e2e8f0;
  background: #ffffff;
  color: #0b2a3a;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
  text-align: left;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}

.ai-analysis-btn::before {
  content: "";
  position: absolute;
  left: 1.1rem;
  top: 50%;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  transform: translateY(-50%);
  background: radial-gradient(
      circle at 30% 30%,
      rgba(255, 255, 255, 0.95),
      rgba(186, 230, 253, 0.8) 45%,
      rgba(56, 189, 248, 0.55) 70%,
      rgba(14, 116, 144, 0.4) 100%
    );
  box-shadow: 0 0 22px rgba(94, 196, 255, 0.4), inset 0 0 10px rgba(255, 255, 255, 0.6);
  pointer-events: none;
}

.ai-analysis-glow {
  position: absolute;
  left: 0.4rem;
  top: 50%;
  width: 80px;
  height: 80px;
  transform: translateY(-50%);
  background: radial-gradient(circle, rgba(163, 232, 255, 0.45), transparent 60%);
  pointer-events: none;
}

.ai-analysis-label {
  position: relative;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.ai-analysis-sub {
  position: relative;
  font-size: 0.85rem;
  color: rgba(11, 42, 58, 0.75);
