.consent-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 1.5rem;
  pointer-events: auto;
}

.consent-card {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 1;
  width: 100%;
  max-width: 560px;
  background: #ffffff;
  border-radius: 20px;
  padding: 2rem;
  border: 1px solid #e2e8f0;
  box-shadow: 0 25px 60px rgba(15, 23, 42, 0.2);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-height: calc(100vh - 3rem);
  overflow: auto;
}

.consent-kicker {
  margin: 0;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #94a3b8;
  font-weight: 700;
}

.consent-title {
  margin: 0;
  font-size: 1.5rem;
  color: #0f172a;
}

.consent-text {
  margin: 0;
  color: #475569;
}

.consent-links {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.notification-consent .consent-text {
  margin-bottom: 0.5rem;
}

.consent-switch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.85rem 1rem;
  border-radius: 14px;
  border: 1px solid #e2e8f0;
  background: #f8fafc;
}

.consent-switch-title {
  margin: 0 0 0.2rem;
  font-weight: 700;
  color: #0f172a;
}

.consent-switch-sub {
  margin: 0;
  font-size: 0.85rem;
  color: #64748b;
}

.switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  width: 48px;
  height: 28px;
  flex-shrink: 0;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.switch-slider {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: #e2e8f0;
  transition: all 0.2s ease;
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.6);
}

.switch-slider::before {
  content: "";
  position: absolute;
  width: 22px;
  height: 22px;
  left: 3px;
  top: 3px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.2);
  transition: transform 0.2s ease;
}

.switch input:checked + .switch-slider {
  background: linear-gradient(135deg, #30d7ff, #1f7aff);
}

.switch input:checked + .switch-slider::before {
  transform: translateX(20px);
}

.consent-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

