/* ── Klinip IA · Context snapshot (compact tiles) ── */
.ai-ctx {
  display: grid;
  gap: 0.7rem;
  max-width: 860px;
  margin: 0 auto;
  padding: 0 2rem;
}

.ai-ctx.is-compact {
  padding-top: 1rem;
}

.ai-ctx-toast {
  justify-self: end;
  padding: 0.38rem 0.72rem;
  border-radius: 999px;
  border: 1px solid #dce4f1;
  background: #fbfdff;
  color: var(--brand-primary);
  font-size: 0.72rem;
  font-weight: 700;
}

.ai-ctx-toast.is-success {
  border-color: #b7ead9;
  background: #eefbf6;
  color: #0d9678;
}

.ai-ctx-toast.is-error {
  border-color: #f5c2ca;
  background: #fff6f6;
  color: #b42318;
}

.ai-ctx-rail {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
}

.ai-ctx-tile {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.72rem 0.78rem;
  background: #ffffff;
  border: 1px solid #e6ebf3;
  border-radius: 14px;
  transition: border-color 0.15s, box-shadow 0.15s, transform 0.1s;
}

.ai-ctx-tile:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 14px rgba(15, 23, 42, 0.06);
}

.ai-ctx-tile.is-alerting {
  border-color: #fde68a;
  background: #fffbeb;
}

.ai-ctx-tile-icon {
  flex-shrink: 0;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
}

.ai-ctx-tile-icon svg {
  width: 16px;
  height: 16px;
}

.ai-ctx-tile.tone-violet .ai-ctx-tile-icon { background: #f0eafd; color: #7c3aed; }
.ai-ctx-tile.tone-teal   .ai-ctx-tile-icon { background: #e5f5f1; color: #0d9678; }
.ai-ctx-tile.tone-amber  .ai-ctx-tile-icon { background: #fff3df; color: #c47d12; }

.ai-ctx-tile-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
}

.ai-ctx-tile-label {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #9ea3ae;
}

.ai-ctx-tile-value {
  font-size: 0.88rem;
  font-weight: 700;
  color: #14161a;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ai-ctx-tile-sub {
  font-size: 0.7rem;
  color: #6b7180;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ai-ctx-tile-cta {
  flex-shrink: 0;
  padding: 0.32rem 0.65rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 0.7rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.ai-ctx-tile.tone-violet .ai-ctx-tile-cta { background: #f0eafd; color: #7c3aed; }
.ai-ctx-tile.tone-teal   .ai-ctx-tile-cta { background: #e5f5f1; color: #0d9678; }
.ai-ctx-tile.tone-amber  .ai-ctx-tile-cta { background: #fff3df; color: #c47d12; }

.ai-ctx-tile.tone-violet .ai-ctx-tile-cta:hover { background: #7c3aed; color: #ffffff; }
.ai-ctx-tile.tone-teal   .ai-ctx-tile-cta:hover { background: #0d9678; color: #ffffff; }
.ai-ctx-tile.tone-amber  .ai-ctx-tile-cta:hover { background: #c47d12; color: #ffffff; }

/* Memory as single-line subtle chip row */
.ai-ctx-memory {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem 0.65rem;
  margin: 0;
  padding: 0 0.15rem;
  font-size: 0.7rem;
  color: #6b7180;
}

.ai-ctx-memory-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
}

.ai-ctx-memory-chip em {
  font-style: normal;
  font-weight: 700;
  color: #9ea3ae;
  font-size: 0.66rem;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.ai-ctx-memory-chip b {
  font-weight: 600;
  color: #41444c;
}

.ai-ctx-memory-chip.tone-blue   em { color: var(--brand-primary); }
.ai-ctx-memory-chip.tone-violet em { color: #7c3aed; }
.ai-ctx-memory-chip.tone-teal   em { color: #0d9678; }
.ai-ctx-memory-chip.tone-amber  em { color: #c47d12; }

.ai-ctx-memory-chip i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #cfd3dc;
  margin-left: 0.45rem;
}

/* ── Per-message response chips (minimal) ── */
.ai-response-visual {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-top: 0.75rem;
  padding-top: 0.65rem;
  border-top: 1px dashed #e6ebf3;
}

.ai-response-source {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #9ea3ae;
}

.ai-response-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.ai-response-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.42rem 0.8rem 0.42rem 0.68rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 0.76rem;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.15s, background 0.15s, color 0.15s;
}

.ai-response-chip:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.08);
}

.ai-response-chip svg {
  width: 14px;
  height: 14px;
}

.ai-response-chip.tone-violet { background: #f0eafd; color: #7c3aed; border-color: #e0d4f9; }
.ai-response-chip.tone-teal   { background: #e5f5f1; color: #0d9678; border-color: #cbe8df; }
.ai-response-chip.tone-amber  { background: #fff3df; color: #c47d12; border-color: #fce5b8; }

.ai-response-chip.tone-violet:hover { background: #7c3aed; color: #ffffff; border-color: #7c3aed; }
.ai-response-chip.tone-teal:hover   { background: #0d9678; color: #ffffff; border-color: #0d9678; }

/* Dark mode */
body.theme-dark .ai-ctx-tile {
  background: #111827;
  border-color: rgba(30, 41, 59, 0.7);
}

body.theme-dark .ai-ctx-tile:hover {
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.35);
}

body.theme-dark .ai-ctx-tile.is-alerting {
  background: rgba(120, 53, 15, 0.18);
  border-color: rgba(253, 224, 71, 0.28);
}

body.theme-dark .ai-ctx-tile-value { color: #e5e7ec; }
body.theme-dark .ai-ctx-tile-sub   { color: #8d93a1; }
body.theme-dark .ai-ctx-tile-label { color: #6b7180; }

body.theme-dark .ai-ctx-tile.tone-violet .ai-ctx-tile-icon,
body.theme-dark .ai-ctx-tile.tone-violet .ai-ctx-tile-cta {
  background: rgba(124, 58, 237, 0.18);
  color: #c4b5fd;
}

body.theme-dark .ai-ctx-tile.tone-teal .ai-ctx-tile-icon,
body.theme-dark .ai-ctx-tile.tone-teal .ai-ctx-tile-cta {
  background: rgba(13, 150, 120, 0.18);
  color: #6ee7c7;
}

body.theme-dark .ai-ctx-tile.tone-amber .ai-ctx-tile-icon,
body.theme-dark .ai-ctx-tile.tone-amber .ai-ctx-tile-cta {
  background: rgba(196, 125, 18, 0.2);
  color: #fbd38d;
}

body.theme-dark .ai-ctx-memory-chip b { color: #cbd5e1; }
body.theme-dark .ai-ctx-memory-chip i { background: #334155; }
body.theme-dark .ai-response-visual { border-top-color: rgba(30, 41, 59, 0.7); }
body.theme-dark .ai-response-source { color: #6b7180; }

body.theme-dark .ai-response-chip.tone-violet { background: rgba(124, 58, 237, 0.16); color: #c4b5fd; border-color: rgba(124, 58, 237, 0.3); }
body.theme-dark .ai-response-chip.tone-teal   { background: rgba(13, 150, 120, 0.16); color: #6ee7c7; border-color: rgba(13, 150, 120, 0.3); }

@media (max-width: 980px) {
  .ai-ctx {
    padding-left: 1.2rem;
    padding-right: 1.2rem;
  }

  .ai-ctx-rail {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .ai-ctx {
    gap: 0.6rem;
    padding-left: 0.9rem;
    padding-right: 0.9rem;
  }

  .ai-ctx-tile {
    padding: 0.65rem 0.72rem;
    border-radius: 13px;
    gap: 0.55rem;
  }

  .ai-ctx-tile-icon {
    width: 32px;
    height: 32px;
    border-radius: 9px;
  }

  .ai-ctx-tile-value {
    font-size: 0.85rem;
  }

  .ai-ctx-tile-sub {
    font-size: 0.68rem;
  }

  .ai-ctx-tile-cta {
    padding: 0.3rem 0.6rem;
    font-size: 0.68rem;
  }

  .ai-ctx-memory {
    font-size: 0.68rem;
  }

  .ai-response-chip {
    width: 100%;
    justify-content: center;
    padding: 0.5rem 0.85rem;
  }
}

.ai-chat-inner {
  max-width: 860px;
  margin: 0 auto;
  padding: 1.5rem 2rem 0;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.ai-chat-jump-slot {
  position: sticky;
  bottom: 1rem;
  display: flex;
  justify-content: flex-end;
  max-width: 860px;
  margin: 0 auto;
  padding: 0 2rem 0.9rem;
  pointer-events: none;
}

.ai-message {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
}

.ai-message.is-user {
  flex-direction: row-reverse;
}

.ai-message-column {
  max-width: 680px;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.ai-message.is-user .ai-message-column {
  align-items: flex-end;
}

.ai-message-avatar {
  width: 30px;
  height: 30px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  color: #fff;
  font-size: 0.68rem;
  font-weight: 700;
  flex-shrink: 0;
}

.ai-message-avatar.is-ai {
  background: linear-gradient(135deg, #38bdf8, #2563eb);
}

.ai-message-avatar.is-user {
  background: linear-gradient(135deg, #2aa87a, #0d9678);
}

.ai-message-bubble {
  padding: 0.82rem 1rem;
  border-radius: 16px;
  font-size: 0.88rem;
  line-height: 1.7;
}

.ai-message-bubble.is-ai {
  border: 1px solid #e8eaee;
  border-top-left-radius: 4px;
  background: #fff;
  color: #14161a;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
}

.ai-message-bubble.is-user {
  border-top-right-radius: 4px;
  background: #14161a;
  color: rgba(255, 255, 255, 0.92);
}

.ai-message-bubble p {
  margin: 0;
  white-space: pre-wrap;
}

.ai-message-bubble.is-loading {
  display: inline-flex;
  gap: 0.3rem;
  align-items: center;
}

.ai-message-bubble.is-loading span {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: #9ea3ae;
  animation: aiPulse 1.2s ease infinite;
}

.ai-message-bubble.is-loading span:nth-child(2) {
  animation-delay: 0.16s;
}

.ai-message-bubble.is-loading span:nth-child(3) {
  animation-delay: 0.32s;
}

.ai-inline-attachment {
  display: inline-flex;
  margin-top: 0.65rem;
  padding: 0.28rem 0.55rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.14);
  font-size: 0.72rem;
}

.ai-reference-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.7rem;
}

.ai-reference-chip {
  display: inline-flex;
  flex-direction: column;
  gap: 0.08rem;
  padding: 0.35rem 0.55rem;
  border: 1px solid #e8eaee;
  border-radius: 10px;
  background: #f8fafc;
}

.ai-reference-chip strong {
  font-size: 0.72rem;
  color: #14161a;
}

.ai-message-time {
  font-size: 0.72rem;
  padding: 0 0.2rem;
}

.ai-input-zone {
  position: sticky;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 4;
  flex-shrink: 0;
  padding: 0.85rem 1.8rem 0.45rem;
  background: linear-gradient(to top, #f6f7f9 72%, transparent);
}

.ai-jump-composer-btn {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: 999px;
  border: 1px solid var(--brand-border);
  background: #ffffff;
  color: var(--brand-primary);
  display: grid;
  place-items: center;
  box-shadow: 0 10px 22px rgba(20, 22, 26, 0.16);
  z-index: 12;
  transition: all 0.2s ease;
  pointer-events: auto;
}

.ai-jump-composer-btn:hover {
  transform: translateY(-1px);
  border-color: var(--brand-border);
  background: var(--brand-soft);
}

.ai-jump-composer-btn svg {
  width: 16px;
  height: 16px;
}

.ai-input-shell {
  max-width: 860px;
  margin: 0 auto;
  border: 1px solid #e8eaee;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 8px 24px rgba(20, 22, 26, 0.06);
  overflow: hidden;
}

.ai-upload-strip {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  padding: 0.55rem 0.8rem;
  border-bottom: 1px solid #f0f2f5;
  background: #fafbfd;
}

.ai-upload-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.32rem 0.55rem;
  border: 1px solid #e8eaee;
  border-radius: 10px;
  background: #fff;
  color: #60636e;
  font-size: 0.76rem;
}

.ai-upload-chip button {
  width: 16px;
  height: 16px;
  border-radius: 999px;
  background: #f0f2f5;
  font-size: 0.6rem;
}

.ai-scan-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.32rem 0.55rem;
  border-radius: 999px;
  background: var(--brand-soft);
  color: var(--brand-primary);
  font-size: 0.74rem;
  font-weight: 600;
  margin-left: auto;
}

.ai-voice-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.32rem 0.6rem;
  border-radius: 999px;
  background: rgba(37, 99, 235, 0.08);
  color: #1d4ed8;
  font-size: 0.74rem;
  font-weight: 600;
  margin-left: auto;
}

.ai-voice-badge.is-recording {
  background: rgba(220, 38, 38, 0.1);
  color: #b91c1c;
}

.ai-voice-badge.is-ready {
  background: rgba(22, 163, 74, 0.12);
  color: #166534;
}

.ai-voice-badge.is-error {
  background: rgba(220, 38, 38, 0.1);
  color: #b91c1c;
}

.ai-voice-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: currentColor;
  flex-shrink: 0;
}

.ai-voice-badge.is-recording .ai-voice-dot {
  animation: aiPulse 1s ease infinite;
}

.ai-scan-dot {
  background: var(--brand-primary);
  animation: aiPulse 1s ease infinite;
}

.ai-input-row {
  display: flex;
  align-items: flex-end;
  gap: 0.6rem;
  padding: 0.78rem 0.85rem;
}

.ai-input-field {
  flex: 1;
  min-height: 24px;
  max-height: 92px;
  border: 0;
  outline: 0;
  resize: none;
  background: transparent;
  font: inherit;
  color: #14161a;
  line-height: 1.55;
}

.ai-input-field::placeholder {
  color: #9ea3ae;
}

.ai-input-actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.ai-icon-btn,
.ai-send-btn {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  transition: all 0.18s ease;
}

.ai-icon-btn {
  border: 1px solid #e8eaee;
  color: #60636e;
  background: transparent;
  position: relative;
  overflow: hidden;
}

.ai-icon-btn:hover {
  background: #f6f7f9;
  color: #14161a;
}

.ai-icon-btn.is-disabled {
  opacity: 0.55;
}

.ai-icon-btn.is-recording {
  border-color: rgba(220, 38, 38, 0.3);
  background: rgba(220, 38, 38, 0.08);
  color: #b91c1c;
}

.ai-icon-btn.is-recording:hover {
  background: rgba(220, 38, 38, 0.12);
  color: #991b1b;
}

.ai-icon-btn.is-busy {
  color: var(--brand-primary);
}

.ai-icon-btn.is-busy svg {
  animation: aiSpin 1s linear infinite;
}

.ai-icon-btn input[type="file"] {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.ai-icon-btn input[type="file"]:disabled {
  cursor: not-allowed;
}

.ai-icon-btn svg,
.ai-send-btn svg {
  width: 15px;
  height: 15px;
}

.ai-send-btn {
  border: 0;
  color: #fff;
  background: linear-gradient(135deg, #38bdf8, #2563eb);
}

.ai-send-btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #22b7f6, #1d4ed8);
  transform: scale(1.04);
}

.ai-send-btn:disabled {
  opacity: 0.55;
}

.ai-input-footer {
  justify-content: center;
  margin-top: 0.55rem;
  width: 100%;
}

.ai-mobile-topbar,
.ai-mobile-panel-btn,
.ai-mobile-panel-backdrop,
.ai-right-close {
  display: none;
}

.ai-mobile-topbar {
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  padding: 0.85rem 0.95rem 0;
}

.ai-mobile-panel-backdrop {
  border: 0;
  padding: 0;
}

.ai-mobile-topbar-copy {
  display: grid;
  gap: 0.14rem;
}

.ai-mobile-topbar-copy span {
  color: #60636e;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.ai-mobile-topbar-copy strong {
  color: #14161a;
  font-size: 0.92rem;
  font-weight: 700;
}

.ai-mobile-topbar-copy small {
  color: #60636e;
  font-size: 0.78rem;
  line-height: 1.35;
}

.ai-mobile-panel-btn,
.ai-right-close {
  width: 36px;
  height: 36px;
  border: 1px solid var(--brand-border);
  border-radius: 12px;
  background: #f8fbff;
  color: var(--brand-primary);
  align-items: center;
  justify-content: center;
  place-items: center;
  transition: all 0.18s ease;
}

.ai-mobile-panel-btn:hover,
.ai-right-close:hover {
  background: var(--brand-soft);
  border-color: var(--brand-border);
}

.ai-mobile-panel-btn svg,
.ai-right-close svg {
  width: 16px;
  height: 16px;
}

.ai-right-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  border: 1px solid #e8eaee;
  border-radius: 20px;
  background: #fff;
  min-height: 0;
  overflow: hidden;
  isolation: isolate;
}

.ai-right-profile {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
  padding: 1.18rem 1rem 1rem;
  border-bottom: 1px solid #f0f2f5;
  border-top-left-radius: inherit;
  border-top-right-radius: inherit;
}

.ai-right-avatar {
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: linear-gradient(135deg, #38bdf8, #2563eb);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 0.78rem;
  font-weight: 700;
  flex-shrink: 0;
}

.ai-right-profile-copy {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
  flex: 1;
}

.ai-right-profile-copy strong {
  color: #14161a;
  font-size: 0.86rem;
}

.ai-right-profile-copy span,
.ai-empty-note {
  color: #60636e;
  font-size: 0.74rem;
}

.ai-right-tabs {
  display: flex;
  gap: 0.24rem;
  flex-shrink: 0;
  padding: 0.46rem 0.62rem 0;
  border-bottom: 0;
}

.ai-right-tabs button {
  flex: 1;
  min-width: 0;
  padding: 0.38rem 0.24rem;
  font-size: 0.66rem;
  font-weight: 600;
  color: #9ea3ae;
  border: 1px solid #e8eaee;
  border-radius: 9px 9px 0 0;
  background: #f6f7f9;
  transition: all 0.18s ease;
}

.ai-right-tabs button:hover {
  color: #60636e;
  background: #fafbfd;
}

.ai-right-tabs button.is-active {
  color: var(--brand-primary);
  border-color: var(--brand-border);
  background: var(--brand-soft);
  box-shadow: inset 0 -2px 0 var(--brand-primary);
}

.ai-right-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  gap: 0.8rem;
  padding: 0.9rem;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.ai-right-body > * {
  flex-shrink: 0;
}

.ai-right-body::-webkit-scrollbar {
  display: none;
}

.ai-widget {
  border: 1px solid #e8eaee;
  border-radius: 16px;
  background: #fff;
  overflow: hidden;
}

.ai-widget-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.78rem 0.9rem;
  border-bottom: 1px solid #f0f2f5;
}

.ai-widget-head button,
.ai-clear-history-link {
  padding: 0.34rem 0.62rem;
  border: 1px solid var(--brand-border);
  border-radius: 9px;
  background: #f8fbff;
  color: var(--brand-primary);
  font-size: 0.72rem;
  font-weight: 600;
  flex-shrink: 0;
  transition: all 0.18s ease;
}

.ai-widget-head button:hover {
  border-color: var(--brand-border);
  background: var(--brand-soft);
}

.ai-score-row {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.9rem;
}

.ai-score-ring {
  position: relative;
  width: 72px;
  height: 72px;
  flex-shrink: 0;
}

.ai-score-ring svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.ai-score-ring-track,
.ai-score-ring-fill {
  fill: none;
  stroke-width: 7;
  stroke-linecap: round;
}

.ai-score-ring-track {
  stroke: #f0f2f5;
}

.ai-score-ring-fill {
  stroke: var(--brand-primary);
  transition: stroke-dashoffset 0.8s ease;
}

.ai-score-ring-inner {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  text-align: center;
}

.ai-score-ring-inner strong {
  font-size: 1.1rem;
  color: #14161a;
}

.ai-score-ring-inner span {
  margin-top: -0.2rem;
  font-size: 0.62rem;
  color: #9ea3ae;
}

.ai-score-copy p {
  margin: 0.2rem 0 0;
  line-height: 1.5;
}

.ai-progress-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 0 0.9rem 0.9rem;
}

.ai-progress-row {
  display: grid;
  grid-template-columns: 74px minmax(0, 1fr) 38px;
  align-items: center;
  gap: 0.45rem;
}

.ai-progress-row span,
.ai-progress-row strong {
  font-size: 0.74rem;
}

