@keyframes aiPulse {
  0%, 80%, 100% {
    opacity: 0.35;
    transform: translateY(0);
  }
  40% {
    opacity: 1;
    transform: translateY(-1px);
  }
}

@keyframes aiSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 980px) {
  .ai-copilot-shell {
    grid-template-columns: 1fr;
  }

  .ai-mobile-topbar,
  .ai-mobile-panel-btn,
  .ai-right-close {
    display: flex;
  }

  .ai-mobile-panel-backdrop {
    display: block;
    position: fixed;
    inset: 0;
    background: rgba(15, 23, 42, 0.38);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s ease;
    z-index: 1250;
  }

  .ai-mobile-panel-backdrop.is-visible {
    opacity: 1;
    pointer-events: auto;
  }

  .ai-right-panel {
    min-height: 0;
    position: fixed;
    top: 0.9rem;
    right: 0.9rem;
    bottom: calc(74px + env(safe-area-inset-bottom));
    height: auto;
    max-height: calc(100dvh - 0.9rem - 0.9rem - 74px - env(safe-area-inset-bottom));
    width: min(340px, calc(100vw - 1.8rem));
    border-radius: 22px;
    box-shadow: 0 18px 44px rgba(15, 23, 42, 0.2);
    z-index: 1300;
    transform: translateX(calc(100% + 1.4rem));
    opacity: 0;
    pointer-events: none;
    transition: transform 0.22s ease, opacity 0.22s ease;
  }

  .ai-right-panel.is-mobile-open {
    transform: translateX(0);
    opacity: 1;
    pointer-events: auto;
  }
}

