.home-radar-insights {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 1rem;
}

.home-radar-summary {
  display: flex;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.home-radar-summary-chip {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  min-width: 160px;
  border-radius: 14px;
  border: 1px solid #dce4f1;
  background: #f8fbff;
  padding: 0.72rem 0.82rem;
}

.home-radar-summary-chip span,
.home-radar-alert span,
.home-radar-pattern span {
  display: block;
  color: #64748b;
  font-size: 0.74rem;
  line-height: 1.5;
}

.home-radar-summary-chip strong,
.home-radar-alert strong,
.home-radar-pattern strong {
  display: block;
  margin-bottom: 0.18rem;
  color: #0f172a;
  font-size: 0.8rem;
}

.home-radar-summary-chip.tone-teal {
  border-color: #b7ead9;
  background: #eefbf6;
}

.home-radar-summary-chip.tone-alert {
  border-color: #f6c7cc;
  background: #fff5f5;
}

.home-radar-summary-chip.tone-alert strong {
  color: #9e1c30;
}

.home-radar-summary-chip.tone-ok {
  border-color: #bfe7d1;
  background: #f3fbf7;
}

.home-radar-summary-chip.tone-warn {
  border-color: #ffe0a6;
  background: #fff8ec;
}

.home-radar-summary-chip.tone-warn strong {
  color: #924f06;
}

.home-radar-alert-list {
  display: grid;
  gap: 0.55rem;
}

.home-radar-alert {
  width: 100%;
  border: 1px solid #dce4f1;
  border-radius: 16px;
  background: #fbfdff;
  padding: 0.85rem 0.95rem;
  text-align: left;
  font: inherit;
  cursor: pointer;
}

.home-radar-alert.tone-alert {
  border-color: #f5c2ca;
  background: #fff6f6;
}

.home-radar-alert.tone-warn {
  border-color: #ffe0a6;
  background: #fff8ec;
}

.home-radar-alert.tone-ok {
  border-color: #bfe7d1;
  background: #f3fbf7;
}

.home-radar-pattern {
  border-radius: 14px;
  border: 1px solid #dce4f1;
  background: #ffffff;
  padding: 0.78rem 0.86rem;
}

/* ── Radar: banner de estado general ───────────────────────── */
.home-radar-status {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  border-radius: 14px;
  border: 1px solid #dce4f1;
  background: #f8fbff;
  padding: 0.88rem 1rem;
}

.home-radar-status strong {
  display: block;
  font-size: 0.88rem;
  font-weight: 700;
  color: #0f172a;
}

.home-radar-status span {
  display: block;
  font-size: 0.76rem;
  color: #64748b;
  line-height: 1.5;
}

.home-radar-status.home-radar-status-ok {
  background: #f3fbf7;
  border-color: #bfe7d1;
}

.home-radar-status.home-radar-status-ok strong {
  color: #0a6b3a;
}

.home-radar-status.home-radar-status-warn {
  background: #fff8ec;
  border-color: #ffe0a6;
}

.home-radar-status.home-radar-status-warn strong {
  color: #924f06;
}

.home-radar-status.home-radar-status-alert {
  background: #fff5f5;
  border-color: #f6c7cc;
}

.home-radar-status.home-radar-status-alert strong {
  color: #9e1c30;
}

.home-radar-status.home-radar-status-neutral {
  background: #f8fbff;
  border-color: #dce4f1;
}

/* ── Radar: chip clickable "Por atender" ───────────────────── */
.home-radar-summary-chip-btn {
  cursor: pointer;
  border: 1px solid;
  border-radius: 12px;
  text-align: left;
  font: inherit;
  transition: opacity 0.15s ease;
}

.home-radar-summary-chip-btn:hover {
  opacity: 0.82;
}

/* ── Radar: indicador de navegación en cada alerta ─────────── */
.home-radar-alert-nav {
  display: block;
  font-size: 0.7rem;
  color: #6366f1;
  font-weight: 600;
  margin-top: 0.38rem;
  text-align: left;
  opacity: 0.85;
}

.home-radar-alert.is-expanded {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  border-bottom-color: transparent;
}

/* ── Radar: acordeón de detalle ────────────────────────────── */
.home-radar-alert-detail {
  border: 1px solid #dce4f1;
  border-top: none;
  border-bottom-left-radius: 16px;
  border-bottom-right-radius: 16px;
  background: #ffffff;
  padding: 0.88rem 1rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  /* Cancela el gap del grid para pegarse al botón de arriba */
  margin-top: calc(-0.55rem - 1px);
  animation: radarDetailIn 0.18s ease;
}

@keyframes radarDetailIn {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}

.home-radar-alert-detail strong {
  display: block;
  font-size: 0.8rem;
  font-weight: 700;
  color: #0f172a;
}

.home-radar-alert-detail p {
  font-size: 0.78rem;
  color: #475569;
  line-height: 1.6;
  margin: 0;
}

/* ── Radar: botón "Consultar con Klinip IA" ────────────────── */
.home-radar-alert-ai-btn {
  align-self: flex-start;
  margin-top: 0.25rem;
  border: none;
  border-radius: 999px;
  background: #6366f1;
  color: #ffffff;
  font-family: inherit;
  font-size: 0.76rem;
  font-weight: 600;
  padding: 0.48rem 1rem;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.12s ease;
}

.home-radar-alert-ai-btn:hover {
  background: #4f46e5;
  transform: translateY(-1px);
}

/* ── Dark mode ─────────────────────────────────────────────── */
body.theme-dark .home-radar-status {
  background: rgba(11, 18, 36, 0.82);
  border-color: #243244;
}

body.theme-dark .home-radar-status strong {
  color: #f1f5f9;
}

body.theme-dark .home-radar-status span {
  color: #94a3b8;
}

body.theme-dark .home-radar-status.home-radar-status-ok {
  background: rgba(13, 148, 136, 0.09);
  border-color: rgba(16, 185, 129, 0.25);
}

body.theme-dark .home-radar-status.home-radar-status-ok strong {
  color: #34d399;
}

body.theme-dark .home-radar-status.home-radar-status-warn {
  background: rgba(217, 119, 6, 0.11);
  border-color: rgba(245, 158, 11, 0.25);
}

body.theme-dark .home-radar-status.home-radar-status-warn strong {
  color: #fbbf24;
}

body.theme-dark .home-radar-status.home-radar-status-alert {
  background: rgba(220, 75, 95, 0.1);
  border-color: rgba(244, 114, 182, 0.2);
}

body.theme-dark .home-radar-status.home-radar-status-alert strong {
  color: #f87171;
}

body.theme-dark .home-radar-alert-nav {
  color: #818cf8;
}

body.theme-dark .home-radar-alert-detail {
  background: rgba(11, 18, 36, 0.9);
  border-color: #243244;
}

body.theme-dark .home-radar-alert-detail strong {
  color: #f1f5f9;
}

body.theme-dark .home-radar-alert-detail p {
  color: #94a3b8;
}

/* Acordeón hereda el color del borde de la alerta que lo precede */
.home-radar-alert.tone-warn.is-expanded + .home-radar-alert-detail {
  border-color: #ffe0a6;
  background: #fffdf7;
}

.home-radar-alert.tone-alert.is-expanded + .home-radar-alert-detail {
  border-color: #f5c2ca;
  background: #fff9f9;
}

.home-radar-alert.tone-ok.is-expanded + .home-radar-alert-detail {
  border-color: #bfe7d1;
  background: #f6fdf9;
}

