/* ──────────────────────────────────────────────
   ONBOARDING – pantalla completa al primer login
   ────────────────────────────────────────────── */
.ob-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(2px);
}

.ob-overlay {
  position: relative;
  width: 100%;
  max-width: 420px;
  height: 100%;
  max-height: 100dvh;
  display: flex;
  flex-direction: column;
  background: linear-gradient(160deg, #1e3a8a 0%, #2563eb 45%, #4f46e5 100%);
  overflow: hidden;
  border-radius: 0;
}

@media (min-width: 520px) {
  .ob-overlay {
    max-height: 780px;
    border-radius: 24px;
    box-shadow: 0 32px 80px rgba(15, 23, 42, 0.45);
  }
}

.ob-skip {
  position: absolute;
  top: 1rem;
  right: 1.1rem;
  background: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.3);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  font-family: inherit;
  padding: 0.3rem 0.9rem;
  border-radius: 999px;
  cursor: pointer;
  z-index: 10;
  backdrop-filter: blur(6px);
  transition: background 0.2s;
  letter-spacing: 0.01em;
}

.ob-skip:hover {
  background: rgba(255, 255, 255, 0.3);
}

.ob-skip:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ob-illus-wrap {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4.5rem 2rem 0.5rem;
  min-height: 0;
}

.ob-illus {
  width: 100%;
  max-width: 270px;
  height: auto;
  filter: drop-shadow(0 12px 28px rgba(0, 0, 0, 0.22));
}

.ob-card {
  background: #fff;
  border-radius: 28px 28px 0 0;
  padding: 1.6rem 1.6rem 1.8rem;
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
  box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.18);
  max-height: 58%;
  overflow-y: auto;
  flex-shrink: 0;
}

@media (min-width: 520px) {
  .ob-card {
    border-radius: 28px 28px 24px 24px;
    max-height: 56%;
  }
}

body.theme-dark .ob-card {
  background: #0f172a;
}

.ob-card-content {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.ob-title {
  font-size: 1.28rem;
  font-weight: 700;
  color: #0f172a;
  margin: 0;
  text-align: center;
  line-height: 1.3;
}

body.theme-dark .ob-title {
  color: #f1f5f9;
}

.ob-text {
  font-size: 0.855rem;
  color: #6b7280;
  margin: 0;
  text-align: center;
  line-height: 1.65;
}

body.theme-dark .ob-text {
  color: #94a3b8;
}

/* Footer: dots + navigation */
.ob-footer {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  align-items: center;
}

.ob-dots {
  display: flex;
  gap: 6px;
  align-items: center;
}

.ob-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #e2e8f0;
  transition: all 0.3s ease;
  display: inline-block;
}

body.theme-dark .ob-dot {
  background: #334155;
}

.ob-dot-active {
  background: #2563eb;
  width: 24px;
}

.ob-nav {
  display: flex;
  gap: 0.65rem;
  width: 100%;
  align-items: center;
}

.ob-cta {
  flex: 1;
  background: linear-gradient(135deg, #2563eb 0%, #4f46e5 100%);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 0.85rem 2rem;
  font-size: 0.975rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: opacity 0.2s, transform 0.15s;
  letter-spacing: 0.01em;
}

.ob-cta:hover:not(:disabled) {
  opacity: 0.92;
  transform: translateY(-1px);
}

.ob-cta:active:not(:disabled) {
  transform: translateY(0);
}

.ob-cta:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.ob-back-btn {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 1.5px solid #e2e8f0;
  background: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: #374151;
  transition: border-color 0.2s, background 0.2s;
}

body.theme-dark .ob-back-btn {
  background: #1e293b;
  border-color: #334155;
  color: #cbd5e1;
}

.ob-back-btn:hover:not(:disabled) {
  border-color: #2563eb;
  background: #eff6ff;
}

.ob-back-btn svg {
  width: 20px;
  height: 20px;
}

/* Form elements inside onboarding */
.ob-form {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.ob-input-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: #6b7280;
  margin: 0.2rem 0 0;
}

.ob-input {
  width: 100%;
  padding: 0.72rem 1rem;
  border: 1.5px solid #e2e8f0;
  border-radius: 12px;
  font-family: inherit;
  font-size: 0.875rem;
  color: #0f172a;
  background: #fff;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  box-sizing: border-box;
}

body.theme-dark .ob-input {
  background: #1e293b;
  border-color: #334155;
  color: #f1f5f9;
}

.ob-input:focus {
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
}

/* Yes/No toggle row */
.ob-toggle-row {
  display: flex;
  gap: 0.65rem;
}

.ob-toggle-btn {
  flex: 1;
  padding: 0.65rem;
  border: 1.5px solid #e2e8f0;
  border-radius: 10px;
  background: #f8fafc;
  color: #374151;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.2s;
}

body.theme-dark .ob-toggle-btn {
  background: #1e293b;
  border-color: #334155;
  color: #cbd5e1;
}

.ob-toggle-active {
  border-color: #2563eb;
  background: #eff6ff;
  color: #2563eb;
}

body.theme-dark .ob-toggle-active {
  background: rgba(37, 99, 235, 0.15);
}

/* Notification action buttons (step 1) */
.ob-actions-col {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.ob-action-btn {
  width: 100%;
  padding: 0.75rem;
  border-radius: 10px;
  font-family: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.ob-action-primary {
  background: #eff6ff;
  color: #2563eb;
  border: 1.5px solid #bfdbfe;
}

.ob-action-primary:hover:not(:disabled) {
  background: #dbeafe;
}

.ob-action-ghost {
  background: transparent;
  color: #9ca3af;
  border: 1.5px solid #e2e8f0;
}

.ob-action-ghost:hover {
  background: #f8fafc;
}

.ob-msg {
  font-size: 0.8rem;
  color: #6b7280;
  margin: 0;
  text-align: center;
}

/* Quick action cards (step 4) */
.ob-quick-actions {
  display: flex;
  gap: 0.5rem;
}

.ob-quick-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.45rem;
  padding: 0.8rem 0.4rem;
  border: 1.5px solid #e2e8f0;
  border-radius: 14px;
  background: #f8fafc;
  color: #374151;
  font-family: inherit;
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  text-align: center;
}

body.theme-dark .ob-quick-btn {
  background: #1e293b;
  border-color: #334155;
  color: #cbd5e1;
}

.ob-quick-btn svg {
  width: 24px;
  height: 24px;
  color: #2563eb;
}

.ob-quick-btn:hover {
  border-color: #2563eb;
  background: #eff6ff;
  color: #2563eb;
}

/* ═══════════════════════════════════════════════════════════════════════════
   KlinipFeed — LinkedIn-style health social feed
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Avatar ── */
.kfeed-avatar {
  border-radius: 50%;
  background: linear-gradient(135deg, #1d4ed8, #7c3aed);
  color: #fff;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  letter-spacing: -0.02em;
  overflow: hidden;
}

/* ── Page layout ── */
.kfeed-page {
  max-width: 660px;
  margin: 0 auto;
  padding: 1.25rem 1rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  width: 100%;
}

/* ── Page header ── */
.kfeed-page-header {
  padding: 0.25rem 0 0.5rem;
}

.kfeed-actions-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
  padding: 0.25rem 0 0.5rem;
}
.kfeed-actions-right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}
.kfeed-brand-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.9rem;
}
.kfeed-brand-copy {
  min-width: 0;
}
.kfeed-page-title {
  font-size: 1.18rem;
  font-weight: 800;
  color: var(--text-primary, #0f172a);
  margin: 0;
  letter-spacing: 0;
}
.kfeed-page-subtitle {
  font-size: 0.82rem;
  line-height: 1.45;
  color: var(--text-secondary, #64748b);
  margin: 0.18rem 0 0;
  max-width: 28rem;
}

.kfeed-page-header .kfeed-section-kicker {
  margin-bottom: 0.08rem;
  color: rgba(255, 255, 255, 0.82);
}

.kfeed-care-overview {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
  margin-top: 0.8rem;
}

.kfeed-care-overview-item {
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0.14rem;
  padding: 0.58rem 0.72rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.14);
  backdrop-filter: blur(12px);
}

.kfeed-care-overview-item::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent);
}

.kfeed-care-overview-item span {
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.78);
}

.kfeed-care-overview-item strong {
  font-size: 1.1rem;
  line-height: 1.1;
  color: #ffffff;
  font-weight: 800;
}

.kfeed-care-overview-item.tone-red {
  background:
    radial-gradient(circle at top right, rgba(248, 113, 113, 0.22), transparent 36%),
    rgba(255, 255, 255, 0.12);
}

.kfeed-care-overview-item.tone-blue {
  background:
    radial-gradient(circle at top right, rgba(96, 165, 250, 0.22), transparent 36%),
    rgba(255, 255, 255, 0.12);
}

.kfeed-care-overview-item.tone-teal {
  background:
    radial-gradient(circle at top right, rgba(45, 212, 191, 0.2), transparent 36%),
    rgba(255, 255, 255, 0.12);
}

.kfeed-hero-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-top: 0.95rem;
}

.kfeed-hero-chip {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0.42rem 0.8rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background: rgba(255, 255, 255, 0.16);
  color: rgba(255, 255, 255, 0.94);
  font-size: 0.78rem;
  font-weight: 700;
  backdrop-filter: blur(10px);
}

.kfeed-actions-row-care {
  align-items: flex-end;
  gap: 0.9rem;
  padding: 0.15rem 0 0.2rem;
}

.kfeed-actions-copy {
  flex: 1;
  min-width: 0;
}

.kfeed-section-kicker {
  margin: 0 0 0.24rem;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #2563eb;
}

.kfeed-section-title {
  margin: 0;
  font-size: 1.02rem;
  font-weight: 800;
  color: var(--text-primary, #0f172a);
}

.kfeed-section-subtitle {
  margin: 0;
  font-size: 0.84rem;
  line-height: 1.45;
  color: var(--text-secondary, #64748b);
}

.kfeed-care-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.55rem;
}

.kfeed-care-kpi,
.kfeed-care-panel,
.kfeed-feed-head {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 12px;
  background: linear-gradient(180deg, var(--card-bg, #ffffff) 0%, #f8fbff 100%);
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
}

.kfeed-care-kpi {
  display: flex;
  flex-direction: column;
  gap: 0.18rem;
  padding: 0.7rem 0.8rem;
}

.kfeed-care-kpi::before,
.kfeed-care-panel::before,
.kfeed-feed-head::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(37, 99, 235, 0.24), transparent);
  pointer-events: none;
}

.kfeed-care-kpi span {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #64748b;
}

.kfeed-care-kpi strong {
  font-size: 1.3rem;
  line-height: 1.1;
  color: #0f172a;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.kfeed-care-kpi.tone-red {
  background:
    radial-gradient(circle at top right, rgba(239, 68, 68, 0.12), transparent 34%),
    linear-gradient(180deg, var(--card-bg, #ffffff) 0%, #fff8f8 100%);
}

.kfeed-care-kpi.tone-blue {
  background:
    radial-gradient(circle at top right, rgba(37, 99, 235, 0.14), transparent 36%),
    linear-gradient(180deg, var(--card-bg, #ffffff) 0%, #f7fbff 100%);
}

.kfeed-care-kpi.tone-amber {
  background:
    radial-gradient(circle at top right, rgba(245, 158, 11, 0.16), transparent 36%),
    linear-gradient(180deg, var(--card-bg, #ffffff) 0%, #fffaf1 100%);
}

.kfeed-care-kpi.tone-teal {
  background:
    radial-gradient(circle at top right, rgba(20, 184, 166, 0.14), transparent 36%),
    linear-gradient(180deg, var(--card-bg, #ffffff) 0%, #f4fcfb 100%);
}

.kfeed-care-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) minmax(0, 0.92fr);
  gap: 0.75rem;
}

.kfeed-care-panel {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  padding: 0.85rem 0.95rem 0.95rem;
}

.kfeed-care-panel-head,
.kfeed-feed-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.kfeed-care-panel-head .kfeed-section-title {
  font-size: 0.92rem;
}

.kfeed-inline-link,
.kfeed-clinical-link {
  color: #2563eb;
  font-size: 0.82rem;
  font-weight: 700;
  text-decoration: none;
}

.kfeed-inline-link:hover,
.kfeed-inline-link:focus-visible,
.kfeed-clinical-link:hover,
.kfeed-clinical-link:focus-visible {
