.kfeed-clinical-event p {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}

.kfeed-clinical-event.tone-red {
  background: linear-gradient(180deg, rgba(254, 242, 242, 0.92) 0%, rgba(255, 255, 255, 0.96) 100%);
}

.kfeed-clinical-event.tone-amber {
  background: linear-gradient(180deg, rgba(255, 247, 237, 0.96) 0%, rgba(255, 255, 255, 0.96) 100%);
}

.kfeed-clinical-event.tone-blue {
  background: linear-gradient(180deg, rgba(239, 246, 255, 0.96) 0%, rgba(255, 255, 255, 0.96) 100%);
}

.kfeed-clinical-event.tone-green {
  background: linear-gradient(180deg, rgba(240, 253, 244, 0.96) 0%, rgba(255, 255, 255, 0.96) 100%);
}

.kfeed-clinical-event.tone-violet {
  background: linear-gradient(180deg, rgba(245, 243, 255, 0.96) 0%, rgba(255, 255, 255, 0.96) 100%);
}

.kfeed-permission-card {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.kfeed-permission-card-label {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.kfeed-permission-card strong {
  font-size: 0.76rem;
  font-weight: 600;
  color: #334155;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.kfeed-permission-card.tone-blue .kfeed-permission-card-label {
  color: #2563eb;
}

.kfeed-permission-card.tone-teal .kfeed-permission-card-label {
  color: #0f766e;
}

.kfeed-permission-card.tone-amber .kfeed-permission-card-label {
  color: #b45309;
}

.kfeed-permission-card.tone-slate .kfeed-permission-card-label {
  color: #64748b;
}

.kfeed-permission-note {
  padding-top: 0.05rem;
}

.kfeed-permission-note p {
  margin: 0;
  color: #475569;
  font-size: 0.82rem;
  line-height: 1.45;
}

.kfeed-care-empty {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  border-radius: 14px;
  border: 1px dashed rgba(148, 163, 184, 0.45);
  background: rgba(248, 250, 252, 0.86);
  padding: 0.95rem;
}

.kfeed-care-empty strong {
  color: #0f172a;
  font-size: 0.92rem;
}

.kfeed-feed-head {
  padding: 0.92rem 1rem;
}

.kfeed-feed-head-note {
  max-width: 220px;
  text-align: right;
}

/* ── Composer card ── */
.kfeed-composer-card {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--card-bg, #fff);
  border: 1.5px solid var(--border, #e2e8f0);
  border-radius: 14px;
  padding: 0.9rem 1rem;
}
.kfeed-composer-trigger {
  flex: 1;
  background: var(--hover-bg, #f8fafc);
  border: 1.5px solid var(--border, #e2e8f0);
  border-radius: 30px;
  padding: 0.65rem 1.1rem;
  text-align: left;
  font-size: 0.88rem;
  color: var(--text-secondary, #64748b);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  font-family: inherit;
}
.kfeed-composer-trigger:hover {
  border-color: #2563eb;
  background: #f0f7ff;
  color: #2563eb;
}

/* ── State helpers ── */
.kfeed-state-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  padding: 3rem 0;
  color: var(--text-secondary, #64748b);
  font-size: 0.9rem;
  text-align: center;
}
.kfeed-state-error { color: #ef4444; }
.kfeed-spinner {
  width: 28px;
  height: 28px;
  border: 3px solid var(--border, #e2e8f0);
  border-top-color: #2563eb;
  border-radius: 50%;
  animation: kfeed-spin 0.7s linear infinite;
}
@keyframes kfeed-spin { to { transform: rotate(360deg); } }

/* ── Empty state ── */
.kfeed-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.85rem;
  padding: 3.5rem 1.5rem;
  text-align: center;
}
.kfeed-empty-illus { margin-bottom: 0.25rem; }
.kfeed-empty-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary, #0f172a);
  margin: 0;
}
.kfeed-empty-sub {
  font-size: 0.86rem;
  color: var(--text-secondary, #64748b);
  margin: 0;
  max-width: 300px;
}

/* ── Feed list ── */
.kfeed-list { display: flex; flex-direction: column; gap: 0.75rem; }

/* ── Post card ── */
.kfeed-post-card {
  background: var(--card-bg, #fff);
  border: 1.5px solid var(--border, #e2e8f0);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

/* Post header */
.kfeed-post-header {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem 1rem 0.6rem;
}
.kfeed-post-header-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.08rem;
  min-width: 0;
}
.kfeed-post-header-top {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}
.kfeed-post-author {
  font-weight: 700;
  font-size: 0.92rem;
  color: var(--text-primary, #0f172a);
}
.kfeed-post-type-pill {
  font-size: 0.7rem;
  font-weight: 600;
  border-radius: 20px;
  padding: 0.18rem 0.6rem;
  background: color-mix(in srgb, var(--type-color, #2563eb) 12%, transparent);
  color: var(--type-color, #2563eb);
  border: 1px solid color-mix(in srgb, var(--type-color, #2563eb) 25%, transparent);
  white-space: nowrap;
}
.kfeed-post-profile {
  font-size: 0.78rem;
  color: var(--text-secondary, #64748b);
}
.kfeed-post-time {
  font-size: 0.72rem;
  color: #94a3b8;
  display: flex;
  align-items: center;
  gap: 0.2rem;
}
.kfeed-post-tools {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  flex-shrink: 0;
}
.kfeed-post-menu-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: #94a3b8;
  padding: 0.3rem;
  border-radius: 8px;
  display: flex;
  transition: color 0.15s, background 0.15s;
  flex-shrink: 0;
}
.kfeed-post-menu-btn:hover { color: #ef4444; background: #fef2f2; }
.kfeed-post-menu-btn--edit:hover { color: #2563eb; background: #eff6ff; }

/* Post content */
.kfeed-post-content-wrap { padding: 0 1rem 0.5rem; }
.kfeed-post-content {
  font-size: 0.92rem;
  color: var(--text-primary, #0f172a);
  line-height: 1.58;
  margin: 0;
  white-space: pre-wrap;
}
.kfeed-expand-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 0.88rem;
  color: #2563eb;
  padding: 0;
  font-weight: 600;
}

/* Mentions */
.kfeed-post-mentions {
  padding: 0 1rem 0.4rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  margin: 0;
}
.kfeed-mention { font-size: 0.82rem; color: #2563eb; font-weight: 600; }

/* ── Media card (LinkedIn-style preview) ── */
.kfeed-media-card {
  margin: 0.25rem 0 0;
  border-top: 1px solid var(--border, #e2e8f0);
  overflow: hidden;
}
.kfeed-media-img-wrap { display: block; width: 100%; }
.kfeed-attachment-loading {
  width: 100%;
  height: 200px;
  background: linear-gradient(90deg, #e2e8f0 25%, #f1f5f9 50%, #e2e8f0 75%);
  background-size: 200% 100%;
  animation: kfeed-shimmer 1.2s infinite;
}
@keyframes kfeed-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
body.theme-dark .kfeed-attachment-loading { background: linear-gradient(90deg, #1e293b 25%, #334155 50%, #1e293b 75%); background-size: 200% 100%; }
.kfeed-media-img {
  width: 100%;
  max-height: 340px;
  object-fit: cover;
  display: block;
}
.kfeed-media-card-body {
  padding: 0.85rem 1rem;
  background: var(--hover-bg, #f8fafc);
  border-top: 1px solid var(--border, #e2e8f0);
}
.kfeed-media-card-tag {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.72rem;
  color: var(--type-color, #2563eb);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.3rem;
}
.kfeed-media-card-title {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text-primary, #0f172a);
  margin: 0 0 0.2rem;
}
.kfeed-media-card-sub {
  font-size: 0.76rem;
  color: var(--text-secondary, #64748b);
  margin: 0;
}
.kfeed-media-docs {
  padding: 0.6rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.kfeed-media-doc-link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.82rem;
  color: #2563eb;
  font-weight: 500;
  text-decoration: none;
  padding: 0.35rem 0.65rem;
  background: #eff6ff;
  border-radius: 8px;
  width: fit-content;
  border: none;
  cursor: pointer;
  font-family: inherit;
}
.kfeed-media-doc-link:hover { background: #dbeafe; }

/* ── Stats row ── */
.kfeed-stats-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.4rem 1rem 0;
  gap: 0.5rem;
}
.kfeed-stats-reactions {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.8rem;
  color: var(--text-secondary, #64748b);
}
.kfeed-stats-emojis { font-size: 0.9rem; }
.kfeed-stats-comments {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 0.8rem;
  color: var(--text-secondary, #64748b);
  padding: 0;
  text-decoration: underline;
  text-decoration-color: transparent;
  transition: text-decoration-color 0.15s, color 0.15s;
}
.kfeed-stats-comments:hover { color: #2563eb; text-decoration-color: #2563eb; }

/* ── Actions row ── */
.kfeed-actions-row {
  display: flex;
  align-items: center;
  border-top: 1px solid var(--border, #e2e8f0);
  margin-top: 0.4rem;
  padding: 0.15rem 0.25rem;
}
.kfeed-action-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.6rem 0.25rem;
  border-radius: 10px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-secondary, #64748b);
  transition: background 0.15s, color 0.15s;
  font-family: inherit;
  white-space: nowrap;
}
.kfeed-action-btn:hover { background: var(--hover-bg, #f8fafc); color: #2563eb; }
.kfeed-action-btn:disabled { cursor: default; opacity: 0.7; }
.kfeed-action-btn--reacted { color: #2563eb; }
.kfeed-action-icon { display: flex; align-items: center; font-size: 1.1rem; }
.kfeed-action-label { font-size: 0.82rem; }

/* ── Reaction picker ── */
.kfeed-reaction-wrap { flex: 1; position: relative; display: flex; }
.kfeed-reaction-picker {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--card-bg, #fff);
  border: 1.5px solid var(--border, #e2e8f0);
  border-radius: 40px;
  padding: 0.5rem 0.65rem;
  display: flex;
  gap: 0.5rem;
  box-shadow: 0 6px 30px rgba(0,0,0,0.14);
  z-index: 50;
  white-space: nowrap;
}
.kfeed-reaction-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.2rem 0.3rem;
  border-radius: 10px;
  transition: transform 0.15s, background 0.15s;
}
.kfeed-reaction-option:hover,
.kfeed-reaction-option.selected {
  background: var(--hover-bg, #f8fafc);
  transform: scale(1.2) translateY(-4px);
}
.kfeed-reaction-emoji { font-size: 1.6rem; line-height: 1; display: block; }
.kfeed-reaction-label { font-size: 0.62rem; font-weight: 600; color: var(--text-secondary, #64748b); }

/* ── Comments ── */
/* ── Comments section (Instagram style) ── */
.kfeed-comments-wrap,
.kfeed-comments-section {
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid var(--border, #e2e8f0);
}
.kfeed-comments-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0.6rem 1rem 0;
}
.kfeed-ig-comment {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  padding: 0.45rem 0;
}
.kfeed-ig-comment-body {
  flex: 1;
  min-width: 0;
}
.kfeed-ig-comment-line {
  font-size: 0.86rem;
  color: var(--text-primary, #0f172a);
  line-height: 1.4;
  word-break: break-word;
}
.kfeed-ig-comment-author {
  font-weight: 700;
  margin-right: 0.35em;
}
.kfeed-ig-comment-text {
  font-weight: 400;
}
.kfeed-ig-comment-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 0.2rem;
}
.kfeed-ig-comment-time {
  font-size: 0.72rem;
  color: #94a3b8;
}
.kfeed-ig-comment-delete {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 0.72rem;
  color: #94a3b8;
  padding: 0;
  font-weight: 600;
  transition: color 0.15s;
}
.kfeed-ig-comment-reply {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 0.72rem;
  color: #64748b;
  padding: 0;
  font-weight: 600;
  transition: color 0.15s;
}
.kfeed-ig-comment-reply:hover { color: #2563eb; }
.kfeed-ig-comment-delete:hover { color: #ef4444; }
.kfeed-ig-comment-heart {
  background: none;
  border: none;
  display: inline-flex;
  align-items: center;
  gap: 0.22rem;
  cursor: pointer;
  color: #94a3b8;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 0;
  margin-left: auto;
  line-height: 1;
  flex-shrink: 0;
  transition: color 0.15s;
}
.kfeed-ig-comment-heart:hover { color: #ef4444; }
.kfeed-ig-comment-heart.is-active { color: #ef4444; }
.kfeed-comment-thread {
  display: flex;
  flex-direction: column;
}
.kfeed-comment-thread.depth-1,
.kfeed-comment-thread.depth-2,
.kfeed-comment-thread.depth-3 {
  margin-left: 2.25rem;
}
.kfeed-comment-replies {
  display: flex;
  flex-direction: column;
}

/* ── Comment emoji quick bar ── */
.kfeed-comment-emoji-bar {
  display: flex;
  align-items: center;
  gap: 0.15rem;
  padding: 0.4rem 1rem 0.2rem;
}
.kfeed-comment-emoji-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.15rem;
  padding: 0.2rem 0.25rem;
  border-radius: 6px;
  transition: transform 0.12s, background 0.12s;
  line-height: 1;
}
.kfeed-comment-emoji-btn:hover {
  transform: scale(1.25);
  background: var(--hover-bg, #f1f5f9);
}

/* ── Comment composer ── */
.kfeed-comment-composer {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.5rem 1rem 0.75rem;
  border-top: 1px solid var(--border, #e2e8f0);
}
.kfeed-comment-compose-shell {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}
.kfeed-comment-replying {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0 0.1rem;
  font-size: 0.72rem;
  color: #64748b;
}
.kfeed-comment-replying span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kfeed-comment-replying button {
  background: none;
  border: none;
  color: #2563eb;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0;
  cursor: pointer;
}
.kfeed-comment-input-wrap {
  flex: 1;
  min-width: 0;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--hover-bg, #f8fafc);
  border: 1.5px solid var(--border, #e2e8f0);
  border-radius: 30px;
  padding: 0.45rem 0.85rem;
  overflow: hidden;
  transition: border-color 0.15s;
}
.kfeed-comment-input-wrap:focus-within { border-color: #2563eb; background: var(--card-bg, #fff); }
.kfeed-comment-input {
  flex: 1;
  min-width: 0;
  background: none;
  border: none;
  outline: none;
  font-size: 0.86rem;
  color: var(--text-primary, #0f172a);
  font-family: inherit;
}
.kfeed-comment-input::placeholder { color: #94a3b8; }
.kfeed-comment-mentions-menu {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.35rem;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 16px;
  background: var(--card-bg, #fff);
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.08);
}
.kfeed-comment-mention-option {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  border: none;
  background: none;
  border-radius: 12px;
  padding: 0.35rem 0.45rem;
  color: var(--text-primary, #0f172a);
  text-align: left;
  cursor: pointer;
}
.kfeed-comment-mention-option:hover {
  background: var(--hover-bg, #f8fafc);
}
.kfeed-comment-send-btn {
  background: none;
  border: none;
  cursor: pointer;
  flex-shrink: 0;
  min-width: 4.7rem;
  color: #2563eb;
  font-size: 0.82rem;
  font-weight: 700;
  padding: 0;
  text-align: right;
  transition: color 0.15s;
  white-space: nowrap;
}
.kfeed-comment-send-btn:disabled { color: #93c5fd; cursor: default; }
.kfeed-comment-send-btn:not(:disabled):hover { color: #1d4ed8; }

/* ── Create post preview grid ── */
.kfeed-preview-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  padding: 0.25rem 0;
}
.kfeed-preview-img {
  width: 80px;
  height: 80px;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid var(--border, #e2e8f0);
}
.kfeed-modal-helper {
  font-size: 0.8rem;
  color: var(--text-secondary, #64748b);
  background: var(--hover-bg, #f8fafc);
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 12px;
  padding: 0.65rem 0.8rem;
}

/* ── Load more ── */
.kfeed-load-more { display: flex; justify-content: center; padding: 0.5rem 0 1rem; }

/* ── Publish button ── */
.kfeed-publish-btn {
  background: #2563eb;
  color: #fff;
  border: none;
  border-radius: 30px;
  padding: 0.65rem 1.8rem;
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, box-shadow 0.15s;
  font-family: inherit;
}
.kfeed-publish-btn:hover { background: #1d4ed8; box-shadow: 0 4px 16px rgba(37,99,235,0.3); }
.kfeed-publish-btn:disabled { opacity: 0.5; cursor: not-allowed; box-shadow: none; }

/* ── Modal ── */
.kfeed-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}
.kfeed-modal {
  background: var(--card-bg, #fff);
  border-radius: 16px;
  width: 100%;
  max-width: 540px;
  max-height: 92vh;
  overflow-y: auto;
  box-shadow: 0 24px 64px rgba(0,0,0,0.22);
  display: flex;
  flex-direction: column;
}
.kfeed-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.1rem 1.25rem 0.9rem;
  border-bottom: 1px solid var(--border, #e2e8f0);
  position: sticky;
  top: 0;
  background: var(--card-bg, #fff);
  z-index: 1;
  border-radius: 16px 16px 0 0;
}
.kfeed-modal-title { font-size: 1.05rem; font-weight: 700; color: var(--text-primary, #0f172a); margin: 0; }
.kfeed-modal-close {
  background: none;
  border: none;
  cursor: pointer;
  color: #94a3b8;
  padding: 0.3rem;
  border-radius: 8px;
  display: flex;
  align-items: center;
  transition: color 0.15s, background 0.15s;
}
.kfeed-modal-close:hover { color: #ef4444; background: #fef2f2; }

.kfeed-modal-body {
  padding: 1rem 1.25rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

.kfeed-modal-profile-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.kfeed-modal-profile-info {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.kfeed-modal-profile-select {
  background: none;
  border: none;
  outline: none;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-primary, #0f172a);
  cursor: pointer;
  font-family: inherit;
  padding: 0;
  max-width: 240px;
}
.kfeed-modal-privacy-badge {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.72rem;
  color: var(--text-secondary, #64748b);
  background: var(--hover-bg, #f8fafc);
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 20px;
  padding: 0.15rem 0.55rem;
  width: fit-content;
  font-weight: 600;
}

.kfeed-modal-textarea {
  border: none;
  outline: none;
  resize: none;
  font-size: 0.96rem;
  line-height: 1.55;
  font-family: inherit;
  background: transparent;
  color: var(--text-primary, #0f172a);
  min-height: 120px;
  padding: 0.25rem 0;
}
.kfeed-modal-textarea::placeholder { color: #94a3b8; }

.kfeed-modal-types {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  padding: 0.5rem 0;
  border-top: 1px solid var(--border, #f1f5f9);
  border-bottom: 1px solid var(--border, #f1f5f9);
}
.kfeed-type-chip {
  background: var(--hover-bg, #f8fafc);
  border: 1.5px solid var(--border, #e2e8f0);
  border-radius: 20px;
  padding: 0.3rem 0.75rem;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
  color: var(--text-secondary, #64748b);
  font-family: inherit;
}
.kfeed-type-chip:hover { border-color: #2563eb; color: #2563eb; }
.kfeed-type-chip.active {
  background: color-mix(in srgb, var(--type-color, #2563eb) 12%, transparent);
  border-color: var(--type-color, #2563eb);
  color: var(--type-color, #2563eb);
}

.kfeed-modal-section { display: flex; flex-direction: column; gap: 0.4rem; }
.kfeed-modal-section-label {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text-secondary, #64748b);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.kfeed-modal-mentions { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.kfeed-mention-chip {
  background: var(--hover-bg, #f8fafc);
  border: 1.5px solid var(--border, #e2e8f0);
  border-radius: 20px;
  padding: 0.25rem 0.7rem;
  font-size: 0.8rem;
  cursor: pointer;
  font-weight: 600;
  color: var(--text-secondary, #64748b);
  transition: all 0.15s;
  font-family: inherit;
}
.kfeed-mention-chip:hover { border-color: #7c3aed; color: #7c3aed; }
.kfeed-mention-chip.active { background: #f5f3ff; border-color: #7c3aed; color: #7c3aed; }

.kfeed-modal-toolbar {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  flex-wrap: wrap;
  padding: 0.5rem 0 0;
  border-top: 1px solid var(--border, #f1f5f9);
}
.kfeed-toolbar-btn {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-secondary, #64748b);
  font-size: 0.82rem;
  font-weight: 600;
  padding: 0.4rem 0.65rem;
  border-radius: 8px;
  transition: background 0.15s, color 0.15s;
  font-family: inherit;
}
.kfeed-toolbar-btn:hover { background: var(--hover-bg, #f8fafc); color: #2563eb; }

.kfeed-file-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.3rem; }
.kfeed-file-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.82rem;
  color: var(--text-primary, #0f172a);
  background: var(--hover-bg, #f8fafc);
  border-radius: 8px;
  padding: 0.4rem 0.65rem;
}
.kfeed-file-remove {
  background: none;
  border: none;
  cursor: pointer;
  color: #94a3b8;
  font-size: 1.1rem;
  margin-left: auto;
  padding: 0;
  line-height: 1;
}
.kfeed-file-remove:hover { color: #ef4444; }
.kfeed-modal-error { font-size: 0.83rem; color: #ef4444; margin: 0; }
.kfeed-modal-footer { display: flex; justify-content: flex-end; padding-top: 0.25rem; }

