/* ── Aviso publicación sensible ── */
.kfeed-sensitive-notice {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  background: #fef9ec;
  border: 1px solid #fbbf24;
  border-radius: 10px;
  padding: 0.65rem 0.85rem;
  font-size: 0.8rem;
  color: #92400e;
  line-height: 1.45;
}
body.theme-dark .kfeed-sensitive-notice {
  background: rgba(251, 191, 36, 0.08);
  border-color: rgba(251, 191, 36, 0.35);
  color: #fcd34d;
}

/* ── Avatar con imagen ── */
.kfeed-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
  display: block;
}

/* ── PDF viewer ── */
.kfeed-pdf-viewer {
  border-radius: 12px;
  overflow: hidden;
  border: 1.5px solid var(--border, #e2e8f0);
  background: var(--card-bg, #fff);
  margin: 0.5rem 0;
}
.kfeed-pdf-topbar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 0.85rem;
  border-bottom: 1px solid var(--border, #e2e8f0);
  background: var(--hover-bg, #f8fafc);
}
.kfeed-pdf-name {
  flex: 1;
  font-size: 0.82rem;
  color: var(--text-primary, #0f172a);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kfeed-pdf-open-btn {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  background: #2563eb;
  color: #fff;
  border: none;
  border-radius: 20px;
  padding: 0.3rem 0.75rem;
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  flex-shrink: 0;
  transition: background 0.15s;
}
.kfeed-pdf-open-btn:hover { background: #1d4ed8; }
.kfeed-pdf-embed {
  display: block;
  width: 100%;
  height: 420px;
  border: none;
}
.kfeed-pdf-loading {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  font-size: 0.83rem;
  color: var(--text-secondary, #64748b);
}
body.theme-dark .kfeed-pdf-viewer { border-color: #334155; background: #1e293b; }
body.theme-dark .kfeed-pdf-topbar { background: #0f172a; border-color: #334155; }
body.theme-dark .kfeed-pdf-name { color: #f1f5f9; }

/* Video viewer */
.kfeed-video-viewer {
  border-radius: 12px;
  overflow: hidden;
  border: 1.5px solid var(--border, #e2e8f0);
  background: var(--card-bg, #fff);
  margin: 0.5rem 0;
}
.kfeed-video-topbar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.55rem 0.85rem;
  border-bottom: 1px solid var(--border, #e2e8f0);
  background: var(--hover-bg, #f8fafc);
}
.kfeed-video-name {
  flex: 1;
  min-width: 0;
  font-size: 0.82rem;
  color: var(--text-primary, #0f172a);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kfeed-media-video {
  display: block;
  width: 100%;
  max-height: 460px;
  background: #020617;
}
body.theme-dark .kfeed-video-viewer { border-color: #334155; background: #1e293b; }
body.theme-dark .kfeed-video-topbar { background: #0f172a; border-color: #334155; }
body.theme-dark .kfeed-video-name { color: #f1f5f9; }

/* ── Layout 2 columnas (desktop) ── */
.kfeed-layout-wrapper {
  display: flex;
  align-items: flex-start;
  gap: 1.5rem;
  max-width: 1060px;
  margin: 0 auto;
  padding: 0 1rem;
}
.kfeed-layout-wrapper .kfeed-page {
  flex: 1;
  min-width: 0;
  max-width: 660px;
  margin: 0;
  padding-left: 0;
  padding-right: 0;
}

/* ── Botón abrir sidebar (solo móvil) ── */
.kfeed-family-panel-btn {
  display: none;
  margin-left: auto;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── Backdrop móvil ── */
.kfeed-sidebar-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.4);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease;
  z-index: 1250;
}
.kfeed-sidebar-backdrop.is-visible {
  opacity: 1;
  pointer-events: auto;
}

/* ── Header móvil del sidebar (solo visible en móvil) ── */
.kfeed-sidebar-mobile-header {
  display: none;
}

/* ── Botón cerrar sidebar (solo móvil) ── */
.kfeed-sidebar-close-btn {
  display: none;
}

/* ── Sidebar familia ── */
.kfeed-sidebar {
  display: none;
  flex-direction: column;
  gap: 0.25rem;
  width: 300px;
  flex-shrink: 0;
  padding-top: 1.25rem;
  position: sticky;
  top: 1rem;
  max-height: calc(100dvh - 2rem);
  overflow-y: auto;
  scrollbar-width: none;
}
.kfeed-sidebar::-webkit-scrollbar {
  display: none;
}

@media (min-width: 1050px) {
  .kfeed-sidebar {
    display: flex;
  }
}

/* ── Móvil: sidebar como drawer deslizante ── */
@media (max-width: 960px) {
  .kfeed-care-layout {
    grid-template-columns: 1fr;
  }

  .kfeed-feed-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .kfeed-feed-head-note {
    max-width: none;
    text-align: left;
  }
}

@media (max-width: 1049px) {
  .kfeed-family-panel-btn {
    display: flex;
  }
  .kfeed-sidebar-backdrop {
    display: block;
  }
  .kfeed-sidebar-mobile-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 0.25rem 0.85rem;
    margin-bottom: 0.25rem;
    border-bottom: 1px solid var(--border, #e2e8f0);
  }
  .kfeed-sidebar-mobile-title {
    font-size: 1rem;
    font-weight: 700;
    color: var(--text-primary, #0f172a);
  }
  .kfeed-sidebar-close-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: var(--hover-bg, #f1f5f9);
    border: none;
    cursor: pointer;
    color: var(--text-secondary, #64748b);
    transition: background 0.15s;
  }
  .kfeed-sidebar-close-btn:hover { background: var(--border, #e2e8f0); }
  .kfeed-sidebar {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 0.9rem;
    right: 0.9rem;
    bottom: calc(60px + env(safe-area-inset-bottom));
    width: min(320px, calc(100vw - 1.8rem));
    padding: 1.25rem 1rem;
    background: var(--card-bg, #fff);
    border-radius: 16px;
    box-shadow: 0 24px 64px rgba(0, 0, 0, 0.22);
    overflow: hidden;
    z-index: 1300;
    transform: translateX(calc(100% + 1.8rem));
    opacity: 0;
    pointer-events: none;
    transition: transform 0.22s ease, opacity 0.22s ease;
  }
  .kfeed-sidebar.is-open {
    transform: translateX(0);
    opacity: 1;
    pointer-events: auto;
  }
}

@media (max-width: 600px) {
  .kfeed-sidebar {
    top: 0.55rem;
    right: 0.55rem;
    width: min(300px, calc(100vw - 1.1rem));
    bottom: calc(60px + env(safe-area-inset-bottom));
  }
  .kfeed-sidebar-group-head {
    flex-direction: column;
    align-items: flex-start;
  }
  .kfeed-sidebar-primary-card {
    padding: 0.72rem 0.72rem 0.15rem;
  }
  .kfeed-sidebar-user-row {
    gap: 0.65rem;
    padding-bottom: 0.75rem;
  }
  .kfeed-sidebar-family-header {
    padding-bottom: 0.4rem;
  }
}

.kfeed-sidebar-user-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0 0.25rem 0.85rem;
  border-bottom: 1px solid var(--border, #e2e8f0);
  margin-bottom: 0.5rem;
}
.kfeed-sidebar-group-shell {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  min-height: 0;
}

@media (max-width: 1049px) {
  .kfeed-sidebar-group-shell {
    flex: 1 1 auto;
    overflow-y: auto;
    overflow-x: hidden;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    touch-action: pan-y;
    scrollbar-width: none;
    padding-bottom: 0.9rem;
  }

  .kfeed-sidebar-group-shell::-webkit-scrollbar {
    display: none;
  }
}
.kfeed-sidebar-group-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0 0.25rem;
}
.kfeed-sidebar-group-kicker {
  display: inline-block;
  margin-bottom: 0.2rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #2563eb;
}
.kfeed-sidebar-group-title {
  margin: 0;
  font-size: 1rem;
  font-weight: 800;
  color: var(--text-primary, #0f172a);
}
.kfeed-sidebar-group-count {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0.2rem 0.65rem;
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  font-size: 0.76rem;
  font-weight: 700;
  white-space: nowrap;
}
.kfeed-sidebar-primary-card {
  border: 1px solid #dbeafe;
  border-radius: 18px;
  background: linear-gradient(180deg, #f8fbff 0%, #ffffff 100%);
  padding: 0.8rem 0.85rem 0.2rem;
  box-shadow: 0 14px 30px rgba(37, 99, 235, 0.08);
}
.kfeed-sidebar-primary-card .kfeed-sidebar-user-row {
