  .mobile-section-link {
    font-size: 0.75rem;
    color: #2563eb;
    font-weight: 600;
    background: none;
    border: none;
    cursor: pointer;
    font-family: inherit;
    padding: 0;
  }

  /* ── QUICK ACCESS GRID - estilo Burjeel ── */
  .mobile-quick-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 0.7rem;
  }

  .mobile-quick-item {
    background: white;
    border: 1.5px solid #f1f5f9;
    border-radius: 16px;
    padding: 0.9rem 0.82rem;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0.46rem;
    cursor: pointer;
    text-align: left;
    transition: transform 0.15s, box-shadow 0.15s;
    font-family: inherit;
    box-shadow: 0 2px 10px rgba(15, 23, 42, 0.06);
  }

  .mobile-quick-item:active {
    transform: scale(0.97);
    box-shadow: 0 4px 16px rgba(37, 99, 235, 0.12);
  }

  .mobile-quick-icon {
    width: 40px;
    height: 40px;
    border-radius: 11px;
    display: grid;
    place-items: center;
    flex-shrink: 0;
  }

  .mobile-quick-icon svg {
    width: 19px;
    height: 19px;
  }

  .mobile-quick-label {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0;
    line-height: 1.25;
  }

  .mobile-quick-sub {
    font-size: 0.68rem;
    color: #64748b;
    margin: 0;
    font-weight: 500;
  }

  .mobile-quick-item.tone-blue .mobile-quick-icon  { background: #eff6ff; color: #2563eb; }
  .mobile-quick-item.tone-amber .mobile-quick-icon { background: #fffbeb; color: #d97706; }
  .mobile-quick-item.tone-teal .mobile-quick-icon  { background: #f0fdfa; color: #0d9488; }
  .mobile-quick-item.tone-violet .mobile-quick-icon{ background: #f5f3ff; color: #7c3aed; }
  .mobile-quick-item.tone-sky .mobile-quick-icon   { background: #f0f9ff; color: #0284c7; }
  .mobile-quick-item.tone-green .mobile-quick-icon { background: #f0fdf4; color: #16a34a; }

  /* ── ACTIVITY ITEMS - estilo Burjeel ── */
  .mobile-activity-item {
    background: white;
    border: 1.5px solid #f1f5f9;
    border-radius: 18px;
    padding: 0.9rem 1rem;
    display: flex;
    align-items: center;
    gap: 0.8rem;
    cursor: pointer;
    transition: transform 0.15s;
    margin-bottom: 0.6rem;
    width: 100%;
    text-align: left;
    font-family: inherit;
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.05);
  }

  .mobile-activity-item:active {
    transform: scale(0.98);
    background: #f8fafc;
  }

  .mobile-activity-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: grid;
    place-items: center;
    flex-shrink: 0;
  }

  .mobile-activity-icon svg {
    width: 19px;
    height: 19px;
  }

  .mobile-activity-icon.tone-blue   { background: #eff6ff; color: #2563eb; }
  .mobile-activity-icon.tone-amber  { background: #fffbeb; color: #d97706; }
  .mobile-activity-icon.tone-teal   { background: #f0fdfa; color: #0d9488; }
  .mobile-activity-icon.tone-green  { background: #f0fdf4; color: #16a34a; }

  .mobile-activity-info {
    flex: 1;
    min-width: 0;
  }

  .mobile-activity-title {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 0.12rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .mobile-activity-sub {
    font-size: 0.69rem;
    color: #64748b;
    margin: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-weight: 500;
  }

  .mobile-activity-tag {
    font-size: 0.63rem;
    font-weight: 700;
    padding: 0.2rem 0.55rem;
    border-radius: 999px;
    flex-shrink: 0;
    white-space: nowrap;
  }

  .mobile-activity-tag.tone-blue   { background: #eff6ff; color: #2563eb; }
  .mobile-activity-tag.tone-amber  { background: #fffbeb; color: #d97706; }
  .mobile-activity-tag.tone-teal   { background: #f0fdfa; color: #0d9488; }

  .mobile-empty-state {
    text-align: center;
    padding: 2rem 1rem;
    color: #94a3b8;
    font-size: 0.83rem;
    font-weight: 500;
  }

  /* ── MOBILE DASHBOARD: quita padding al main-content ── */
  .main-content-dashboard {
    padding: 0 !important;
    padding-top: 0 !important;
    padding-bottom: 0 !important;
  }
}

