/* ============================================================
   KLINIP MOBILE SYSTEM REFRESH
   Blanco dominante + azul Klinip + acentos verdes
   ============================================================ */
@media (max-width: 768px), (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
  :root {
    --mobile-font: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", sans-serif;
    --mobile-bg: #ffffff;
    --mobile-surface: #ffffff;
    --mobile-surface-muted: #f8fbff;
    --mobile-border: #dfe8f3;
    --mobile-border-strong: #c8d8ee;
    --mobile-text: #132238;
    --mobile-text-muted: #6d7d92;
    --mobile-blue: #2563eb;
    --mobile-blue-strong: #194fcf;
    --mobile-blue-soft: #eef4ff;
    --mobile-green: #28c18f;
    --mobile-green-strong: #0f9f71;
    --mobile-green-soft: #eafaf4;
    --mobile-shadow-soft: 0 14px 32px rgba(15, 35, 70, 0.08);
    --mobile-shadow-strong: 0 18px 40px rgba(21, 76, 196, 0.18);
    --mobile-radius-xl: 28px;
    --mobile-radius-lg: 22px;
  }

  body,
  .sidebar,
  .topbar,
  .mobile-dashboard,
  .records-mobile-card,
  .appt-burjeel-card,
  .calendar-card,
  .floating-form-card,
  .detail-modal-card,
  .modal-card,
  .mobile-sheet {
    font-family: var(--mobile-font);
  }

  .main-area {
    margin-bottom: calc(84px + env(safe-area-inset-bottom));
    background: var(--mobile-bg);
  }

  .main-content,
  .main-content.main-content-dashboard,
  .main-area,
  .main-area > .main-content {
    background: var(--mobile-bg) !important;
  }

  .main-content {
    padding-top: calc(0.9rem + env(safe-area-inset-top));
  }

  .sidebar {
    background: rgba(255, 255, 255, 0.96) !important;
    border-top: 1px solid rgba(200, 216, 238, 0.9) !important;
    border-radius: 26px 26px 0 0 !important;
    box-shadow: 0 -18px 40px rgba(15, 35, 70, 0.12) !important;
    padding: 0.55rem 0.72rem !important;
    padding-bottom: calc(0.55rem + env(safe-area-inset-bottom)) !important;
    backdrop-filter: blur(18px) !important;
    -webkit-backdrop-filter: blur(18px) !important;
  }

  .sidebar-nav {
    gap: 0.15rem !important;
  }

  .sidebar-link {
    min-height: 56px !important;
    gap: 0.28rem !important;
    padding: 0.5rem 0.28rem !important;
    border-radius: 18px !important;
    color: var(--mobile-text-muted) !important;
    background: transparent !important;
  }

  .sidebar-link.active {
    background: var(--mobile-blue-soft) !important;
    color: var(--mobile-blue) !important;
  }

  .sidebar-link.active .sidebar-icon,
  .sidebar-link.active .sidebar-label {
    color: var(--mobile-blue) !important;
  }

  .sidebar-link[href="/"]:not(.sidebar-more).active,
  .sidebar-link[to="/"]:not(.sidebar-more).active {
    background: var(--mobile-blue-soft) !important;
    color: var(--mobile-blue) !important;
    transform: none !important;
    border-radius: 18px !important;
    box-shadow: none !important;
  }

  .sidebar-link[href="/"]:not(.sidebar-more).active .sidebar-icon,
  .sidebar-link[href="/"]:not(.sidebar-more).active .sidebar-label,
  .sidebar-link[to="/"]:not(.sidebar-more).active .sidebar-icon,
  .sidebar-link[to="/"]:not(.sidebar-more).active .sidebar-label {
    color: var(--mobile-blue) !important;
  }

  .sidebar-link.is-mobile-ai,
  .sidebar-link.is-mobile-ai.active {
    background: transparent !important;
    color: var(--mobile-text-muted) !important;
    box-shadow: none !important;
  }

  .sidebar-link.is-mobile-ai .sidebar-icon,
  .sidebar-link.is-mobile-ai .sidebar-label,
  .sidebar-link.is-mobile-ai.active .sidebar-icon,
  .sidebar-link.is-mobile-ai.active .sidebar-label {
    color: inherit !important;
  }

  .sidebar-link.is-mobile-ai.active {
    color: var(--mobile-blue) !important;
  }

  .sidebar-label {
    font-size: 0.62rem !important;
    font-weight: 700 !important;
    letter-spacing: 0 !important;
  }

  .sidebar-badge {
    background: var(--mobile-green) !important;
    color: #ffffff !important;
    box-shadow: none !important;
  }

  .sidebar-more-menu {
    left: 0.45rem;
    right: 0.45rem;
    bottom: calc(100% + 0.8rem);
    padding: 0.75rem !important;
    border-radius: 24px !important;
    border: 1px solid var(--mobile-border) !important;
    background: rgba(255, 255, 255, 0.98) !important;
    box-shadow: 0 -18px 40px rgba(15, 35, 70, 0.14) !important;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.45rem;
  }

  .sidebar-menu-link {
    min-height: 62px;
    border-radius: 18px !important;
    padding: 0.55rem 0.35rem !important;
    background: transparent !important;
    border: none !important;
    color: var(--mobile-text) !important;
    box-shadow: none !important;
  }

  .sidebar-menu-link.active {
    background: transparent !important;
    border-color: transparent !important;
    color: var(--mobile-blue) !important;
  }

  .topbar.topbar-mobile-compact {
    margin: 0 0.7rem 0.75rem;
    padding: 0.95rem 0.1rem 0.72rem;
    border-radius: 0;
    border: 0;
    background: transparent;
    box-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    position: relative;
    z-index: 4300;
    overflow: visible;
  }

  .topbar.topbar-mobile-compact .topbar-actions,
  .topbar.topbar-mobile-compact .topbar-notifications,
  .topbar.topbar-mobile-compact .topbar-user-wrap {
    position: relative;
    overflow: visible;
  }

  .topbar.topbar-mobile-compact .topbar-title {
    color: var(--mobile-text);
    font-size: 1.02rem;
    font-weight: 800;
    letter-spacing: -0.02em;
  }

  /* Botones del header compact = mismo estilo que mobile-hero-action-btn */
