  .mobile-hero-avatar {
    width: 48px;
    height: 48px;
    border: 1px solid #d7e5fa;
    background: #ffffff;
    color: var(--mobile-blue);
    box-shadow: 0 8px 18px rgba(37, 99, 235, 0.08);
