.route-scene {
  min-height: 100%;
  animation-duration: 0.34s;
  animation-fill-mode: none;
  animation-timing-function: cubic-bezier(.22, 1, .36, 1);
  will-change: transform, opacity;
  transform: none;
  opacity: 1;
}

.route-loading-shell {
  min-height: 52dvh;
  display: grid;
  place-items: center;
  padding: 1rem;
}

.route-loading-card {
  width: min(100%, 320px);
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 0.8rem;
  align-items: center;
  padding: 1rem 1.05rem;
  border-radius: 22px;
  border: 1px solid rgba(207, 222, 242, 0.96);
  background: rgba(255, 255, 255, 0.94);
}

.route-loading-card strong {
  display: block;
  margin: 0;
  color: #0f172a;
  font-size: 0.94rem;
  font-weight: 800;
}

.route-loading-card p {
  margin: 0.12rem 0 0;
  color: #64748b;
  font-size: 0.84rem;
  line-height: 1.45;
}

.route-loading-dot {
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: #2563eb;
  animation: nativeOrbPulse 1.1s ease-in-out infinite;
}

.route-scene-forward.route-scene-mobile {
  animation-name: routeSceneMobileForward;
}

.route-scene-backward.route-scene-mobile {
  animation-name: routeSceneMobileBackward;
}

.route-scene-desktop {
  animation-name: routeSceneDesktopIn;
}

.splash-brand {
