@media (max-width: 768px), (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
  .mobile-dashboard {
    background: #eef4fb;
  }

  .mobile-hero {
    background: #f8fbff !important;
    padding: env(safe-area-inset-top) 0.85rem 0.75rem !important;
    color: #102033;
  }

  .mobile-hero-topbar {
    padding: 0.7rem 0 0.9rem !important;
    background: transparent !important;
    border-bottom: 0 !important;
  }

  .mobile-hero-avatar,
  .mobile-hero-action-btn {
    border-radius: 8px !important;
    background: rgba(255, 255, 255, 0.94) !important;
    border: 1px solid #dbe7f5 !important;
    color: #2563eb !important;
    box-shadow: 0 12px 28px rgba(15, 35, 70, 0.08);
  }

  .mobile-hero-greeting-sub,
  .mobile-hero-greeting-name,
  .mobile-hero-stat-label,
  .mobile-hero-stat-value,
  .mobile-ai-label,
  .mobile-quick-counter,
  .mobile-quick-highlight {
    letter-spacing: 0 !important;
  }

  .mobile-hero-greeting-sub {
    font-size: 0.86rem;
    color: #536579;
  }

  .mobile-hero-greeting-name {
    font-size: 1.18rem;
    color: #101d33;
  }

  .mobile-hero-greeting-name em {
    color: #2563eb;
  }

  .mobile-hero > div:last-child:not(.mobile-hero-health-card) {
    background: transparent !important;
    margin: 0 !important;
    border-radius: 0 !important;
    padding: 0 !important;
    color: inherit !important;
  }

  .mobile-hero-health-card {
    position: relative;
    overflow: hidden;
    margin: 0 !important;
    border-radius: 8px !important;
    padding: 1rem !important;
    color: #ffffff !important;
    background: linear-gradient(145deg, #0f49c8 0%, #2563eb 58%, #36a6ff 100%) !important;
    box-shadow: 0 22px 42px rgba(37, 99, 235, 0.22);
  }

  .mobile-hero-health-main {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 86px;
    gap: 0.85rem;
    align-items: center;
  }

  .mobile-hero-stat-label {
    margin-bottom: 0.55rem;
    color: rgba(255, 255, 255, 0.82);
    font-size: 0.71rem;
    font-weight: 800;
    text-transform: uppercase;
  }

  .mobile-hero-stat-row {
    align-items: center;
    flex-wrap: wrap;
    gap: 0.55rem;
    margin-bottom: 0.6rem;
  }

  .mobile-hero-stat-value {
    font-size: 2.65rem !important;
    font-weight: 850;
    line-height: 1;
    color: #ffffff;
  }

  .mobile-hero-stat-badge {
    margin-bottom: 0;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.22);
    color: #ffffff;
  }

  .mobile-hero-stat-badge.is-warn {
    background: rgba(245, 158, 11, 0.28);
    border-color: rgba(255, 213, 128, 0.34);
  }

  .mobile-hero-stat-badge.is-alert {
    background: rgba(239, 68, 68, 0.26);
    border-color: rgba(252, 165, 165, 0.34);
  }

  .mobile-hero-progress {
    width: 86px;
    height: 86px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background:
      radial-gradient(circle closest-side, #1b4ecf 68%, transparent 70% 100%),
      conic-gradient(from 220deg, #50e3d0 0 var(--health-progress), rgba(255, 255, 255, 0.24) var(--health-progress) 100%);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
  }

  .mobile-hero-progress span {
    font-size: 1.02rem;
    font-weight: 850;
    color: #ffffff;
  }

  .mobile-hero-profile-badge {
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.15);
    color: rgba(255, 255, 255, 0.92);
  }

  .mobile-hero-health-footer {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 0.65rem;
    align-items: center;
    margin-top: 0.85rem;
  }

  .mobile-hero-health-copy {
    margin: 0;
    color: rgba(255, 255, 255, 0.88);
    font-size: 0.86rem;
    line-height: 1.45;
  }

  .mobile-hero-recommendation-btn {
    border: 1px solid rgba(255, 255, 255, 0.24);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.13);
    color: #ffffff;
    min-height: 38px;
    padding: 0.5rem 0.68rem;
    font: inherit;
    font-size: 0.78rem;
    font-weight: 800;
    white-space: nowrap;
  }

  .mobile-action-bar {
    display: none !important;
  }

  .mobile-sheet {
    background: #eef4fb !important;
    padding: 0 0.85rem 1.2rem !important;
  }

  .mobile-intelligence-card {
    width: 100%;
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr) auto;
    gap: 0.75rem;
    align-items: center;
    margin: 0.1rem 0 0.75rem;
    border: 1px solid #dbe7f5;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.96);
    color: #102033;
    padding: 0.82rem;
    text-align: left;
    font: inherit;
    box-shadow: 0 16px 34px rgba(15, 35, 70, 0.08);
  }

  .mobile-intelligence-icon {
    width: 42px;
    height: 42px;
    border-radius: 8px;
    display: grid;
    place-items: center;
    background: linear-gradient(145deg, #38bdf8, #2563eb);
    color: #ffffff;
  }

  .mobile-intelligence-icon svg {
    width: 22px;
    height: 22px;
  }

  .mobile-intelligence-copy {
    min-width: 0;
  }

  .mobile-intelligence-copy strong,
  .mobile-intelligence-copy small {
    display: block;
  }

  .mobile-intelligence-copy strong {
    color: #102033;
    font-size: 0.9rem;
    line-height: 1.25;
  }

  .mobile-intelligence-copy small {
    margin-top: 0.16rem;
    color: #536579;
    font-size: 0.78rem;
    line-height: 1.4;
  }

  .mobile-intelligence-cta {
    border-radius: 8px;
    background: #edf5ff;
    color: #2563eb;
    padding: 0.5rem 0.72rem;
    font-size: 0.78rem;
    font-weight: 850;
    white-space: nowrap;
  }

  .mobile-section {
    padding: 0.2rem 0 0.7rem !important;
  }

  .mobile-section-header {
    margin-bottom: 0.7rem;
  }

  .mobile-section-title {
    color: #102033;
    font-size: 1rem;
  }

  .mobile-quick-counter {
    color: #102033;
    font-size: 0.84rem;
    font-weight: 850;
  }

  .mobile-quick-slide {
    min-height: 128px;
  }

  .mobile-quick-item {
    border-radius: 8px !important;
    border-width: 1px !important;
    padding: 0.82rem !important;
    box-shadow: none !important;
  }

  .mobile-quick-icon {
    border-radius: 8px !important;
  }

  .mobile-quick-label {
    font-size: 0.86rem;
    line-height: 1.25;
  }

  .mobile-quick-sub {
    font-size: 0.72rem;
    line-height: 1.35;
  }
}

@media (max-width: 390px) {
