/* Klinip: lenguaje visual compartido para secciones principales */
:root {
  --klinip-ui-bg: #f5f9fe;
  --klinip-ui-surface: rgba(255, 255, 255, 0.96);
  --klinip-ui-surface-soft: #f8fbff;
  --klinip-ui-border: #dbe7f5;
  --klinip-ui-text: #102033;
