  --klinip-ui-teal: #14b8a6;
  --klinip-ui-green: #22c55e;
  --klinip-ui-amber: #f59e0b;
  --klinip-ui-violet: #7c3aed;
  --klinip-ui-shadow: 0 18px 38px rgba(15, 35, 70, 0.1);
  --klinip-ui-shadow-strong: 0 24px 48px rgba(37, 99, 235, 0.2);
  --klinip-ui-radius: 8px;
  --klinip-ui-hero: linear-gradient(145deg, #0d48c7 0%, #2563eb 58%, #37a8ff 100%);
