  justify-content: flex-start !important;
  min-height: 240px;
  padding: 1.75rem !important;
  border: 1px solid rgba(174, 198, 235, 0.72) !important;
  background:
    radial-gradient(circle at 8% 42%, rgba(255, 255, 255, 0.94) 0 2px, transparent 3px 100%),
    radial-gradient(circle at 94% 34%, rgba(255, 255, 255, 0.9) 0 2px, transparent 3px 100%),
    radial-gradient(circle at 78% 68%, rgba(37, 99, 235, 0.12) 0 1px, transparent 2px 100%),
