.health-hub-page-quick {
  padding: 0.2rem 0 1rem;
}

.health-hub-page-quick .health-hub-native-header {
  margin-bottom: 0.9rem;
}

.health-hub-quick-shell {
  display: grid;
  gap: 0.9rem;
}

.health-hub-quick-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
}

.health-hub-quick-kicker {
  display: block;
  margin-bottom: 0.16rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #64748b;
}

.health-hub-quick-head h2 {
  margin: 0;
  color: #0f172a;
  font-size: clamp(1.7rem, 3.6vw, 2.3rem);
  line-height: 1;
}

.health-hub-quick-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 0.78rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.86);
  border: 1px solid rgba(207, 222, 242, 0.96);
  color: #0f172a;
  font-size: 0.82rem;
  font-weight: 700;
  white-space: nowrap;
}

.health-hub-quick-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.9rem;
}

.health-hub-quick-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.7rem;
  min-height: 196px;
  padding: 1rem 1rem 1.05rem;
  border-radius: 22px;
  border: 1px solid transparent;
  color: #ffffff;
  text-decoration: none;
  overflow: hidden;
  isolation: isolate;
  box-shadow:
    0 18px 34px rgba(15, 35, 70, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
}

.health-hub-quick-card::before,
.health-hub-quick-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.health-hub-quick-card::before {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.2) 0 16%, transparent 16% 100%),
    repeating-linear-gradient(140deg, rgba(255, 255, 255, 0.06) 0 1px, transparent 1px 13px);
  opacity: 0.72;
}

.health-hub-quick-card::after {
  inset: auto 0 0 0;
  height: 48%;
  background:
    linear-gradient(180deg, transparent 0%, rgba(6, 24, 66, 0.18) 100%),
    radial-gradient(circle at bottom right, rgba(255, 255, 255, 0.12), transparent 46%);
}

.health-hub-quick-card > * {
  position: relative;
  z-index: 1;
}

.health-hub-quick-card:hover,
.health-hub-quick-card:focus-visible {
  transform: translateY(-2px);
  filter: saturate(1.04);
  box-shadow:
    0 24px 44px rgba(15, 35, 70, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.health-hub-quick-card.tone-blue {
  background: linear-gradient(145deg, #0d48c7 0%, #2563eb 58%, #3b82f6 100%);
}

.health-hub-quick-card.tone-teal {
  background: linear-gradient(145deg, #0f8f87 0%, #14b8a6 58%, #2dd4bf 100%);
}

.health-hub-quick-card.tone-sky {
  background: linear-gradient(145deg, #0b78b8 0%, #0ea5e9 62%, #38bdf8 100%);
}

.health-hub-quick-card.tone-amber {
  background: linear-gradient(145deg, #c56a08 0%, #f59e0b 62%, #fbbf24 100%);
}

.health-hub-quick-card.tone-violet {
  background: linear-gradient(145deg, #5b4bc4 0%, #7c3aed 62%, #a78bfa 100%);
}

.health-hub-quick-card.tone-green {
  background: linear-gradient(145deg, #13966f 0%, #22c55e 60%, #4ade80 100%);
}

.health-hub-quick-icon {
  width: 64px;
  height: 64px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.14);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.16);
  color: #ffffff;
}

.health-hub-quick-icon svg {
  width: 30px;
  height: 30px;
}

.health-hub-quick-title {
  display: block;
  font-size: clamp(1.5rem, 2.8vw, 2rem);
  line-height: 1.02;
  font-weight: 800;
  color: inherit;
}

.health-hub-quick-highlight {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 0.34rem 0.82rem;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.16);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.16);
  color: inherit;
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.health-hub-quick-subtitle {
  margin-top: auto;
  font-size: 0.92rem;
  font-weight: 600;
  line-height: 1.25;
  color: rgba(255, 255, 255, 0.96);
}

body.theme-dark .health-hub-quick-kicker {
  color: #94a3b8;
}

body.theme-dark .health-hub-quick-head h2,
body.theme-dark .health-hub-quick-count {
  color: #e2e8f0;
}

body.theme-dark .health-hub-quick-count {
  background: rgba(15, 23, 39, 0.88);
  border-color: rgba(96, 165, 250, 0.18);
}

body.theme-dark .health-hub-quick-card {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    0 18px 34px rgba(2, 6, 23, 0.32);
}

body.theme-dark .health-hub-quick-card.tone-blue {
  background: linear-gradient(145deg, #0b3aa4 0%, #1d4ed8 62%, #0f7bbd 100%);
}

body.theme-dark .health-hub-quick-card.tone-teal {
  background: linear-gradient(145deg, #0a6f69 0%, #0f8f87 60%, #14b8a6 100%);
}

body.theme-dark .health-hub-quick-card.tone-sky {
  background: linear-gradient(145deg, #0b5d93 0%, #0284c7 60%, #0ea5e9 100%);
}

body.theme-dark .health-hub-quick-card.tone-amber {
  background: linear-gradient(145deg, #9a5506 0%, #d97706 60%, #f59e0b 100%);
}

body.theme-dark .health-hub-quick-card.tone-violet {
  background: linear-gradient(145deg, #45349a 0%, #6d28d9 60%, #8b5cf6 100%);
}

body.theme-dark .health-hub-quick-card.tone-green {
  background: linear-gradient(145deg, #0d7a58 0%, #16a34a 60%, #22c55e 100%);
}

@media (max-width: 768px) {
  .health-hub-page-quick {
    padding-bottom: 0.85rem;
  }

  .health-hub-quick-head {
    align-items: flex-start;
  }

  .health-hub-quick-head h2 {
    font-size: 1.4rem;
  }

  .health-hub-quick-count {
    padding: 0.36rem 0.62rem;
    font-size: 0.72rem;
  }

  .health-hub-quick-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.72rem;
  }

  .health-hub-quick-card {
    min-height: 164px;
    padding: 0.82rem;
    border-radius: 18px;
    gap: 0.52rem;
  }

  .health-hub-quick-icon {
    width: 52px;
    height: 52px;
    border-radius: 15px;
  }

  .health-hub-quick-icon svg {
    width: 24px;
    height: 24px;
  }

  .health-hub-quick-title {
    font-size: 1.05rem;
  }

  .health-hub-quick-highlight {
    min-height: 28px;
    padding: 0.28rem 0.6rem;
    font-size: 0.64rem;
