  }

  .health-hub-quick-subtitle {
    font-size: 0.78rem;
  }
}

@media (max-width: 390px) {
  .health-hub-quick-grid {
    gap: 0.62rem;
  }

  .health-hub-quick-card {
    min-height: 148px;
