  }

  .health-hub-quick-icon {
    width: 46px;
    height: 46px;
  }

  .health-hub-quick-title {
    font-size: 0.96rem;
  }

  .health-hub-quick-highlight {
    font-size: 0.6rem;
    padding: 0.24rem 0.5rem;
  }

  .health-hub-quick-subtitle {
    font-size: 0.72rem;
  }
}


/* ================================================================
   CLINICAL PANEL — Mi Salud  (.clp-)
   Estilo: Apple Health · sobrio · monochromatic · data-first
   ================================================================ */

.clp-page {
  max-width: 720px;
  margin: 0 auto;
  padding: 0.25rem 0 2rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* ── Loading ── */
.clp-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 3rem 1rem;
  color: #64748b;
  font-size: 0.85rem;
}

.clp-loading-pulse {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2px solid #e2e8f0;
  border-top-color: #2563eb;
  animation: clp-spin 0.8s linear infinite;
}

@keyframes clp-spin {
  to { transform: rotate(360deg); }
}

/* ── Patient header ── */
.clp-patient {
  display: flex;
  align-items: center;
  gap: 0.95rem;
  padding: 1.1rem 1.2rem;
  background: linear-gradient(135deg, #f0f9ff 0%, #ffffff 55%, #f0fdf4 100%);
  border: 1px solid rgba(191, 219, 254, 0.55);
  border-radius: 18px;
  box-shadow: 0 2px 10px rgba(37, 99, 235, 0.06);
}

.clp-patient-icon {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 13px;
  background: linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%);
  color: #2563eb;
  display: grid;
  place-items: center;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.18);
}

.clp-patient-icon svg {
  width: 22px;
  height: 22px;
}

.clp-patient-copy {
  flex: 1;
  min-width: 0;
}

.clp-patient-greet {
  font-size: 0.78rem;
  color: #2563eb;
  font-weight: 600;
  margin: 0;
  letter-spacing: 0.01em;
}

.clp-patient-name {
  font-size: 1.15rem;
  font-weight: 800;
  color: #0f172a;
  margin: 0 0 0.2rem;
  letter-spacing: -0.015em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.clp-patient-meta {
  font-size: 0.78rem;
  color: #64748b;
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.clp-patient-warn {
  flex-shrink: 0;
  color: #d97706;
  display: flex;
}

.clp-patient-warn svg {
  width: 18px;
  height: 18px;
}

/* ── Warning strip ── */
.clp-warn-strip {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.7rem 0.95rem;
  background: #fffbeb;
  border: 1px solid #fde68a;
  border-radius: 12px;
  color: #92400e;
  font-size: 0.8rem;
  font-weight: 500;
}

.clp-warn-strip svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

/* ── Card ── */
.clp-card {
  position: relative;
  background: #ffffff;
  border: 1px solid rgba(226, 232, 240, 0.8);
  border-radius: 16px;
  padding: 1.05rem 1.15rem 1.15rem;
  box-shadow: 0 1px 6px rgba(15, 23, 42, 0.045);
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  overflow: hidden;
}

.clp-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent 0%, currentColor 50%, transparent 100%);
  opacity: 0.9;
}

.clp-card.tone-blue   { color: #2563eb; }
.clp-card.tone-green  { color: #16a34a; }
.clp-card.tone-slate  { color: #64748b; }
.clp-card.tone-indigo { color: #4f46e5; }

.clp-card-head {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.clp-card-icon {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: grid;
  place-items: center;
}

.clp-card-icon svg {
  width: 17px;
  height: 17px;
}

.clp-card-icon.tone-blue   { background: #eff6ff; color: #2563eb; }
.clp-card-icon.tone-green  { background: #f0fdf4; color: #16a34a; }
.clp-card-icon.tone-slate  { background: #f1f5f9; color: #475569; }
.clp-card-icon.tone-indigo { background: #eef2ff; color: #4f46e5; }

.clp-card-titles {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.clp-card-title {
  font-size: 0.98rem;
  font-weight: 700;
  color: #0f172a;
  margin: 0;
  letter-spacing: -0.01em;
}

.clp-card-sub {
  font-size: 0.72rem;
  color: #94a3b8;
  margin: 0;
  font-weight: 500;
}

.clp-card-link {
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: #2563eb;
  text-decoration: none;
  white-space: nowrap;
}

.clp-card-link svg {
  width: 13px;
  height: 13px;
}

.clp-card-link:hover { text-decoration: underline; }

/* ── Appointment body ── */
.clp-appt-body {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.clp-appt-main {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.clp-appt-tag {
  display: inline-block;
  align-self: flex-start;
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #2563eb;
  background: #eff6ff;
  padding: 0.18rem 0.5rem;
  border-radius: 6px;
  margin-bottom: 0.25rem;
}

.clp-appt-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: #0f172a;
  margin: 0;
  letter-spacing: -0.01em;
  text-transform: capitalize;
}

.clp-appt-when {
  font-size: 0.8rem;
  color: #64748b;
  margin: 0;
  text-transform: capitalize;
}

.clp-appt-note {
  font-size: 0.78rem;
  color: #475569;
  margin: 0.3rem 0 0;
  padding: 0.5rem 0.7rem;
  background: #f8fafc;
  border-left: 3px solid #cbd5e1;
  border-radius: 4px;
}

.clp-appt-stats {
  display: flex;
  gap: 0.6rem;
  padding-top: 0.75rem;
  border-top: 1px solid rgba(226, 232, 240, 0.7);
}

.clp-appt-stat {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
}

.clp-appt-stat strong {
  font-size: 1.15rem;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.02em;
  line-height: 1;
}

.clp-appt-stat span {
  font-size: 0.7rem;
  color: #64748b;
  font-weight: 500;
}

/* ── Medication tracker ── */
.clp-med-list {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.clp-med-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 0;
  border-bottom: 1px solid rgba(226, 232, 240, 0.6);
  transition: opacity 0.2s;
}

.clp-med-row:last-child {
  border-bottom: none;
}

.clp-med-row.is-done {
  opacity: 0.55;
}

.clp-med-row.is-done .clp-med-name {
  text-decoration: line-through;
}

.clp-med-info {
  flex: 1;
  min-width: 0;
}

.clp-med-name {
  font-size: 0.9rem;
  font-weight: 600;
  color: #0f172a;
  margin: 0 0 0.15rem;
  line-height: 1.25;
  word-break: break-word;
}

.clp-med-detail {
  font-size: 0.74rem;
  color: #64748b;
  margin: 0;
  line-height: 1.35;
  word-break: break-word;
}

.clp-med-next {
  font-size: 0.76rem;
  color: #2563eb;
  margin: 0.25rem 0 0;
  line-height: 1.35;
  font-weight: 700;
  word-break: break-word;
}

.clp-med-check {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.5rem 0.85rem 0.5rem 0.7rem;
  border-radius: 999px;
  border: 1.5px solid #bbf7d0;
  background: #f0fdf4;
  color: #16a34a;
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  line-height: 1;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.1s;
}

.clp-med-check:hover:not(:disabled) {
  background: #dcfce7;
  border-color: #86efac;
  transform: translateY(-1px);
}

.clp-med-check:active:not(:disabled) {
  transform: translateY(0);
}

.clp-med-check.is-done {
  background: #16a34a;
  border-color: #16a34a;
  color: #ffffff;
  cursor: default;
}

.clp-med-check svg {
  width: 15px;
  height: 15px;
  flex-shrink: 0;
}

.clp-med-check-label {
  line-height: 1;
  white-space: nowrap;
}

.clp-med-check:disabled {
  cursor: default;
}

.clp-med-spin {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid #cbd5e1;
  border-top-color: #475569;
  animation: clp-spin 0.7s linear infinite;
}

/* ── Documents ── */
.clp-doc-list {
  display: flex;
  flex-direction: column;
}

.clp-doc-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 0;
  color: inherit;
  text-decoration: none;
  border-bottom: 1px solid rgba(226, 232, 240, 0.6);
  transition: background 0.12s;
}

.clp-doc-row:last-of-type {
  border-bottom: none;
}

.clp-doc-row:hover {
  background: #f8fafc;
}

.clp-doc-row > svg {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  color: #94a3b8;
}

.clp-doc-info {
  flex: 1;
  min-width: 0;
}

.clp-doc-name {
  font-size: 0.86rem;
  font-weight: 600;
  color: #0f172a;
  margin: 0 0 0.15rem;
  line-height: 1.25;
  word-break: break-word;
}

.clp-doc-meta {
  font-size: 0.72rem;
  color: #64748b;
  margin: 0;
  line-height: 1.35;
  word-break: break-word;
}

/* ── Activity feed ── */
.clp-activity-list {
  display: flex;
  flex-direction: column;
}

.clp-activity-row {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.55rem 0;
  border-bottom: 1px solid rgba(226, 232, 240, 0.5);
}

.clp-activity-row:last-child {
  border-bottom: none;
}

.clp-activity-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: #f1f5f9;
  color: #475569;
  display: grid;
  place-items: center;
  margin-top: 2px;
}

.clp-activity-icon svg {
  width: 14px;
  height: 14px;
}

.clp-activity-copy {
  flex: 1;
  min-width: 0;
}

.clp-activity-text {
  font-size: 0.82rem;
  color: #0f172a;
  margin: 0 0 0.1rem;
  line-height: 1.3;
}

.clp-activity-time {
  font-size: 0.7rem;
  color: #94a3b8;
  margin: 0;
}

/* ── Quick nav (secondary) ── */
.clp-quick-wrap {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  margin-top: 0.3rem;
}

.clp-quick-heading {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #94a3b8;
  margin: 0;
  padding: 0 0.25rem;
}

.clp-quick-nav {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.5rem;
}

.clp-quick-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.9rem 0.4rem;
  background: #ffffff;
  border: 1px solid rgba(226, 232, 240, 0.8);
  border-radius: 13px;
  color: #334155;
  text-decoration: none;
  font-size: 0.72rem;
  font-weight: 600;
  text-align: center;
  transition: border-color 0.15s, background 0.15s, transform 0.1s;
}

.clp-quick-item:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
}

.clp-quick-item:active {
  transform: translateY(0);
}

.clp-quick-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: grid;
  place-items: center;
}

.clp-quick-icon svg {
  width: 18px;
  height: 18px;
}

.clp-quick-item.tone-blue   .clp-quick-icon { background: #eff6ff; color: #2563eb; }
.clp-quick-item.tone-green  .clp-quick-icon { background: #f0fdf4; color: #16a34a; }
.clp-quick-item.tone-indigo .clp-quick-icon { background: #eef2ff; color: #4f46e5; }
.clp-quick-item.tone-slate  .clp-quick-icon { background: #f1f5f9; color: #475569; }

.clp-quick-item.tone-blue:hover   { border-color: #bfdbfe; }
.clp-quick-item.tone-green:hover  { border-color: #bbf7d0; }
.clp-quick-item.tone-indigo:hover { border-color: #c7d2fe; }
.clp-quick-item.tone-slate:hover  { border-color: #cbd5e1; }

/* ── More link ── */
.clp-more-link {
  display: inline-block;
  margin-top: 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: #2563eb;
  text-decoration: none;
}

.clp-more-link:hover {
  text-decoration: underline;
}

/* ── Empty states ── */
.clp-empty {
  font-size: 0.82rem;
  color: #94a3b8;
  padding: 0.5rem 0;
  font-style: italic;
}

/* ── Dark mode ── */
body.theme-dark .clp-patient {
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.12) 0%, rgba(17, 24, 39, 1) 55%, rgba(22, 163, 74, 0.1) 100%);
  border-color: rgba(37, 99, 235, 0.2);
  box-shadow: none;
}

body.theme-dark .clp-card,
body.theme-dark .clp-quick-item {
  background: #111827;
  border-color: rgba(30, 41, 59, 0.6);
  box-shadow: none;
}

body.theme-dark .clp-patient-icon {
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.25) 0%, rgba(37, 99, 235, 0.4) 100%);
  color: #93c5fd;
  box-shadow: none;
}

body.theme-dark .clp-patient-greet {
  color: #60a5fa;
}

body.theme-dark .clp-card-sub {
  color: #64748b;
}

body.theme-dark .clp-patient-name,
body.theme-dark .clp-card-title,
body.theme-dark .clp-appt-title,
body.theme-dark .clp-med-name,
body.theme-dark .clp-doc-name,
body.theme-dark .clp-activity-text,
body.theme-dark .clp-appt-stat strong {
  color: #e2e8f0;
}

body.theme-dark .clp-patient-meta,
body.theme-dark .clp-appt-when,
body.theme-dark .clp-med-detail,
body.theme-dark .clp-doc-meta,
body.theme-dark .clp-appt-stat span {
  color: #94a3b8;
}

body.theme-dark .clp-med-next {
  color: #7dd3fc;
}

body.theme-dark .clp-activity-time,
body.theme-dark .clp-empty {
  color: #64748b;
}

body.theme-dark .clp-warn-strip {
  background: rgba(120, 53, 15, 0.18);
  border-color: rgba(253, 224, 71, 0.2);
  color: #fde68a;
}

body.theme-dark .clp-card-icon.tone-blue   { background: rgba(37, 99, 235, 0.15); color: #60a5fa; }
body.theme-dark .clp-card-icon.tone-green  { background: rgba(22, 163, 74, 0.15); color: #4ade80; }
body.theme-dark .clp-card-icon.tone-slate  { background: rgba(71, 85, 105, 0.2); color: #94a3b8; }
body.theme-dark .clp-card-icon.tone-indigo { background: rgba(79, 70, 229, 0.18); color: #a5b4fc; }

body.theme-dark .clp-card-link,
body.theme-dark .clp-more-link {
  color: #60a5fa;
}

body.theme-dark .clp-appt-tag {
  background: rgba(37, 99, 235, 0.15);
  color: #60a5fa;
}

body.theme-dark .clp-appt-note {
  background: rgba(30, 41, 59, 0.5);
  border-left-color: #475569;
  color: #cbd5e1;
}

body.theme-dark .clp-appt-stats {
  border-top-color: rgba(30, 41, 59, 0.7);
}

body.theme-dark .clp-med-row,
body.theme-dark .clp-doc-row,
body.theme-dark .clp-activity-row {
  border-bottom-color: rgba(30, 41, 59, 0.5);
}

body.theme-dark .clp-doc-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

body.theme-dark .clp-doc-row > svg,
body.theme-dark .clp-quick-icon {
  color: #64748b;
}

body.theme-dark .clp-activity-icon {
  background: rgba(71, 85, 105, 0.2);
  color: #94a3b8;
}

body.theme-dark .clp-med-check {
  background: rgba(22, 163, 74, 0.12);
  border-color: rgba(22, 163, 74, 0.35);
  color: #4ade80;
}

body.theme-dark .clp-med-check:hover:not(:disabled) {
  background: rgba(22, 163, 74, 0.2);
  border-color: #16a34a;
}

body.theme-dark .clp-med-check.is-done {
  background: #16a34a;
  border-color: #16a34a;
  color: #ffffff;
}

body.theme-dark .clp-quick-heading {
  color: #475569;
}

body.theme-dark .clp-quick-item {
  color: #cbd5e1;
}

body.theme-dark .clp-quick-item.tone-blue   .clp-quick-icon { background: rgba(37, 99, 235, 0.18); color: #60a5fa; }
body.theme-dark .clp-quick-item.tone-green  .clp-quick-icon { background: rgba(22, 163, 74, 0.18); color: #4ade80; }
body.theme-dark .clp-quick-item.tone-indigo .clp-quick-icon { background: rgba(79, 70, 229, 0.22); color: #a5b4fc; }
body.theme-dark .clp-quick-item.tone-slate  .clp-quick-icon { background: rgba(71, 85, 105, 0.25); color: #94a3b8; }

body.theme-dark .clp-loading {
  color: #64748b;
}

body.theme-dark .clp-loading-pulse {
  border-color: #334155;
  border-top-color: #60a5fa;
}

/* ── Mobile ── */
@media (max-width: 768px) {
  .clp-page {
    padding: 0 0 2rem;
    gap: 0.85rem;
  }

  .clp-patient {
    padding: 0.85rem 0.95rem;
    border-radius: 14px;
  }

  .clp-patient-icon {
    width: 38px;
    height: 38px;
  }

  .clp-patient-name {
    font-size: 0.95rem;
  }

  .clp-patient-meta {
    font-size: 0.72rem;
  }

  .clp-card {
    padding: 0.9rem 0.95rem 1rem;
    border-radius: 14px;
    gap: 0.75rem;
  }

  .clp-card-title {
    font-size: 0.88rem;
  }

  .clp-appt-title {
    font-size: 1rem;
  }

  .clp-appt-stat strong {
    font-size: 1.05rem;
  }

  .clp-quick-nav {
    gap: 0.4rem;
  }

  .clp-quick-item {
    padding: 0.75rem 0.25rem;
    font-size: 0.68rem;
    border-radius: 10px;
  }

  .clp-med-row {
    align-items: flex-start;
    gap: 0.6rem;
    padding: 0.75rem 0;
  }

  .clp-med-check {
    padding: 0.45rem 0.65rem;
    font-size: 0.72rem;
    gap: 0.3rem;
    margin-top: 0.15rem;
  }

  .clp-med-next {
    font-size: 0.72rem;
  }

  .clp-med-check svg {
    width: 13px;
    height: 13px;
  }

  .clp-doc-row,
  .clp-activity-row {
    gap: 0.65rem;
  }

  .clp-card-link {
    font-size: 0.72rem;
  }

  .clp-card-sub {
    font-size: 0.7rem;
  }
}
/* Historial por episodios clínicos */
.history-episodes-hero,
.history-episodes-controls,
.history-episode-card,
.history-legacy-card {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(174, 198, 235, 0.78) !important;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(245, 249, 255, 0.98)) !important;
  box-shadow: 0 18px 36px rgba(37, 99, 235, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.96) !important;
}

.history-episodes-hero {
  display: grid;
  gap: 1rem;
  padding: 1.25rem !important;
}

.history-episodes-hero-copy {
  display: grid;
  gap: 0.42rem;
}

.history-episodes-kicker {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  padding: 0.28rem 0.62rem;
  border-radius: 999px;
  background: rgba(37, 99, 235, 0.1);
  color: #1d4ed8;
  font-size: 0.76rem;
  font-weight: 900;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.history-episodes-hero .card-title {
  margin: 0;
}

.history-episodes-hero .muted,
.history-episodes-hero-note {
  margin: 0;
}

.history-episodes-hero-note {
  color: #44516b;
  font-size: 0.98rem;
}

.history-episodes-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.72rem;
}

.history-episodes-stat {
  display: grid;
  gap: 0.18rem;
  padding: 0.85rem;
  border-radius: 18px;
  border: 1px solid rgba(174, 198, 235, 0.76);
  background: rgba(255, 255, 255, 0.86);
}

.history-episodes-stat strong {
  color: #14213d;
  font-size: 1.45rem;
  line-height: 1;
}

.history-episodes-stat span {
  color: #66748f;
  font-size: 0.92rem;
  font-weight: 700;
}

.history-episodes-controls {
  display: grid;
  gap: 0.92rem;
  padding: 1rem !important;
}

.history-episodes-controls-grid {
  display: grid;
  grid-template-columns: minmax(220px, 280px) minmax(0, 1fr);
  gap: 0.8rem;
}

.history-episodes-filter-row {
  display: flex;
  gap: 0.55rem;
  overflow-x: auto;
  scrollbar-width: none;
}

.history-episodes-filter-row::-webkit-scrollbar {
  display: none;
}

.history-episodes-filter-btn {
  flex: 0 0 auto;
  min-height: 42px;
  padding-inline: 0.95rem !important;
}

.history-episodes-stack {
  display: grid;
  gap: 0.9rem;
}

.history-episodes-empty {
  padding: 1.1rem !important;
  border: 1px dashed rgba(174, 198, 235, 0.88);
  border-radius: 22px;
  color: #4e5d78;
  background: rgba(248, 251, 255, 0.96);
  text-align: left;
}

.history-episodes-transition h3,
.history-legacy-head h3,
.history-episode-title {
  margin: 0;
  color: #102033;
}

.history-episodes-transition p {
  margin: 0.45rem 0 0;
  color: #5f6f8c;
}

.history-episode-card {
  display: grid;
  gap: 0.92rem;
  padding: 1rem !important;
}

.history-episode-card-head,
.history-episode-eyebrow,
.history-legacy-head,
.history-episode-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem;
}

.history-episode-eyebrow {
  flex-wrap: wrap;
  justify-content: flex-start;
}

.history-episode-type,
.history-episode-status,
.history-episode-tag {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0.28rem 0.72rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.history-episode-type {
  background: rgba(37, 99, 235, 0.1);
  color: #1d4ed8;
}

.history-episode-status {
  letter-spacing: 0.03em;
}

.history-episode-status.tone-active {
  background: rgba(16, 185, 129, 0.14);
  color: #047857;
}

.history-episode-status.tone-attention {
  background: rgba(245, 158, 11, 0.16);
  color: #b45309;
}

.history-episode-status.tone-closed {
  background: rgba(148, 163, 184, 0.18);
  color: #475569;
}

.history-episode-toggle {
  min-height: 42px;
  padding-inline: 0.95rem !important;
}

.history-episode-summary {
  margin: -0.25rem 0 0;
  color: #5a6a85;
  font-size: 1rem;
  line-height: 1.5;
}

.history-episode-highlights,
.history-episode-related-grid,
.history-episode-detail-grid {
  display: grid;
  gap: 0.72rem;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.history-episode-detail-grid,
.history-episode-related-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.history-episode-highlight,
.history-episode-panel {
  border: 1px solid rgba(174, 198, 235, 0.78);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.88);
}

.history-episode-highlight {
  display: grid;
  gap: 0.34rem;
  padding: 0.86rem 0.92rem;
}

.history-episode-highlight span {
  color: #66748f;
  font-size: 0.84rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.history-episode-highlight strong {
  color: #102033;
  font-size: 1rem;
  line-height: 1.45;
}

.history-episode-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.48rem;
}

.history-episode-tag {
  min-height: 0;
  padding-block: 0.22rem;
  background: rgba(226, 232, 240, 0.78);
  color: #475569;
  font-size: 0.74rem;
  letter-spacing: 0.05em;
}

.history-episode-detail {
  display: grid;
  gap: 0.8rem;
}

.history-episode-panel {
  display: grid;
  gap: 0.75rem;
  padding: 0.92rem;
}

.history-episode-panel-head h4 {
  margin: 0;
  color: #102033;
  font-size: 1rem;
}

.history-episode-panel-head span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 34px;
  min-height: 34px;
  padding: 0 0.6rem;
  border-radius: 999px;
  background: rgba(37, 99, 235, 0.1);
  color: #1d4ed8;
  font-weight: 900;
}

.history-episode-task-list,
.history-episode-timeline,
.history-episode-mini-list,
.history-legacy-list {
  display: grid;
  gap: 0.62rem;
}

.history-episode-task,
.history-episode-mini-item,
.history-legacy-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.72rem;
  padding: 0.8rem 0.84rem;
  border-radius: 18px;
  border: 1px solid rgba(215, 226, 244, 0.95);
  background: rgba(248, 251, 255, 0.95);
}

.history-episode-task strong,
.history-episode-mini-item strong,
.history-legacy-item strong {
  color: #102033;
  font-size: 0.98rem;
}

.history-episode-task p,
.history-episode-mini-item p,
.history-legacy-item p,
.history-episode-empty,
.history-episode-more {
  margin: 0.22rem 0 0;
  color: #607089;
  line-height: 1.45;
}

.history-episode-task span {
  flex: 0 0 auto;
  min-width: 84px;
  padding: 0.34rem 0.66rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 900;
  text-align: center;
}

.history-episode-task.tone-pending span {
  background: rgba(37, 99, 235, 0.1);
  color: #1d4ed8;
}

.history-episode-task.tone-overdue span {
  background: rgba(245, 158, 11, 0.18);
  color: #b45309;
}

.history-episode-task.tone-done span {
  background: rgba(16, 185, 129, 0.14);
  color: #047857;
}

.history-episode-timeline-item {
  display: grid;
  grid-template-columns: 12px minmax(0, 1fr);
  gap: 0.72rem;
  align-items: flex-start;
}

.history-episode-timeline-item strong {
  color: #102033;
}

.history-episode-timeline-item p,
.history-episode-timeline-item span,
.history-legacy-item span {
  display: block;
  margin: 0.22rem 0 0;
  color: #607089;
}

.history-episode-timeline-dot {
  width: 12px;
  height: 12px;
  margin-top: 0.38rem;
  border-radius: 999px;
  background: linear-gradient(135deg, #2563eb, #60a5fa);
  box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
}

.history-episode-more {
  font-size: 0.92rem;
}

.history-legacy-card {
  display: grid;
  gap: 0.85rem;
  padding: 1rem !important;
}

.history-legacy-head span {
  color: #607089;
  font-weight: 800;
}

.history-episode-card.tone-attention {
  background: linear-gradient(180deg, rgba(255, 253, 246, 0.98), rgba(255, 249, 235, 0.96)) !important;
}

.history-episode-card.tone-closed {
  background: linear-gradient(180deg, rgba(249, 251, 255, 0.98), rgba(243, 246, 252, 0.98)) !important;
}

body.theme-dark .history-episodes-hero,
body.theme-dark .history-episodes-controls,
body.theme-dark .history-episode-card,
body.theme-dark .history-legacy-card {
  border-color: rgba(71, 95, 133, 0.84) !important;
  background: linear-gradient(180deg, rgba(13, 20, 33, 0.98), rgba(16, 24, 39, 0.98)) !important;
  box-shadow: 0 20px 42px rgba(2, 6, 23, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.03) !important;
}

body.theme-dark .history-episodes-kicker,
body.theme-dark .history-episode-type,
body.theme-dark .history-episode-panel-head span {
  background: rgba(59, 130, 246, 0.18);
  color: #93c5fd;
}

body.theme-dark .history-episodes-hero-note,
body.theme-dark .history-episodes-stat span,
body.theme-dark .history-episode-summary,
body.theme-dark .history-episode-task p,
body.theme-dark .history-episode-mini-item p,
body.theme-dark .history-episode-empty,
body.theme-dark .history-episode-more,
body.theme-dark .history-episode-timeline-item p,
body.theme-dark .history-episode-timeline-item span,
body.theme-dark .history-legacy-item p,
body.theme-dark .history-legacy-item span,
body.theme-dark .history-legacy-head span,
body.theme-dark .history-episodes-transition p {
  color: rgba(209, 222, 245, 0.78);
}

body.theme-dark .history-episodes-stat,
body.theme-dark .history-episode-highlight,
body.theme-dark .history-episode-panel,
body.theme-dark .history-episode-task,
body.theme-dark .history-episode-mini-item,
body.theme-dark .history-legacy-item,
body.theme-dark .history-episodes-empty {
  border-color: rgba(63, 82, 116, 0.86);
  background: rgba(15, 23, 38, 0.92);
}

body.theme-dark .history-episodes-stat strong,
body.theme-dark .history-episodes-transition h3,
body.theme-dark .history-legacy-head h3,
body.theme-dark .history-episode-title,
