@media (max-width: 980px) {
  .history-explorer-header,
  .history-explorer-shell,
  .history-explorer-stage,
  .history-explorer-bottom-grid,
  .history-explorer-main-head,
  .history-explorer-toolbar-grid {
    grid-template-columns: 1fr;
  }

  .history-explorer-module-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .history-explorer-stage,
  .history-explorer-bottom-grid {
    grid-template-columns: 1fr;
  }

  .history-explorer-header {
    grid-template-columns: 1fr;
    gap: 0.78rem;
    align-items: stretch;
  }

  .history-explorer-header,
  .history-explorer-toolbar,
  .history-explorer-sidebar,
  .history-explorer-main-head,
  .history-explorer-entry-list,
  .history-explorer-detail,
  .history-explorer-support,
  .history-explorer-empty {
    padding: 0.78rem !important;
  }

  .history-explorer-header-stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .history-explorer-module-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .history-explorer-toolbar-row,
  .history-explorer-section-head,
  .history-explorer-support-row,
  .history-explorer-detail-actions,
  .history-explorer-entry-top {
    flex-direction: column;
    align-items: stretch;
  }

  .history-explorer-folder-list {
    display: flex;
    gap: 0.48rem;
    overflow-x: auto;
    padding-bottom: 0.2rem;
  }

  .history-explorer-folder-row {
    min-width: 240px;
  }

  .history-explorer-main-meta {
    justify-content: flex-start;
  }

  .history-explorer-detail-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .history-explorer-header,
  .history-explorer-toolbar,
  .history-explorer-sidebar,
  .history-explorer-main-head,
  .history-explorer-entry-list,
  .history-explorer-detail,
  .history-explorer-support,
  .history-explorer-empty {
    padding: 0.72rem !important;
  }

  .history-explorer-header-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .history-explorer-module-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .history-explorer-folder-row {
    min-width: 210px;
    padding: 0.68rem 0.74rem;
  }

  .history-explorer-entry,
  .history-explorer-detail,
  .history-explorer-support {
    padding: 0.74rem;
  }

  .history-explorer-guidance,
  .history-explorer-entry-meta,
  .history-explorer-detail-summary {
    font-size: 0.79rem;
  }

  .history-explorer-filter {
    min-height: 34px;
  }

  .history-explorer-pill,
  .history-explorer-kicker,
  .history-explorer-folder-type {
    min-height: 26px;
    font-size: 0.68rem;
  }
}

/* Historial: lista de carpetas (nivel 1) */
.history-folder-list {
  display: grid;
  gap: 0.58rem;
  margin-top: 0.94rem;
  padding: 0.96rem;
  background:
    radial-gradient(circle at top right, rgba(59, 130, 246, 0.08), transparent 28%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(248, 251, 255, 0.96) 100%);
}

.history-folder-item {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto auto;
  gap: 0.9rem;
  align-items: start;
  width: 100%;
  padding: 0.92rem 0.96rem;
  border: 1px solid rgba(223, 232, 244, 0.96);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(246, 250, 255, 0.94) 100%);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.04);
  text-align: left;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

.history-folder-item:hover {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 1) 0%, rgba(239, 246, 255, 0.98) 100%);
  border-color: rgba(147, 197, 253, 0.7);
  box-shadow: 0 14px 32px rgba(37, 99, 235, 0.1);
  transform: translateY(-1px);
}

.history-folder-item:focus-visible {
  outline: 2px solid rgba(59, 130, 246, 0.6);
  outline-offset: 2px;
}

.history-folder-item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(219, 234, 254, 0.96) 0%, rgba(239, 246, 255, 0.98) 100%);
  color: #1d4ed8;
  box-shadow: inset 0 0 0 1px rgba(147, 197, 253, 0.4);
