  background: rgba(241, 245, 249, 0.96);
  color: #64748b;
  font-size: 1.08rem;
  line-height: 1;
  font-weight: 700;
  align-self: center;
}

.history-folder-item.tone-closed .history-folder-item-copy strong {
  color: #475569;
}

.history-folder-item.tone-attention .history-folder-item-badge {
  background: rgba(254, 243, 199, 0.96);
  color: #92400e;
}

body.theme-dark .history-folder-item:hover {
  background:
    linear-gradient(180deg, rgba(20, 30, 48, 0.98) 0%, rgba(21, 40, 72, 0.96) 100%);
  border-color: rgba(96, 165, 250, 0.42);
  box-shadow: 0 14px 32px rgba(2, 8, 23, 0.34);
}

body.theme-dark .history-folder-list {
  background:
    radial-gradient(circle at top right, rgba(59, 130, 246, 0.14), transparent 28%),
    linear-gradient(180deg, rgba(15, 23, 38, 0.98) 0%, rgba(12, 20, 32, 0.96) 100%);
}

body.theme-dark .history-folder-item {
  background:
    linear-gradient(180deg, rgba(15, 23, 38, 0.96) 0%, rgba(18, 29, 46, 0.94) 100%);
  border-color: rgba(51, 65, 85, 0.82);
  box-shadow: 0 10px 24px rgba(2, 8, 23, 0.26);
}

body.theme-dark .history-folder-item-icon,
body.theme-dark .history-folder-item-copy strong {
  color: #f1f5f9;
}

body.theme-dark .history-folder-item-icon {
  background: linear-gradient(180deg, rgba(30, 64, 175, 0.34) 0%, rgba(15, 23, 38, 0.9) 100%);
  box-shadow: inset 0 0 0 1px rgba(96, 165, 250, 0.26);
}

body.theme-dark .history-folder-item-copy small {
  color: #cbd5e1;
}

body.theme-dark .history-folder-item-preview,
body.theme-dark .history-folder-item-tag.is-muted {
  color: rgba(209, 222, 245, 0.82);
}

body.theme-dark .history-folder-item-tag {
  background: rgba(30, 41, 59, 0.92);
  color: #cbd5e1;
}

body.theme-dark .history-folder-item-state {
  background: rgba(30, 64, 175, 0.32);
  color: #bfdbfe;
}

body.theme-dark .history-folder-item-state.tone-attention {
  background: rgba(146, 64, 14, 0.34);
  color: #fde68a;
}

body.theme-dark .history-folder-item-state.tone-closed {
  background: rgba(51, 65, 85, 0.96);
  color: #cbd5e1;
}

body.theme-dark .history-folder-item-chevron {
  background: rgba(30, 41, 59, 0.92);
  color: #94a3b8;
}

/* Historial: barra de volver (nivel 2) */
.history-folder-back {
  margin-bottom: 0.72rem;
}

.history-folder-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.34rem;
  padding: 0.54rem 0.88rem;
  border-radius: 12px;
}

.history-folder-back-btn span[aria-hidden="true"] {
  font-size: 1.05rem;
  line-height: 1;
}

/* En la vista interior las 4 tarjetas deben mantenerse en 2 x 2 */
.history-folder-module-grid {
  grid-template-columns: repeat(2, minmax(170px, 1fr));
  gap: 0.72rem;
}

@media (max-width: 768px) {
  .history-folder-list {
    gap: 0.48rem;
    padding: 0.74rem;
  }

  .history-folder-item {
    grid-template-columns: 38px minmax(0, 1fr) auto;
    gap: 0.72rem;
    padding: 0.78rem 0.8rem;
  }

  .history-folder-item-icon {
    width: 38px;
    height: 38px;
    border-radius: 12px;
  }

  .history-folder-item-head {
    gap: 0.56rem;
  }

  .history-folder-item-copy strong {
    font-size: 0.94rem;
  }

  .history-folder-item-preview {
    font-size: 0.79rem;
    -webkit-line-clamp: 2;
  }

  .history-folder-item-meta {
    gap: 0.34rem;
  }

  .history-folder-item-state,
  .history-folder-item-tag,
  .history-folder-item-badge {
    min-height: 26px;
    font-size: 0.7rem;
  }

  .history-folder-item-chevron {
    display: none;
  }

  .history-folder-module-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 520px) {
  .history-folder-item {
    grid-template-columns: 34px minmax(0, 1fr);
    gap: 0.62rem;
    padding: 0.72rem 0.74rem;
  }

  .history-folder-item-icon {
    width: 34px;
    height: 34px;
    border-radius: 11px;
  }

  .history-folder-item-head {
    display: grid;
    gap: 0.3rem;
  }

  .history-folder-item-copy small,
  .history-folder-item-preview {
    font-size: 0.76rem;
  }

  .history-folder-item-preview {
    -webkit-line-clamp: 1;
  }

  .history-folder-item-meta {
    gap: 0.28rem;
  }

  .history-folder-item-tag.is-muted {
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .history-folder-item-badge {
    justify-self: start;
  }

  .history-folder-module-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
/* Desktop shell refinement */
.topbar-main {
  min-width: 0;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.topbar-main > div:first-child {
  min-width: 0;
}

.topbar-highlights {
  display: flex;
  align-items: stretch;
  gap: 0.75rem;
}

.topbar-highlight-card {
  min-width: 180px;
  padding: 0.82rem 0.95rem;
  border-radius: 18px;
  border: 1px solid rgba(191, 219, 254, 0.72);
  background:
    radial-gradient(circle at top right, rgba(68, 196, 255, 0.16), transparent 44%),
    linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 0.16rem;
}

.topbar-highlight-label {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #0284c7;
}

.topbar-highlight-value {
  color: #0f172a;
  font-size: 0.95rem;
  line-height: 1.25;
}

.topbar-highlight-note {
  font-size: 0.78rem;
  color: #64748b;
}

.sidebar-desktop-panel {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  margin-top: 0.9rem;
}

.sidebar-desktop-plan-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.sidebar-desktop-plan-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.28rem 0.68rem;
  border-radius: 999px;
  border: 1px solid rgba(14, 165, 233, 0.18);
  background: linear-gradient(180deg, #eff6ff 0%, #e0f2fe 100%);
  color: #0284c7;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.sidebar-desktop-plan-caption {
  font-size: 0.78rem;
  color: #64748b;
  font-weight: 600;
}

.sidebar-desktop-profile-card {
  border-radius: 22px;
  border: 1px solid rgba(191, 219, 254, 0.82);
  background:
    radial-gradient(circle at top right, rgba(68, 196, 255, 0.18), transparent 38%),
    linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
  padding: 1rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.sidebar-desktop-profile-head {
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

.sidebar-desktop-avatar {
  width: 44px;
  height: 44px;
  border-radius: 15px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  background: linear-gradient(135deg, #2563eb, #44c4ff);
  color: #ffffff;
  font-size: 1rem;
  font-weight: 800;
  box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
}

.sidebar-desktop-profile-copy {
  min-width: 0;
}

.sidebar-desktop-profile-label {
  margin: 0;
  font-size: 0.72rem;
  color: #64748b;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.sidebar-desktop-profile-name {
  margin: 0.2rem 0 0;
  color: #0f172a;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.25;
}

.sidebar-desktop-profile-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.sidebar-desktop-profile-role,
.sidebar-desktop-profile-email {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0.28rem 0.65rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid rgba(219, 234, 254, 0.95);
  color: #475569;
  font-size: 0.74rem;
  font-weight: 600;
}

.sidebar-desktop-profile-select {
  width: 100%;
  min-height: 42px;
  border-radius: 14px;
  border: 1px solid #cbd5e1;
  background: rgba(255, 255, 255, 0.96);
  color: #0f172a;
  font-size: 0.86rem;
  font-weight: 600;
  padding: 0.55rem 0.72rem;
  box-shadow: var(--shadow-xs);
}

.sidebar-desktop-profile-select:disabled {
  opacity: 0.7;
  cursor: wait;
}

.sidebar-desktop-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.sidebar-desktop-metric {
  border-radius: 18px;
  border: 1px solid rgba(226, 232, 240, 0.95);
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  box-shadow: var(--shadow-xs);
  padding: 0.8rem 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.18rem;
}

.sidebar-desktop-metric-value {
  color: #0f172a;
  font-size: 1.2rem;
  font-weight: 800;
  line-height: 1;
}

.sidebar-desktop-metric-label {
  color: #64748b;
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.sidebar-section-label {
  padding: 0.2rem 0.95rem 0.3rem;
  color: #2563eb;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.sidebar-desktop-footer {
  margin-top: auto;
  padding-top: 1rem;
}

.sidebar-desktop-settings-link {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0.95rem 1rem;
  text-decoration: none;
  border-radius: 20px;
  border: 1px solid rgba(226, 232, 240, 0.92);
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  color: #0f172a;
  box-shadow: var(--shadow-xs);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.sidebar-desktop-settings-link:hover {
  transform: translateY(-1px);
  border-color: #93c5fd;
  box-shadow: var(--shadow-sm);
}

.sidebar-desktop-settings-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.sidebar-desktop-settings-title {
  color: #0f172a;
  font-size: 0.88rem;
  font-weight: 700;
}

.sidebar-desktop-settings-subtitle {
  color: #64748b;
  font-size: 0.76rem;
  line-height: 1.35;
}

@media (max-width: 1023px) {
  .topbar-highlights,
  .sidebar-desktop-panel,
  .sidebar-section-label,
  .sidebar-desktop-footer {
    display: none;
  }
}

@media (min-width: 1024px) {
  .sidebar {
    width: 292px;
    padding: 1.1rem 1rem 1rem;
  }

  .sidebar-brand {
    justify-content: flex-start;
    padding: 0.3rem 0.35rem 1rem;
  }

  .brand-wordmark-sidebar {
    justify-content: flex-start;
    font-size: 1.18rem;
  }

  .sidebar-nav {
    flex: 1;
    gap: 0.35rem;
    margin-top: 1rem;
  }

  .sidebar-link {
    justify-content: flex-start;
    padding: 0.92rem 1rem;
    border-radius: 18px;
  }

  .sidebar-label {
    width: auto;
    opacity: 1;
    overflow: visible;
    font-size: 0.94rem;
    font-weight: 600;
  }

  .sidebar-tooltip {
    display: none;
  }

  .sidebar-badge {
    top: 10px;
    right: 10px;
  }

  .main-area {
    margin-left: 292px;
    background:
      radial-gradient(circle at top left, rgba(68, 196, 255, 0.08), transparent 18%),
      linear-gradient(180deg, #f8fbff 0%, #f8fafc 100%);
  }

  .main-content {
    max-width: 1480px;
    padding: 1.35rem 1.45rem 1.8rem;
    background: transparent;
  }

  .topbar {
    align-items: flex-start;
    padding: 1rem 1.15rem;
    margin-bottom: 1.2rem;
    border-radius: 22px;
  }

  .topbar-label {
    font-size: 0.78rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .topbar-row {
    gap: 0.8rem;
    flex-wrap: wrap;
  }

  .topbar-title {
    margin-top: 0.16rem;
    font-size: 1.42rem;
    line-height: 1.15;
  }

  .topbar-chip {
    padding: 0.3rem 0.68rem;
    font-size: 0.76rem;
  }

  .topbar-actions {
    gap: 0.6rem;
    align-self: center;
    padding-left: 1rem;
  }

  .topbar-quick {
    padding: 0.45rem 0.78rem;
    border-radius: 12px;
  }

  .topbar-user {
    padding: 0.34rem 0.68rem 0.34rem 0.34rem;
    border-radius: 16px;
  }

  .topbar-avatar {
    width: 34px;
    height: 34px;
    border-radius: 12px;
  }

  .topbar-name {
    font-size: 0.9rem;
  }
}

body.theme-dark .topbar-highlight-card,
