/* Brand logo rollout */
.brand-logo {
  display: inline-flex;
  align-items: center;
  gap: 0.72rem;
  min-width: 0;
}

.brand-logo-mark {
  width: 42px;
  height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  overflow: visible;
}

.brand-logo-img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  backface-visibility: hidden;
  image-rendering: auto;
}

.brand-logo-name {
  display: inline-block;
  min-width: 0;
  line-height: 1;
  color: inherit;
}

.brand-logo-sidebar {
  gap: 0.78rem;
}

.brand-logo-sidebar-mark {
  width: 42px;
  height: 42px;
}

.brand-logo-sidebar-name {
  font-size: 1.12rem;
  font-weight: 800;
  letter-spacing: -0.04em;
}

.brand-mark-nav {
  width: 100%;
  height: 100%;
}

.brand-mark-nav-img {
  width: 100%;
  height: 100%;
}

.sidebar-icon .brand-logo-mark,
.sidebar-link.is-mobile-ai .brand-logo-mark {
  width: 100%;
  height: 100%;
}

.auth-logo-text.brand-logo-auth {
  gap: 0.85rem;
  align-items: center;
  justify-content: center;
}

.brand-logo-auth-mark {
  width: 60px;
  height: 60px;
}

.brand-logo-auth-name {
  font-size: inherit;
  font-weight: 800;
  letter-spacing: -0.05em;
}

.brand-logo-landing,
.brand-logo-plans {
  gap: 0.7rem;
}

.brand-logo-keep-name-mobile .brand-logo-name {
  display: inline-block;
}

.brand-logo-plans-mark {
  width: 44px;
  height: 44px;
}

.pp-footer-name.brand-logo,
.lp-footer-brand .brand-logo {
  margin-bottom: 0.18rem;
}

.splash-brand-core {
  width: 74px;
  height: 74px;
  border-radius: 24px;
  background: transparent;
  box-shadow: none;
  animation: splashFloat 2.8s ease-in-out infinite;
  display: grid;
  place-items: center;
}

.splash-brand-core-glow {
  display: none;
}

.splash-brand-core-logo {
  width: 100%;
  height: 100%;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 18px 28px rgba(37, 99, 235, 0.2);
}

.splash-brand-core-logo-img {
  width: 132%;
  height: 132%;
  max-width: none;
  max-height: none;
  object-fit: cover;
