@media (max-width: 640px) {
  .brand-logo.responsive .brand-logo-name {
    display: none;
  }

  .brand-logo.brand-logo-keep-name-mobile .brand-logo-name {
    display: inline-block;
  }

  .brand-logo-sidebar-mark {
    width: 36px;
    height: 36px;
  }

  .auth-logo-text.brand-logo-auth {
    gap: 0.72rem;
  }

  .brand-logo-auth-mark {
    width: 52px;
    height: 52px;
  }
}
